export default "(self, checkpoint_id: str) -> None:\\n        self._checkpoints.pop(checkpoint_id, None)\\n\\n    async def load_by_run_id(self, run_id: str) -> GraphCheckpoint | None:\\n        candidates = [cp for cp in self._checkpoints.values() if cp.run_id == run_id and not _expired(cp)]\\n        if not candidates:\\n            return None\\n        return max(candidates, key=lambda cp: cp.created_at)\\n\\n    async def list_by_session(self, session_id: str) -> list[GraphCheckpoint]:\\n        return [cp for cp in self._checkpoints.values() if cp.session_id == session_id and not _expired(cp)]\\n\\n\\n_default_store: CheckpointStore | None = None\\n\\n\\ndef default_checkpoint_store() -> CheckpointStore:\\n    \\\"\\\"\\\"Module-singleton fallback store for standalone lfx (no service registry).\\\"\\\"\\\"\\n    global _default_store  # noqa: PLW0603\\n    if _default_store is None:\\n        _default_store = InMemoryCheckpointStore()\\n    return _default_store\\n\\n\\ndef set_default_checkpoint_store(store: CheckpointStore | None) -> None:\\n    \\\"\\\"\\\"Replace the standalone fallback store (e.g. serve's durable SQLite store).\\n\\n    Blob consumers resolve through ``get_checkpoint_service`` \u2192 this fallback, so a\\n    durable host must install its store here or agent pause blobs stay in-memory\\n    and do not survive a restart. ``None`` resets to a fresh in-memory store.\\n    \\\"\\\"\\\"\\n    global _default_store  # noqa: PLW0603\\n    _default_store = store\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/edge/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/edge/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c7297a86b1be54701d93e0e7536a54b69d80987ab672e022632d68f4e4b2044a\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any, cast\\n\\nfrom lfx.graph.edge.schema import EdgeData, LoopTargetHandleDict, SourceHandle, TargetHandle, TargetHandleDict\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.schema import INPUT_FIELD_NAME\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.vertex.base import Vertex\\n\\n# Type migrations for backward compatibility\\n# Maps old type names to new type names\\nTYPE_MIGRATIONS: dict[str, str] = {\\n    \\\"Data\\\": \\\"JSON\\\",\\n    \\\"DataFrame\\\": \\\"Table\\\",\\n}\\n\\n\\ndef types_compatible(output_types: list[str], input_types: list[str]) -> bool:\\n    \\\"\\\"\\\"Check if output types are compatible with input types, considering type migrations.\\n\\n    Args:\\n        output_types: List of output type names from source handle\\n        input_types: List of input type names from target handle\\n\\n    Returns:\\n        True if any output type matches any input type (directly or via migration)\\n    \\\"\\\"\\\"\\n    for output_type in output_types:\\n        # Get the migrated version of the output type\\n        migrated_output = TYPE_MIGRATIONS.get(output_type, output_type)\\n\\n        for input_type in input_types:\\n            # Get the migrated version of the input type\\n            migrated_input = TYPE_MIGRATIONS.get(input_type, input_type)\\n\\n            # Check all possible combinations using sets for cleaner comparison\\n            if input_type in {output_type, migrated_output} or migrated_input in {output_type, migrated_output}:\\n                return True\\n    return False\\n\\n\\nclass Edge:\\n    def __init__(self, source: Vertex, target: Vertex, edge: EdgeData):\\n        self.source_id: str = source.id if source else \\\"\\\"\\n        self.target_id: str = target.id if target else \\\"\\\"\\n        self.valid_handles: bool = False\\n        self.target_param: str | None = None\\n        self._target_handle: TargetHandleDict | str | None = None\\n        self._data = edge.copy()\\n        self.is_cycle = False\\n        if data := edge.get(\\\"data\\\", {}):\\n            self._source_handle = data.get(\\\"sourceHandle\\\", {})\\n            self._target_handle = cast(\\\"TargetHandleDict\\\", data.get(\\\"targetHandle\\\", {}))\\n            self.source_handle: SourceHandle = SourceHandle(**self._source_handle)\\n            if isinstance(self._target_handle, dict):\\n                try:\\n                    if \\\"name\\\" in self._target_handle:\\n                        self.target_handle: TargetHandle = TargetHandle.from_loop_target_handle(\\n                            cast(\\\"LoopTargetHandleDict\\\", self._target_handle)\\n                        )\\n                    else:\\n                        self.target_handle = TargetHandle(**self._target_handle)\\n                except Exception as e:\\n                    if \\\"inputTypes\\\" in self._target_handle and self._target_handle[\\\"inputTypes\\\"] is None:\\n                        # Check if self._target_handle['fieldName']\\n                        if hasattr(target, \\\"custom_component\\\"):\\n                            display_name = getattr(target.custom_component, \\\"display_name\\\", \\\"\\\")\\n                            msg = (\\n                                f\\\"Component {display_name} field '{self._target_handle['fieldName']}' \\\"\\n                                \\\"might not be a valid input.\\\"\\n                            )\\n                            raise ValueError(msg) from e\\n                        msg = (\\n                            f\\\"Field '{self._target_handle['fieldName']}' on {target.display_name} \\\"\\n                            \\\"might not be a valid input.\\\"\\n                        )\\n                        raise ValueError(msg) from e\\n                    raise\\n\\n            else:\\n                msg = \\\"Target handle is not a dictionary\\\"\\n                raise ValueError(msg)\\n            self.target_param = self.target_handle.field_name\\n            # validate handles\\n            self.validate_handles(source, target)\\n        else:\\n            # Logging here because this is a breaking change\\n            logger.error(\\\"Edge data is empty\\\")\\n            self._source_handle = edge.get(\\\"sourceHandle\\\", \\\"\\\")  # type: ignore[assignment]\\n            self._target_handle = edge.get(\\\"targetHandle\\\", \\\"\\\")  # type: ignore[assignment]\\n            # 'BaseLoader;BaseOutputParser|documents|PromptTemplate-zmTlD'\\n            # target_param is documents\\n            if isinstance(self._target_handle, str):\\n                self.target_param = self._target_handle.split(\\\"|\\\")[1]\\n                self.source_handle = None  # type: ignore[assignment]\\n                self.target_handle = None  # type: ignore[assignment]\\n            else:\\n                msg = \\\"Target handle is not a string\\\"\\n                raise ValueError(msg)\\n        # Validate in __init__ to fail fast\\n        self.validate_edge(source, target)\\n\\n    def to_data(self):\\n        return self._data\\n\\n    def validate_handles(self, source, target) -> None:\\n        if isinstance(self._source_handle, str) or self.source_handle.base_classes:\\n            self._legacy_validate_handles(source, target)\\n        else:\\n            self._validate_handles(source, target)\\n\\n    def _validate_handles(self, source, target) -> None:\\n        if self.target_handle.input_types is None:\\n            # Backward compatibility: old flows may have Data/DataFrame types\\n            self.valid_handles = types_compatible(\\n                self.source_handle.output_types, [self.target_handle.type] if self.target_handle.type else []\\n            )\\n        elif self.target_handle.type is None:\\n            # ! This is not a good solution\\n            # This is a loop edge\\n            # If the target_handle.type is None, it means it's a loop edge\\n            # and we should check if the source_handle.output_types is not empty\\n            # and if the target_handle.input_types is empty or if any of the source_handle.output_types\\n            # is in the target_handle.input_types\\n            self.valid_handles = bool(self.source_handle.output_types) and (\\n                not self.target_handle.input_types\\n                or types_compatible(self.source_handle.output_types, self.target_handle.input_types)\\n            )\\n\\n        elif self.source_handle.output_types is not None:\\n            # Backward compatibility: old flows may have Data/DataFrame types\\n            self.valid_handles = types_compatible(\\n                self.source_handle.output_types, self.target_handle.input_types\\n            ) or types_compatible(\\n                self.source_handle.output_types, [self.target_handle.type] if self.target_handle.type else []\\n            )\\n\\n        if not self.valid_handles:\\n            logger.debug(self.source_handle)\\n            logger.debug(self.target_handle)\\n            msg = f\\\"Edge between {source.display_name} and {target.display_name} has invalid handles\\\"\\n            raise ValueError(msg)\\n\\n    def _legacy_validate_handles(self, source, target) -> None:\\n        if self.target_handle.input_types is None:\\n            # Backward compatibility: old flows may have Data/DataFrame types\\n            self.valid_handles = types_compatible(\\n                self.source_handle.base_classes, [self.target_handle.type] if self.target_handle.type else []\\n            )\\n        else:\\n            # Backward compatibility: old flows may have Data/DataFrame types\\n            self.valid_handles = types_compatible(\\n                self.source_handle.base_classes, self.target_handle.input_types\\n            ) or types_compatible(\\n                self.source_handle.base_classes, [self.target_handle.type] if self.target_handle.type else []\\n            )\\n        if not self.valid_handles:\\n            logger.debug(self.source_handle)\\n            logger.debug(self.target_handle)\\n            msg = f\\\"Edge between {source.vertex_type} and {target.vertex_type} has invalid handles\\\"\\n            raise ValueError(msg)\\n\\n    def __setstate__(self, state):\\n        self.source_id = state[\\\"source_id\\\"]\\n        self.target_id = state[\\\"target_id\\\"]\\n        self.target_param = state[\\\"target_param\\\"]\\n        self.source_handle = state.get(\\\"source_handle\\\")\\n        self.target_handle = state.get(\\\"target_handle\\\")\\n        self._source_handle = state.get(\\\"_source_handle\\\")\\n        self._target_handle = state.get(\\\"_target_handle\\\")\\n        self._data = state.get(\\\"_data\\\")\\n        self.valid_handles = state.get(\\\"valid_handles\\\")\\n        self.source_types = state.get(\\\"source_types\\\")\\n        self.target_reqs = state.get(\\\"target_reqs\\\")\\n        self.matched_type = state.get(\\\"matched_type\\\")\\n\\n    def validate_edge(self, source, target) -> None:\\n        # If the self.source_handle has base_classes, then we are using the legacy\\n        # way of defining the source and target handles\\n        if isinstance(self._source_handle, str) or self.source_handle.base_classes:\\n            self._legacy_validate_edge(source, target)\\n        else:\\n            self._validate_edge(source, target)\\n\\n    def _validate_edge(self, source, target) -> None:\\n        # Validate that the outputs of the source node are valid inputs\\n        # for the target node\\n        # .outputs is a list of Output objects as dictionaries\\n        # meaning: check for \\\"types\\\" key in each dictionary\\n        self.source_types = [output for output in source.outputs if output[\\\"name\\\"] == self.source_handle.name]\\n\\n        # Check if this is an loop input (loop target handle with output_types)\\n        is_loop_input = hasattr(self.target_handle, \\\"input_types\\\") and self.target_handle.input_types\\n        loop_input_types = []\\n\\n        if is_loop_input:\\n            # For loop inputs, use the configured input_types\\n            # (which already includes original type + loop_types from frontend)\\n            loop_input_types = list(self.target_handle.input_types)\\n            # Backward compatibility: old flows may have Data/DataFrame types\\n            self.valid = any(types_compatible(output[\\\"types\\\"], loop_input_types) for output in self.source_types)\\n            # Find the first matching type (considering migrations)\\n            self.matched_type = next(\\n                (\\n                    output_type\\n                    for output in self.source_types\\n                    for output_type in output[\\\"types\\\"]\\n                    if types_compatible([output_type], loop_input_types)\\n                ),\\n                None,\\n            )\\n        else:\\n            # Standard validation for regular inputs\\n            self.target_reqs = target.required_inputs + target.optional_inputs\\n            # Both lists contain strings and sometimes a string contains the value we are\\n            # looking for e.g. comgin_out=[\\\"Chain\\\"] and target_reqs=[\\\"LLMChain\\\"]\\n            # so we need to check if any of the strings in source_types is in target_reqs\\n            # Backward compatibility: old flows may have Data/DataFrame types\\n            self.valid = any(types_compatible(output[\\\"types\\\"], self.target_reqs) for output in self.source_types)\\n            # Update the matched type to be the first found match (considering migrations)\\n            self.matched_type = next(\\n                (\\n                    output_type\\n                    for output in self.source_types\\n                    for output_type in output[\\\"types\\\"]\\n                    if types_compatible([output_type], self.target_reqs)\\n                ),\\n                None,\\n            )\\n\\n        no_matched_type = self.matched_type is None\\n        if no_matched_type:\\n            logger.debug(self.source_types)\\n            logger.debug(self.target_reqs if not is_loop_input else loop_input_types)\\n            msg = f\\\"Edge between {source.vertex_type} and {target.vertex_type} has no matched type.\\\"\\n            raise ValueError(msg)\\n\\n    def _legacy_validate_edge(self, source, target) -> None:\\n        # Validate that the outputs of the source node are valid inputs\\n        # for the target node\\n        self.source_types = source.output\\n        self.target_reqs = target.required_inputs + target.optional_inputs\\n        # Both lists contain strings and sometimes a string contains the value we are\\n        # looking for e.g. comgin_out=[\\\"Chain\\\"] and target_reqs=[\\\"LLMChain\\\"]\\n        # so we need to check if any of the strings in source_types is in target_reqs\\n        # Use types_compatible for migration support\\n        self.valid = types_compatible(self.source_types, self.target_reqs)\\n        # Get what type of input the target node is expecting (considering migrations)\\n\\n        self.matched_type = next(\\n            (output for output in self.source_types if types_compatible([output], self.target_reqs)),\\n            None,\\n        )\\n        no_matched_type = self.matched_type is None\\n        if no_matched_type:\\n            logger.debug(self.source_types)\\n            logger.debug(self.target_reqs)\\n            msg = f\\\"Edge between {source.vertex_type} and {target.vertex_type} has no matched type\\\"\\n            raise ValueError(msg)\\n\\n    def __repr__(self) -> str:\\n        if (hasattr(self, \\\"source_handle\\\") and self.source_handle) and (\\n            hasattr(self, \\\"target_handle\\\") and self.target_handle\\n        ):\\n            return f\\\"{self.source_id} -[{self.source_handle.name}->{self.target_handle.field_name}]-> {self.target_id}\\\"\\n        return f\\\"{self.source_id} -[{self.target_param}]-> {self.target_id}\\\"\\n\\n    def __hash__(self) -> int:\\n        return hash(self.__repr__())\\n\\n    def __eq__(self, /, other: object) -> bool:\\n        if not isinstance(other, Edge):\\n            return False\\n        return (\\n            self._source_handle == other._source_handle\\n            and self._target_handle == other._target_handle\\n            and self.target_param == other.target_param\\n        )\\n\\n    def __str__(self) -> str:\\n        return self.__repr__()\\n\\n\\nclass CycleEdge(Edge):\\n    def __init__(self, source: Vertex, target: Vertex, raw_edge: EdgeData):\\n        super().__init__(source, target, raw_edge)\\n        self.is_fulfilled = False  # Whether the contract has been fulfilled.\\n        self.result: Any = None\\n        self.is_cycle = True\\n        source.has_cycle_edges = True\\n        target.has_cycle_edges = True\\n\\n    async def honor(self, source: Vertex, target: Vertex) -> None:\\n        \\\"\\\"\\\"Fulfills the contract by setting the result of the source vertex to the target vertex's parameter.\\n\\n        If the edge is runnable, the source vertex is run with the message text and the target vertex's\\n        root_field param is set to the\\n        result. If the edge is not runnable, the target vertex's parameter is set to the result.\\n        :param message: The message object to be processed if the edge is runnable.\\n        \\\"\\\"\\\"\\n        if self.is_fulfilled:\\n            return\\n\\n        if not source.built:\\n            # The system should be read-only, so we should not be building vertices\\n            # that are not already built.\\n            msg = f\\\"Source vertex {source.id} is not built.\\\"\\n            raise ValueError(msg)\\n\\n        if self.matched_type == \\\"Text\\\":\\n            self.result = source.built_result\\n        else:\\n            self.result = source.built_object\\n\\n        target.params[self.target_param] = self.result\\n        self.is_fulfilled = True\\n\\n    async def get_result_from_source(self, source: Vertex, target: Vertex):\\n        # Fulfill the contract if it has not been fulfilled.\\n        if not self.is_fulfilled:\\n            await self.honor(source, target)\\n\\n        # If the target vertex is a power component we log messages\\n        if (\\n            target.vertex_type == \\\"ChatOutput\\\"\\n            and isinstance(target.params.get(INPUT_FIELD_NAME), str | dict)\\n            and target.params.get(\\\"message\\\") == \\\"\\\"\\n        ):\\n            return self.result\\n        return self.result\\n\\n    def __repr__(self) -> str:\\n        str_repr = super().__repr__()\\n        # Add a symbol to show this is a cycle edge\\n        return f\\\"{str_repr} \ud83d\udd04\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/edge/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6ca969af1ca6795d386d3330de30cba58400037791738048743ffee171865377\",\"content\":\"from typing import Any\\n\\nfrom pydantic import ConfigDict, Field, field_validator\\nfrom typing_extensions import TypedDict\\n\\nfrom lfx.helpers.base_model import BaseModel\\n\\n\\nclass SourceHandleDict(TypedDict, total=False):\\n    baseClasses: list[str]\\n    dataType: str\\n    id: str\\n    name: str | None\\n    output_types: list[str]\\n\\n\\nclass TargetHandleDict(TypedDict):\\n    fieldName: str\\n    id: str\\n    inputTypes: list[str] | None\\n    type: str\\n\\n\\nclass LoopTargetHandleDict(TypedDict):\\n    dataType: str\\n    id: str\\n    name: str\\n    output_types: list[str]\\n\\n\\nclass EdgeDataDetails(TypedDict):\\n    sourceHandle: SourceHandleDict\\n    targetHandle: TargetHandleDict | LoopTargetHandleDict\\n\\n\\nclass EdgeData(TypedDict, total=False):\\n    source: str\\n    target: str\\n    data: EdgeDataDetails\\n\\n\\nclass ResultPair(BaseModel):\\n    result: Any\\n    extra: Any\\n\\n\\nclass Payload(BaseModel):\\n    result_pairs: list[ResultPair] = []\\n\\n    def __iter__(self):\\n        return iter(self.result_pairs)\\n\\n    def add_result_pair(self, result: Any, extra: Any | None = None) -> None:\\n        self.result_pairs.append(ResultPair(result=result, extra=extra))\\n\\n    def get_last_result_pair(self) -> ResultPair:\\n        return self.result_pairs[-1]\\n\\n    # format all but the last result pair\\n    # into a string\\n    def format(self, sep: str = \\\"\\\\n\\\") -> str:\\n        # Result: the result\\n        # Extra: the extra if it exists don't show if it doesn't\\n        return sep.join(\\n            [\\n                f\\\"Result: {result_pair.result}\\\\nExtra: {result_pair.extra}\\\"\\n                if result_pair.extra is not None\\n                else f\\\"Result: {result_pair.result}\\\"\\n                for result_pair in self.result_pairs[:-1]\\n            ]\\n        )\\n\\n\\nclass TargetHandle(BaseModel):\\n    model_config = ConfigDict(populate_by_name=True)\\n    field_name: str = Field(..., alias=\\\"fieldName\\\", description=\\\"Field name for the target handle.\\\")\\n    id: str = Field(..., description=\\\"Unique identifier for the target handle.\\\")\\n    input_types: list[str] = Field(\\n        default_factory=list, alias=\\\"inputTypes\\\", description=\\\"List of input types for the target handle.\\\"\\n    )\\n    type: str = Field(None, description=\\\"Type of the target handle.\\\")\\n\\n    @classmethod\\n    def from_loop_target_handle(cls, target_handle: LoopTargetHandleDict) -> \\\"TargetHandle\\\":\\n        # The target handle is a loop edge\\n        # The target handle is a dict with the following keys:\\n        # - name: str\\n        # - id: str\\n        # - inputTypes: list[str]\\n        # - type: str\\n        # It is built from an Output, which is why it has a different structure\\n        return cls(\\n            field_name=target_handle.get(\\\"name\\\"),\\n            id=target_handle.get(\\\"id\\\"),\\n            input_types=target_handle.get(\\\"output_types\\\"),\\n        )\\n\\n\\nclass SourceHandle(BaseModel):\\n    model_config = ConfigDict(populate_by_name=True)\\n    base_classes: list[str] = Field(\\n        default_factory=list, alias=\\\"baseClasses\\\", description=\\\"List of base classes for the source handle.\\\"\\n    )\\n    data_type: str = Field(..., alias=\\\"dataType\\\", description=\\\"Data type for the source handle.\\\")\\n    id: str = Field(..., description=\\\"Unique identifier for the source handle.\\\")\\n    name: str | None = Field(None, description=\\\"Name of the source handle.\\\")\\n    output_types: list[str] = Field(default_factory=list, description=\\\"List of output types for the source handle.\\\")\\n\\n    @field_validator(\\\"name\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_name(cls, v, info):\\n        if info.data[\\\"data_type\\\"] == \\\"GroupNode\\\":\\n            # 'OpenAIModel-u4iGV_text_output'\\n            splits = v.split(\\\"_\\\", 1)\\n            if len(splits) != 2:  # noqa: PLR2004\\n                msg = f\\\"Invalid source handle name {v}\\\"\\n                raise ValueError(msg)\\n            v = splits[1]\\n        return v\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/edge/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/exceptions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"af987aafcceecf09d8879086fb4c989f98cd0ed187ccde4102919ae61145a045\",\"content\":\"\\\"\\\"\\\"Graph-level control-flow exceptions.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\n\\n\\nclass GraphPausedException(Exception):  # noqa: N818\\n    \\\"\\\"\\\"Raised when a run suspends at a safe boundary after persisting a checkpoint.\\n\\n    This is control flow, not a failure: callers must let it propagate unwrapped\\n    past generic error handlers so the run is finalized as suspended, never failed.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, checkpoint_id: str, reason: str, data: dict[str, Any] | None = None) -> None:\\n        self.checkpoint_id = checkpoint_id\\n        self.reason = reason\\n        self.data = data or {}\\n        super().__init__(f\\\"Graph paused ({reason}); checkpoint {checkpoint_id}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/flow_builder/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"560e7c335efbc4c7ab1bcd49323ad9cc0f5e45ef023f41637dd3e0719a96c831\",\"content\":\"\\\"\\\"\\\"Pure flow-building utilities for constructing Langflow flows programmatically.\\n\\nAll functions operate on plain dicts \u2014 no I/O, no network, no global state.\\n\\\"\\\"\\\"\\n\\nfrom lfx.graph.flow_builder.component import (\\n    add_component,\\n    configure_component,\\n    get_component,\\n    list_components,\\n    needs_server_update,\\n    remove_component,\\n)\\nfrom lfx.graph.flow_builder.connect import (\\n    add_connection,\\n    ensure_tool_mode_supported,\\n    list_connections,\\n    remove_connection,\\n)\\nfrom lfx.graph.flow_builder.flow import empty_flow, flow_graph_repr, flow_info, flow_to_spec_summary\\nfrom lfx.graph.flow_builder.layout import layout_flow\\nfrom lfx.graph.flow_builder.spec import parse_flow_spec\\n\\n__all__ = [\\n    \\\"add_component\\\",\\n    \\\"add_connection\\\",\\n    \\\"configure_component\\\",\\n    \\\"empty_flow\\\",\\n    \\\"ensure_tool_mode_supported\\\",\\n    \\\"flow_graph_repr\\\",\\n    \\\"flow_info\\\",\\n    \\\"flow_to_spec_summary\\\",\\n    \\\"get_component\\\",\\n    \\\"layout_flow\\\",\\n    \\\"list_components\\\",\\n    \\\"list_connections\\\",\\n    \\\"needs_server_update\\\",\\n    \\\"parse_flow_spec\\\",\\n    \\\"remove_component\\\",\\n    \\\"remove_connection\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/flow_builder/_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6b8c3c17f0a63799ab423aab43324d09fc07ec616efed09062b7cf821097ad19\",\"content\":\"\\\"\\\"\\\"Shared utilities for flow_builder modules.\\n\\nExtracted here to avoid duplicating helpers across component.py, layout.py,\\nand other flow_builder modules that need the same node-level operations.\\n\\\"\\\"\\\"\\n\\n\\ndef node_id(node: dict) -> str:\\n    \\\"\\\"\\\"Extract the node ID from a node dict.\\n\\n    Nodes store their ID in node[\\\"data\\\"][\\\"id\\\"], falling back to node[\\\"id\\\"].\\n    This was duplicated in component.py and layout.py -- consolidated here\\n    so both import from one place.\\n    \\\"\\\"\\\"\\n    return node.get(\\\"data\\\", {}).get(\\\"id\\\", node.get(\\\"id\\\", \\\"\\\"))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/flow_builder/builder.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8ac31c515a1c2f6324ca7c4cfa3a2019ad00cd71f8172fd3788754d75d3507a4\",\"content\":\"\\\"\\\"\\\"Build a complete flow from a text spec using the local component registry.\\n\\nThe component registry is loaded from a bundled index file and cached\\nat module level. No network access or running server required.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom pathlib import Path\\nfrom typing import Any\\n\\nfrom lfx.graph.flow_builder.component import add_component, configure_component, sync_dropdown_selected_outputs\\nfrom lfx.graph.flow_builder.connect import add_connection\\nfrom lfx.graph.flow_builder.flow import empty_flow\\nfrom lfx.graph.flow_builder.layout import layout_flow\\nfrom lfx.graph.flow_builder.spec import parse_flow_spec, validate_spec_references\\nfrom lfx.log.logger import logger\\n\\n_INDEX_PATH = Path(__file__).resolve().parent.parent.parent / \\\"_assets\\\" / \\\"component_index.json\\\"\\n_registry_cache: dict[str, dict] | None = None\\n\\n\\ndef load_local_registry() -> dict[str, dict]:\\n    \\\"\\\"\\\"Load the component registry from the bundled index file.\\n\\n    Returns a flat dict: {component_type: template_dict}.\\n    Results are cached after the first call.\\n\\n    Raises:\\n        RuntimeError: If the index file is missing, corrupt, or empty.\\n    \\\"\\\"\\\"\\n    global _registry_cache  # noqa: PLW0603\\n    if _registry_cache is not None:\\n        return _registry_cache\\n\\n    try:\\n        with _INDEX_PATH.open(encoding=\\\"utf-8\\\") as f:\\n            data = json.load(f)\\n    except FileNotFoundError:\\n        msg = f\\\"Component registry not found at {_INDEX_PATH}. The lfx package may be installed incorrectly.\\\"\\n        raise RuntimeError(msg) from None\\n    except (json.JSONDecodeError, OSError) as e:\\n        msg = f\\\"Failed to load component registry from {_INDEX_PATH}: {e}\\\"\\n        raise RuntimeError(msg) from e\\n\\n    registry: dict[str, dict] = {}\\n    for cat in data.get(\\\"entries\\\", []):\\n        if isinstance(cat, list) and len(cat) > 1 and isinstance(cat[1], dict):\\n            category_name = cat[0] if isinstance(cat[0], str) else \\\"\\\"\\n            for name, comp_data in cat[1].items():\\n                if isinstance(comp_data, dict) and \\\"template\\\" in comp_data:\\n                    registry[name] = {**comp_data, \\\"category\\\": category_name}\\n\\n    if not registry:\\n        msg = f\\\"Component registry at {_INDEX_PATH} contains no valid components.\\\"\\n        raise RuntimeError(msg)\\n\\n    logger.debug(\\\"Loaded %d components from local registry\\\", len(registry))\\n    _registry_cache = registry\\n    return registry\\n\\n\\ndef build_flow_from_spec(\\n    spec: str,\\n    registry: dict[str, dict] | None = None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Build a flow dict from a text spec. Returns the flow or errors.\\n\\n    The ``registry`` argument lets callers (notably the MCP flow-builder\\n    tools) inject a user-aware registry overlay \u2014 base components plus\\n    Components the calling user has registered into their sandbox. When\\n    omitted, falls back to the bundled base registry only.\\n\\n    On success: {\\\"flow\\\": <flow_dict>, \\\"name\\\": str, \\\"node_count\\\": int, \\\"edge_count\\\": int}\\n    On failure: {\\\"error\\\": str, \\\"details\\\": str}\\n    \\\"\\\"\\\"\\n    if registry is None:\\n        registry = load_local_registry()\\n\\n    try:\\n        parsed = parse_flow_spec(spec)\\n    except ValueError as e:\\n        return {\\\"error\\\": \\\"Invalid spec\\\", \\\"details\\\": str(e)}\\n\\n    # Validate that all component types exist in the registry\\n    unknown = [n[\\\"type\\\"] for n in parsed[\\\"nodes\\\"] if n[\\\"type\\\"] not in registry]\\n    if unknown:\\n        return {\\n            \\\"error\\\": f\\\"Unknown component types: {unknown}\\\",\\n            \\\"details\\\": f\\\"Available types (sample): {sorted(registry.keys())[:30]}\\\",\\n        }\\n\\n    # Validate node references in edges and config\\n    try:\\n        validate_spec_references(parsed)\\n    except ValueError as e:\\n        return {\\\"error\\\": str(e), \\\"details\\\": str(e)}\\n\\n    # Build the flow\\n    flow = empty_flow(\\n        name=parsed.get(\\\"name\\\", \\\"Untitled Flow\\\"),\\n        description=parsed.get(\\\"description\\\", \\\"\\\"),\\n    )\\n\\n    id_map: dict[str, str] = {}\\n\\n    # Add components\\n    for node in parsed[\\\"nodes\\\"]:\\n        try:\\n            result = add_component(flow, node[\\\"type\\\"], registry)\\n        except (ValueError, KeyError) as e:\\n            return {\\\"error\\\": f\\\"Failed to add component '{node['type']}' (node '{node['id']}')\\\", \\\"details\\\": str(e)}\\n        id_map[node[\\\"id\\\"]] = result[\\\"id\\\"]\\n\\n    # Apply config\\n    for spec_id, params in parsed.get(\\\"config\\\", {}).items():\\n        try:\\n            configure_component(flow, id_map[spec_id], params)\\n        except (ValueError, KeyError) as e:\\n            return {\\\"error\\\": f\\\"Failed to configure node '{spec_id}'\\\", \\\"details\\\": str(e)}\\n\\n    # Connect edges\\n    for edge in parsed[\\\"edges\\\"]:\\n        src_out = f\\\"{edge['source_id']}.{edge['source_output']}\\\"\\n        tgt_in = f\\\"{edge['target_id']}.{edge['target_input']}\\\"\\n        try:\\n            add_connection(\\n                flow,\\n                id_map[edge[\\\"source_id\\\"]],\\n                edge[\\\"source_output\\\"],\\n                id_map[edge[\\\"target_id\\\"]],\\n                edge[\\\"target_input\\\"],\\n                registry=registry,\\n            )\\n        except (ValueError, KeyError) as e:\\n            return {\\\"error\\\": f\\\"Failed to connect {src_out} -> {tgt_in}\\\", \\\"details\\\": str(e)}\\n\\n    sync_dropdown_selected_outputs(flow)\\n    layout_flow(flow)\\n\\n    flow[\\\"name\\\"] = parsed.get(\\\"name\\\", \\\"Untitled Flow\\\")\\n    flow[\\\"description\\\"] = parsed.get(\\\"description\\\", \\\"\\\")\\n\\n    return {\\n        \\\"flow\\\": flow,\\n        \\\"name\\\": flow[\\\"name\\\"],\\n        \\\"node_count\\\": len(flow[\\\"data\\\"][\\\"nodes\\\"]),\\n        \\\"edge_count\\\": len(flow[\\\"data\\\"][\\\"edges\\\"]),\\n        \\\"node_id_map\\\": id_map,\\n    }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/flow_builder/component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"12a1b1361bd8480220c55afaee895bc91945c0f031321b929982da557046ca00\",\"content\":\"\\\"\\\"\\\"Component operations: add, remove, configure, list components in flows.\\n\\nPure functions that operate on flow dicts. The component registry is passed\\nas a parameter (dict mapping component_type -> template_dict), not loaded\\nfrom global state.\\n\\nAll functions are pure \u2014 no I/O, no network, no global state.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport copy\\nimport json\\nimport math\\nimport secrets\\nimport string\\nfrom numbers import Real\\nfrom typing import Any\\n\\nimport yaml\\n\\nfrom lfx.field_typing.conditional_options import resolve_conditional_options\\nfrom lfx.graph.edge.base import TYPE_MIGRATIONS\\nfrom lfx.graph.flow_builder._utils import node_id as _node_id\\n\\n# Canvas type for user-authored code components. The frontend resolves this in\\n# its global template list and exempts it from the \\\"Update available\\\" check\\n# (componentsToIgnoreUpdate). User overlay entries are keyed by class name in\\n# the registry so the agent can reference them, but their canvas node must wear\\n# this type or the frontend flags them as a missing/outdated component.\\nCUSTOM_COMPONENT_CANVAS_TYPE = \\\"CustomComponent\\\"\\nFLOW_BUILDER_REGISTRY_TYPE_KEY = \\\"_flow_builder_registry_type\\\"\\nFLOW_BUILDER_UNTRUSTED_CUSTOM_KEY = \\\"_flow_builder_untrusted_custom\\\"\\n\\n\\ndef _generate_id(component_type: str) -> str:\\n    \\\"\\\"\\\"Generate a component ID like 'ChatInput-a1B2c'.\\\"\\\"\\\"\\n    suffix = \\\"\\\".join(secrets.choice(string.ascii_letters + string.digits) for _ in range(5))\\n    return f\\\"{component_type}-{suffix}\\\"\\n\\n\\ndef _normalize_outputs(node_data: dict) -> None:\\n    \\\"\\\"\\\"Backfill required Output fields the bundled registry sometimes omits.\\n\\n    The local registry index (``_assets/component_index.json``) was built from\\n    component definitions that didn't always serialize every Output field.\\n    Downstream consumers \u2014 the canvas serializer, the ``/custom_component/update``\\n    endpoint, the LFX dataclass deserializer \u2014 expect the full 13-field Output\\n    shape (see ``lfx.template.field.base.Output``). Partial entries crash with\\n    ``string indices must be integers, not 'str'`` when a serializer tries to\\n    walk what it thinks is a dict but the deserializer left as a string.\\n\\n    Fills the missing fields with the safe defaults real saved outputs use, so\\n    flows built via ``build_flow_from_spec`` load on the canvas without the\\n    \\\"Error while updating the Component\\\" toast.\\n\\n    Idempotent.\\n    \\\"\\\"\\\"\\n    outputs = node_data.get(\\\"outputs\\\")\\n    if not isinstance(outputs, list):\\n        return\\n    for output in outputs:\\n        if not isinstance(output, dict):\\n            continue\\n        output.setdefault(\\\"hidden\\\", False)\\n        output.setdefault(\\\"options\\\", None)\\n        output.setdefault(\\\"required_inputs\\\", None)\\n\\n\\ndef _make_node(\\n    component_type: str,\\n    registry: dict[str, dict],\\n    component_id: str | None = None,\\n) -> dict:\\n    \\\"\\\"\\\"Create a full node structure from the component registry.\\n\\n    Args:\\n        component_type: The type name (e.g. \\\"ChatInput\\\").\\n        registry: Mapping of component_type -> template dict.\\n        component_id: Optional explicit ID; auto-generated if None.\\n    \\\"\\\"\\\"\\n    cid = component_id or _generate_id(component_type)\\n\\n    if component_type not in registry:\\n        available = \\\", \\\".join(sorted(registry.keys())[:20])\\n        msg = f\\\"Unknown component: {component_type}. Available: {available}...\\\"\\n        raise ValueError(msg)\\n\\n    node_data = copy.deepcopy(registry[component_type])\\n    _normalize_outputs(node_data)\\n\\n    # User-overlay (assistant-generated) entries are tagged ``custom``. Strip\\n    # the internal marker and label the canvas node as CustomComponent so the\\n    # frontend treats it like any user-authored component (no spurious\\n    # \\\"Update available\\\" badge). Built-ins keep their own type.\\n    is_custom = node_data.pop(\\\"custom\\\", False) is True\\n    node_type = CUSTOM_COMPONENT_CANVAS_TYPE if is_custom else component_type\\n    data = {\\n        \\\"id\\\": cid,\\n        \\\"type\\\": node_type,\\n        \\\"node\\\": node_data,\\n        \\\"showNode\\\": True,\\n    }\\n    if is_custom:\\n        # Keep provenance outside the user-authored component template. The\\n        # canvas type must remain CustomComponent, but policy checks also need\\n        # the original registry key after this node is stored and revisited.\\n        data[FLOW_BUILDER_REGISTRY_TYPE_KEY] = component_type\\n        data[FLOW_BUILDER_UNTRUSTED_CUSTOM_KEY] = True\\n\\n    return {\\n        \\\"id\\\": cid,\\n        \\\"type\\\": \\\"genericNode\\\",\\n        \\\"position\\\": {\\\"x\\\": 0, \\\"y\\\": 0},\\n        \\\"selected\\\": False,\\n        \\\"data\\\": data,\\n    }\\n\\n\\ndef sync_dropdown_selected_outputs(flow: dict) -> None:\\n    \\\"\\\"\\\"Pin dropdown-style source nodes to the output their edges actually use.\\n\\n    A component whose outputs are a single-active dropdown (multiple outputs,\\n    none ``group_outputs``) renders one handle at a time. When a built node\\n    carries no ``selected_output``, the canvas auto-selects its FIRST output on\\n    mount, which clears the other outputs' ``selected`` flag and makes\\n    ``cleanEdges`` drop any edge wired from a non-first output (e.g. a loop\\n    feedback edge from ``TypeConverter.data_output``). Recording\\n    ``selected_output`` = the wired output stops that auto-flip so the edge\\n    survives and the node renders the correct handle. Only applied when every\\n    outgoing edge of the node uses the same output (no ambiguity). Idempotent.\\n    \\\"\\\"\\\"\\n    edges = flow.get(\\\"data\\\", {}).get(\\\"edges\\\", [])\\n    used_outputs: dict[str, set[str]] = {}\\n    for edge in edges:\\n        source_id = edge.get(\\\"source\\\")\\n        name = (edge.get(\\\"data\\\") or {}).get(\\\"sourceHandle\\\", {}).get(\\\"name\\\")\\n        if source_id and name:\\n            used_outputs.setdefault(source_id, set()).add(name)\\n\\n    for node in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", []):\\n        wired = used_outputs.get(_node_id(node))\\n        if not wired or len(wired) != 1:\\n            continue\\n        node_config = node.get(\\\"data\\\", {}).get(\\\"node\\\", {})\\n        outputs = node_config.get(\\\"outputs\\\")\\n        if not isinstance(outputs, list):\\n            continue\\n        non_group = [o for o in outputs if isinstance(o, dict) and not o.get(\\\"group_outputs\\\")]\\n        if len(non_group) <= 1:\\n            continue\\n        wired_name = next(iter(wired))\\n        if any(o.get(\\\"name\\\") == wired_name for o in non_group):\\n            node[\\\"data\\\"][\\\"selected_output\\\"] = wired_name\\n            _sync_output_type_tab(node_config, non_group, wired_name)\\n\\n\\ndef _sync_output_type_tab(node_config: dict, outputs: list[dict], wired_name: str) -> None:\\n    \\\"\\\"\\\"Align a node's ``output_type`` tab with its wired output.\\n\\n    Components like TypeConverter rebuild ``outputs`` from the tab value on\\n    hydration (``update_outputs``), so a tab left on another type deletes the\\n    wired output and dangles its edges as soon as the flow reloads. Only\\n    overwrites when the current value clearly selects a different output;\\n    unknown values (e.g. spec-configured aliases) are left untouched.\\n    \\\"\\\"\\\"\\n    tab = node_config.get(\\\"template\\\", {}).get(\\\"output_type\\\")\\n    if not isinstance(tab, dict) or tab.get(\\\"type\\\") != \\\"tab\\\":\\n        return\\n    options = tab.get(\\\"options\\\") or []\\n    wired = next((o for o in outputs if o.get(\\\"name\\\") == wired_name), None)\\n    if wired is None:\\n        return\\n    match = next((opt for opt in options if opt in (wired.get(\\\"types\\\") or [])), None)\\n    if match is None or tab.get(\\\"value\\\") == match:\\n        return\\n    selects_other_output = any(\\n        tab.get(\\\"value\\\") in (o.get(\\\"types\\\") or []) for o in outputs if o.get(\\\"name\\\") != wired_name\\n    )\\n    if selects_other_output:\\n        tab[\\\"value\\\"] = match\\n\\n\\ndef add_component(\\n    flow: dict,\\n    component_type: str,\\n    registry: dict[str, dict],\\n    component_id: str | None = None,\\n) -> dict:\\n    \\\"\\\"\\\"Add a component to a flow with its full template from the registry.\\n\\n    Returns dict with 'id' and 'display_name'.\\n    \\\"\\\"\\\"\\n    node = _make_node(component_type, registry, component_id=component_id)\\n    flow[\\\"data\\\"][\\\"nodes\\\"].append(node)\\n    return {\\\"id\\\": node[\\\"id\\\"], \\\"display_name\\\": node[\\\"data\\\"][\\\"node\\\"].get(\\\"display_name\\\", component_type)}\\n\\n\\ndef remove_component(flow: dict, component_id: str) -> None:\\n    \\\"\\\"\\\"Remove a component and all its connections from a flow.\\\"\\\"\\\"\\n    nodes = flow[\\\"data\\\"][\\\"nodes\\\"]\\n    original_count = len(nodes)\\n    flow[\\\"data\\\"][\\\"nodes\\\"] = [n for n in nodes if _node_id(n) != component_id]\\n    if len(flow[\\\"data\\\"][\\\"nodes\\\"]) == original_count:\\n        msg = f\\\"Component not found: {component_id}\\\"\\n        raise ValueError(msg)\\n\\n    edges = flow[\\\"data\\\"][\\\"edges\\\"]\\n    flow[\\\"data\\\"][\\\"edges\\\"] = [e for e in edges if e.get(\\\"source\\\") != component_id and e.get(\\\"target\\\") != component_id]\\n\\n\\ndef _parse_serialized_model_text(text: str) -> dict | list | None:\\n    \\\"\\\"\\\"Try JSON then YAML; return ``None`` when the input is a bare name.\\n\\n    Only fires on text that looks structured (starts with ``{``, ``[``, or\\n    ``- ``, or contains an inline ``key: value`` pair) so a bare model name\\n    like ``\\\"gpt-4o\\\"`` is never silently transformed.\\n    \\\"\\\"\\\"\\n    stripped = (text or \\\"\\\").strip()\\n    if not stripped:\\n        return None\\n    looks_structured = stripped.startswith((\\\"{\\\", \\\"[\\\", \\\"- \\\")) or (\\\": \\\" in stripped and \\\"\\\\n\\\" in stripped)\\n    if not looks_structured:\\n        return None\\n    try:\\n        parsed = json.loads(stripped)\\n        if isinstance(parsed, (dict, list)):\\n            return parsed\\n    except json.JSONDecodeError:\\n        pass\\n    try:\\n        parsed = yaml.safe_load(stripped)\\n    except yaml.YAMLError:\\n        return None\\n    if isinstance(parsed, (dict, list)):\\n        return parsed\\n    return None\\n\\n\\ndef _coerce_single_model_entry(item: Any) -> Any:\\n    \\\"\\\"\\\"Unwrap a nested serialized spec stuffed into ``item['name']``.\\n\\n    Pattern observed in QA: ``[{\\\"name\\\": \\\"[{...JSON spec...}]\\\", \\\"provider\\\":\\n    \\\"Unknown\\\"}]``. The outer wrapper is preserved by the catalog fallback,\\n    but the real provider/name is buried in the inner name string.\\n    \\\"\\\"\\\"\\n    if not isinstance(item, dict):\\n        return item\\n    name = item.get(\\\"name\\\")\\n    if not isinstance(name, str):\\n        return item\\n    parsed = _parse_serialized_model_text(name)\\n    if isinstance(parsed, list) and parsed and isinstance(parsed[0], dict):\\n        return parsed[0]\\n    if isinstance(parsed, dict):\\n        return parsed\\n    return item\\n\\n\\ndef _coerce_model_value(value: Any) -> Any:\\n    \\\"\\\"\\\"Normalize a model-field value to canonical ``list[dict]``.\\n\\n    Accepts:\\n      - serialized JSON / YAML string of a list or dict\\n      - already-canonical ``list[dict]`` (each entry still checked for a\\n        nested serialized spec in ``name``)\\n      - a bare name string (left untouched so the catalog path runs)\\n    \\\"\\\"\\\"\\n    if isinstance(value, list):\\n        return [_coerce_single_model_entry(item) for item in value]\\n    if isinstance(value, dict):\\n        return [_coerce_single_model_entry(value)]\\n    if isinstance(value, str):\\n        parsed = _parse_serialized_model_text(value)\\n        if isinstance(parsed, dict):\\n            return [_coerce_single_model_entry(parsed)]\\n        if isinstance(parsed, list):\\n            return [_coerce_single_model_entry(item) for item in parsed]\\n    return value\\n\\n\\ndef _is_scalar_option_value(value: Any) -> bool:\\n    \\\"\\\"\\\"Return whether a registry value can participate in direct option matching.\\\"\\\"\\\"\\n    return value is None or isinstance(value, (str, int, float, bool))\\n\\n\\n# Field types whose ``options`` are scalar but whose value is structured\\n# (DurationInput: unit options, ``{\\\"unit\\\", \\\"value\\\"}`` value). Gated by type, not\\n# by the current value, so the decision cannot flip after a write.\\n_STRUCTURED_VALUE_TYPES = frozenset({\\\"duration\\\"})\\n\\n\\ndef _validate_configured_value(field_name: str, field: dict[str, Any], value: Any, *, allow_zero: bool = False) -> None:\\n    \\\"\\\"\\\"Validate closed options and numeric bounds before mutating a flow.\\\"\\\"\\\"\\n    if value is None:\\n        return\\n\\n    options = field.get(\\\"options\\\")\\n    # Model selectors and sortable lists carry dict options and keep their\\n    # existing structured semantics; duration keeps its structured value.\\n    has_scalar_options = (\\n        isinstance(options, list)\\n        and all(_is_scalar_option_value(option) for option in options)\\n        and field.get(\\\"type\\\") not in _STRUCTURED_VALUE_TYPES\\n    )\\n    # A list field with an options list (even an empty, open one such as an\\n    # action picker) always takes a list. Checked before the re-set shortcut so\\n    # an already malformed scalar cannot be re-affirmed.\\n    if has_scalar_options and field.get(\\\"list\\\") and not isinstance(value, list):\\n        msg = f\\\"Invalid value for parameter '{field_name}': {value!r}. Expected a list\\\"\\n        raise ValueError(msg)\\n\\n    if not field.get(\\\"conditional_options\\\") and value == field.get(\\\"value\\\"):\\n        # Re-setting what the field already holds is always acceptable, including\\n        # shipped defaults that sit outside their own range_spec (max_tokens=0).\\n        return\\n\\n    has_direct_options = has_scalar_options and (bool(options) or bool(field.get(\\\"conditional_options\\\")))\\n    if has_direct_options and not field.get(\\\"combobox\\\"):\\n        values = value if field.get(\\\"list\\\") and isinstance(value, list) else [value]\\n        accepted_values = list(options)\\n        if field.get(\\\"type\\\") == \\\"tab\\\":\\n            # TabInput accepts an empty selection in addition to its options.\\n            accepted_values.append(\\\"\\\")\\n            # Saved flows may still carry the pre-migration type names; accept\\n            # them the same way edge type checks do.\\n            for alias, canonical in TYPE_MIGRATIONS.items():\\n                if canonical in options:\\n                    accepted_values.append(alias)\\n        invalid_values = [item for item in values if item not in accepted_values]\\n        if invalid_values:\\n            msg = f\\\"Invalid value for parameter '{field_name}': {invalid_values[0]!r}. Expected one of: {options!r}\\\"\\n            raise ValueError(msg)\\n\\n    range_spec = field.get(\\\"range_spec\\\")\\n    if not isinstance(range_spec, dict):\\n        return\\n\\n    if not isinstance(value, Real) or isinstance(value, bool):\\n        msg = f\\\"Invalid value for parameter '{field_name}': {value!r}. Expected a number\\\"\\n        raise ValueError(msg)  # noqa: TRY004\\n\\n    # Integers are always finite; converting a very large int to float can overflow.\\n    if not isinstance(value, int) and not math.isfinite(value):\\n        msg = f\\\"Invalid value for parameter '{field_name}': {value!r}. Expected a finite number\\\"\\n        raise ValueError(msg)\\n\\n    if allow_zero and value == 0:\\n        # Older saved Agent/LanguageModel templates have min=1, although their\\n        # runtime has always used zero to mean no explicit token limit.\\n        return\\n\\n    minimum = range_spec.get(\\\"min\\\")\\n    maximum = range_spec.get(\\\"max\\\")\\n    if (minimum is not None and value < minimum) or (maximum is not None and value > maximum):\\n        bounds = f\\\"{minimum}..{maximum}\\\" if minimum is not None and maximum is not None else \\\"the configured range\\\"\\n        msg = f\\\"Invalid value for parameter '{field_name}': {value!r}. Expected a value in {bounds}\\\"\\n        raise ValueError(msg)\\n\\n\\ndef configure_component(\\n    flow: dict,\\n    component_id: str,\\n    params: dict[str, Any],\\n) -> None:\\n    \\\"\\\"\\\"Set parameters on a component (pure version \u2014 no server calls).\\n\\n    Every parameter is validated first (known field, closed ``options``,\\n    ``range_spec`` bounds, numeric type) and only then applied, so a\\n    rejected call raises ``ValueError`` and leaves the flow, including\\n    ``load_from_db`` flags, exactly as it was.\\n\\n    Model-typed fields (``template[field].type == \\\"model\\\"``) accept the\\n    canonical ``[{\\\"provider\\\": X, \\\"name\\\": Y}]`` shape. Some flow-builder\\n    callers (the agent's ``BuildFlowFromSpec`` and ``ConfigureComponent``\\n    tools) sometimes emit the spec as a JSON or YAML *string* instead.\\n    Without normalization, that raw string lands in\\n    ``template['model'].value``, the catalog falls back to\\n    ``provider=\\\"Unknown\\\"``, and ``get_llm`` raises ``ValueError: missing\\n    a provider``. Normalize at this single choke point so every caller\\n    path is covered. ``params`` is mutated in place so post-configure\\n    helpers (e.g. ``_mirror_model_value_into_options``) read the\\n    canonical value.\\n    \\\"\\\"\\\"\\n    node = _find_node(flow, component_id)\\n    if node is None:\\n        msg = f\\\"Component not found: {component_id}\\\"\\n        raise ValueError(msg)\\n\\n    template = node[\\\"data\\\"].get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n    normalized_params: dict[str, Any] = {}\\n    for key, raw_value in params.items():\\n        if key not in template:\\n            available = [k for k in template if isinstance(template[k], dict)]\\n            msg = f\\\"Unknown parameter '{key}' on component '{component_id}'. Available: {available}\\\"\\n            raise ValueError(msg)\\n        if not isinstance(template[key], dict):\\n            # Reserved non-field entries (e.g. \\\"_type\\\", metadata strings) are not\\n            # configurable; wrapping them would corrupt the node. Reject instead.\\n            available = [k for k in template if isinstance(template[k], dict)]\\n            msg = (\\n                f\\\"Parameter '{key}' on component '{component_id}' is not a configurable \\\"\\n                f\\\"field (reserved template entry). Available: {available}\\\"\\n            )\\n            # Why: this function's contract raises ValueError for every config\\n            # error (see sibling check + test_configure_unknown_field_raises);\\n            # callers catch ValueError. TypeError would break that contract.\\n            raise ValueError(msg)  # noqa: TRY004\\n        value = raw_value\\n        if template[key].get(\\\"type\\\") == \\\"model\\\":\\n            value = _coerce_model_value(value)\\n        normalized_params[key] = value\\n\\n    candidate_values = {key: field.get(\\\"value\\\") for key, field in template.items() if isinstance(field, dict)}\\n    candidate_values.update(normalized_params)\\n    resolved_options = {\\n        key: resolve_conditional_options(field, candidate_values)\\n        for key, field in template.items()\\n        if isinstance(field, dict) and field.get(\\\"conditional_options\\\")\\n    }\\n    # Use the whole proposed configuration regardless of parameter order, but\\n    # preserve the existing contract of validating only explicitly supplied values.\\n    for key in normalized_params:\\n        field = template[key]\\n        if key in resolved_options:\\n            field = {**field, \\\"options\\\": resolved_options[key]}\\n        _validate_configured_value(\\n            key,\\n            field,\\n            candidate_values[key],\\n            allow_zero=key == \\\"max_tokens\\\" and node[\\\"data\\\"].get(\\\"type\\\") in {\\\"Agent\\\", \\\"LanguageModelComponent\\\"},\\n        )\\n\\n    # Validate every parameter before changing either the flow or caller's params.\\n    params.update(normalized_params)\\n    for key, options in resolved_options.items():\\n        template[key][\\\"options\\\"] = options\\n    for key, value in normalized_params.items():\\n        template[key][\\\"value\\\"] = value\\n        # Values supplied through the configure API are explicit literals, just\\n        # like values set through Component.set_input_value(). Do not reinterpret\\n        # them as global-variable names merely because the field defaults to\\n        # load_from_db=True (notably SecretStrInput credentials).\\n        if \\\"load_from_db\\\" in template[key]:\\n            template[key][\\\"load_from_db\\\"] = False\\n\\n\\ndef get_component(flow: dict, component_id: str) -> dict:\\n    \\\"\\\"\\\"Get information about a component in a flow.\\\"\\\"\\\"\\n    node = _find_node(flow, component_id)\\n    if node is None:\\n        msg = f\\\"Component not found: {component_id}\\\"\\n        raise ValueError(msg)\\n\\n    node_data = node.get(\\\"data\\\", {})\\n    node_config = node_data.get(\\\"node\\\", {})\\n    template = node_config.get(\\\"template\\\", {})\\n\\n    params = {}\\n    for key, field in template.items():\\n        if isinstance(field, dict):\\n            params[key] = field.get(\\\"value\\\")\\n\\n    return {\\n        \\\"id\\\": _node_id(node),\\n        \\\"display_name\\\": node_config.get(\\\"display_name\\\", node_data.get(\\\"type\\\", \\\"\\\")),\\n        \\\"type\\\": node_data.get(\\\"type\\\", \\\"\\\"),\\n        \\\"params\\\": params,\\n        \\\"outputs\\\": node_config.get(\\\"outputs\\\", []),\\n    }\\n\\n\\ndef list_components(flow: dict) -> list[dict]:\\n    \\\"\\\"\\\"List all components in a flow.\\\"\\\"\\\"\\n    results = []\\n    for node in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", []):\\n        node_data = node.get(\\\"data\\\", {})\\n        node_config = node_data.get(\\\"node\\\", {})\\n        results.append(\\n            {\\n                \\\"id\\\": _node_id(node),\\n                \\\"display_name\\\": node_config.get(\\\"display_name\\\", node_data.get(\\\"type\\\", \\\"\\\")),\\n                \\\"type\\\": node_data.get(\\\"type\\\", \\\"\\\"),\\n            }\\n        )\\n    return results\\n\\n\\ndef needs_server_update(template: dict, field: str) -> bool:\\n    \\\"\\\"\\\"Check if setting a field requires server-side template regeneration.\\n\\n    The frontend triggers /custom_component/update on value change only when\\n    the field has real_time_refresh=True. tool_mode is handled separately.\\n    \\\"\\\"\\\"\\n    if field == \\\"tool_mode\\\":\\n        return True\\n    field_def = template.get(field, {})\\n    if not isinstance(field_def, dict):\\n        return False\\n    return bool(field_def.get(\\\"real_time_refresh\\\"))\\n\\n\\ndef _find_node(flow: dict, component_id: str) -> dict | None:\\n    \\\"\\\"\\\"Find a node by component ID.\\\"\\\"\\\"\\n    for node in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", []):\\n        if _node_id(node) == component_id:\\n            return node\\n    return None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/flow_builder/connect.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"731fe0ee8c18c5e6cd5136dbaade11517928f9a8a3381b993cde4e69f4ce5768\",\"content\":\"\\\"\\\"\\\"Connection management: wire component outputs to inputs.\\n\\nConnections are represented as edges in the flow JSON matching\\nReactFlow's edge format. Each edge needs:\\n- source/target: Component IDs\\n- sourceHandle/targetHandle: JSON-like strings with \u0153 (U+0153) replacing quotes\\n- data.sourceHandle/data.targetHandle: Dicts with type info\\n- id: reactflow__edge-{source}{sourceHandle}-{target}{targetHandle}\\n\\nAll functions are pure \u2014 they operate on flow dicts, no I/O.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\n\\nfrom lfx.graph.edge.base import types_compatible\\nfrom lfx.graph.flow_builder.component import sync_dropdown_selected_outputs\\n\\n# Langflow uses oe (U+0153) as a quote replacement in ReactFlow handle strings\\n_Q = \\\"\\\\u0153\\\"\\n\\n# Must match lfx.base.tools.constants.TOOL_OUTPUT_NAME \\\\u2014 duplicated as a\\n# literal to avoid a cross-package import in the flow_builder layer.\\n_TOOL_OUTPUT_NAME = \\\"component_as_tool\\\"\\n_TOOL_OUTPUT_DISPLAY_NAME = \\\"Toolset\\\"\\n\\n_MESSAGE_TYPE = \\\"Message\\\"\\n# Data \\\\u2261 JSON and DataFrame \\\\u2261 Table per lfx.graph.edge.base.TYPE_MIGRATIONS.\\n_DATA_LIKE_TYPES = frozenset({\\\"Data\\\", \\\"JSON\\\", \\\"DataFrame\\\", \\\"Table\\\"})\\n\\n\\ndef _conversion_hint(\\n    source_id: str,\\n    source_output: str,\\n    source_types: list[str],\\n    target_id: str,\\n    target_input: str,\\n    target_types: list[str],\\n) -> str:\\n    \\\"\\\"\\\"Deterministic repair for the two common Data<->Message mismatches.\\n\\n    A bare \\\"Type mismatch\\\" dead-ends the flow-builder agent into a discovery\\n    spiral (it re-searches/re-describes until its step budget is gone); naming\\n    the exact converter edge lets it correct the wiring in a single retry.\\n    \\\"\\\"\\\"\\n    src = set(source_types or [])\\n    tgt = set(target_types or [])\\n    if _MESSAGE_TYPE in tgt and src & _DATA_LIKE_TYPES:\\n        return (\\n            f\\\" Fix: insert a ParserComponent between them \\\\u2014 \\\"\\n            f\\\"{source_id}.{source_output} -> ParserComponent.input_data, \\\"\\n            f\\\"ParserComponent.parsed_text -> {target_id}.{target_input}.\\\"\\n        )\\n    if _MESSAGE_TYPE in src and tgt & _DATA_LIKE_TYPES:\\n        converter_output = \\\"data_output\\\" if tgt & {\\\"Data\\\", \\\"JSON\\\"} else \\\"dataframe_output\\\"\\n        return (\\n            f\\\" Fix: insert a TypeConverterComponent between them \\\\u2014 \\\"\\n            f\\\"{source_id}.{source_output} -> TypeConverterComponent.input_data, \\\"\\n            f\\\"TypeConverterComponent.{converter_output} -> {target_id}.{target_input}.\\\"\\n        )\\n    return \\\"\\\"\\n\\n\\ndef _find_node_data(flow: dict, component_id: str) -> dict | None:\\n    \\\"\\\"\\\"Return the ``data`` dict of the node matching ``component_id``, or None.\\\"\\\"\\\"\\n    for node in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", []):\\n        node_data = node.get(\\\"data\\\", {})\\n        nid = node_data.get(\\\"id\\\", node.get(\\\"id\\\", \\\"\\\"))\\n        if nid == component_id:\\n            return node_data\\n    return None\\n\\n\\ndef _has_template_input(flow: dict, component_id: str, input_name: str) -> bool:\\n    \\\"\\\"\\\"True when ``input_name`` is a non-empty template field on the component.\\\"\\\"\\\"\\n    node_data = _find_node_data(flow, component_id)\\n    if node_data is None:\\n        return False\\n    field = node_data.get(\\\"node\\\", {}).get(\\\"template\\\", {}).get(input_name)\\n    return isinstance(field, dict) and bool(field)\\n\\n\\ndef _declares_tool_mode(node: dict) -> bool:\\n    \\\"\\\"\\\"Both halves of Component._handle_tool_mode, read off one serialized node.\\n\\n    That method is the runtime authority that creates the ``component_as_tool``\\n    output: it fires for an INPUT declaring ``tool_mode``, or for a class opting\\n    in via ``add_tool_output``.\\n\\n    Output-side ``tool_mode`` is deliberately not consulted. That flag marks\\n    which outputs a toolset exposes, not whether the component has one \\\\u2014 89 of\\n    the 127 bundled components set it, ChatInput and ChatOutput included \\\\u2014 so\\n    reading it as a capability signal made this guard accept everything.\\n    \\\"\\\"\\\"\\n    if node.get(\\\"add_tool_output\\\"):\\n        return True\\n    template = node.get(\\\"template\\\", {})\\n    return any(isinstance(fdata, dict) and fdata.get(\\\"tool_mode\\\") for fdata in template.values())\\n\\n\\ndef _node_supports_tool_mode(node_data: dict, registry: dict[str, dict] | None = None) -> bool:\\n    \\\"\\\"\\\"Return True when the component can synthesize a toolset output.\\n\\n    Reads the node as saved, then falls back to ``registry`` -- the live\\n    definition for the node's type -- when the saved copy declares neither\\n    signal. ``add_tool_output`` only started being serialized into templates\\n    this release, so a flow saved before it carries tool-capable nodes with no\\n    capability signal at all. ``RunFlow`` is the whole of that set: it is the\\n    one bundled component that opts in via ``add_tool_output`` while declaring\\n    no ``tool_mode`` input, and being wrapped as a Tool is its entire purpose.\\n    \\\"\\\"\\\"\\n    if _declares_tool_mode(node_data.get(\\\"node\\\", {})):\\n        return True\\n    node_type = node_data.get(\\\"type\\\")\\n    entry = registry.get(node_type) if registry and isinstance(node_type, str) else None\\n    return isinstance(entry, dict) and _declares_tool_mode(entry)\\n\\n\\ndef ensure_tool_mode_supported(\\n    flow: dict,\\n    component_id: str,\\n    registry: dict[str, dict] | None = None,\\n) -> dict:\\n    \\\"\\\"\\\"Validate that a component can be wrapped as a Tool. Mutates nothing.\\n\\n    Split out of ``_enable_tool_mode`` so a caller that performs the flip\\n    remotely can refuse BEFORE it mutates the stored flow. The MCP\\n    ``connect_components`` tool does exactly that: it hands the flip to\\n    ``/custom_component/update`` because only the server's node rebuild\\n    produces the ``tools_metadata`` template field.\\n\\n    Returns the node's ``data`` dict. Raises ValueError when the component is\\n    missing from the flow or cannot produce a toolset output.\\n    \\\"\\\"\\\"\\n    node_data = _find_node_data(flow, component_id)\\n    if node_data is None:\\n        msg = f\\\"Component not found in flow: {component_id}\\\"\\n        raise ValueError(msg)\\n    if not _node_supports_tool_mode(node_data, registry):\\n        msg = (\\n            f\\\"Cannot connect '{component_id}.{_TOOL_OUTPUT_NAME}': this component does not \\\"\\n            \\\"support tool mode - none of its inputs declare tool_mode=True and it does not \\\"\\n            \\\"set add_tool_output. If this component IS tool-capable (RunFlow, for example), \\\"\\n            \\\"this node's template predates the capability flag: refresh the component to \\\"\\n            \\\"restore it. Otherwise pick a different output.\\\"\\n        )\\n        raise ValueError(msg)\\n    return node_data\\n\\n\\ndef _enable_tool_mode(flow: dict, source_id: str, registry: dict[str, dict] | None = None) -> None:\\n    \\\"\\\"\\\"Flip a component to tool mode in place.\\n\\n    Mirrors Component._handle_tool_mode: when tool_mode is enabled the\\n    outputs list is replaced with a single synthesized tool output. The\\n    source node must already exist in the flow; raises ValueError otherwise.\\n\\n    Raises ValueError when the component cannot produce a toolset output\\n    (i.e. it genuinely cannot be wrapped as a Tool). Checked before the\\n    idempotence shortcut so a node already carrying the synthesized output \u2014\\n    flipped by this same guard back when it accepted output-side tool_mode \u2014\\n    is refused rather than kept alive.\\n    \\\"\\\"\\\"\\n    node_data = ensure_tool_mode_supported(flow, source_id, registry)\\n    inner = node_data.setdefault(\\\"node\\\", {})\\n    # Idempotent: already in tool mode with the synthesized output present.\\n    if inner.get(\\\"tool_mode\\\") and any(o.get(\\\"name\\\") == _TOOL_OUTPUT_NAME for o in inner.get(\\\"outputs\\\", [])):\\n        return\\n    inner[\\\"tool_mode\\\"] = True\\n    # Mirror the FULL Output schema (lfx.template.field.base.Output): the canvas\\n    # serializers crash on partial output dicts (\\\"string indices must be integers\\\").\\n    inner[\\\"outputs\\\"] = [\\n        {\\n            \\\"allows_loop\\\": False,\\n            \\\"cache\\\": True,\\n            \\\"display_name\\\": _TOOL_OUTPUT_DISPLAY_NAME,\\n            \\\"group_outputs\\\": False,\\n            \\\"hidden\\\": False,\\n            \\\"method\\\": \\\"to_toolkit\\\",\\n            \\\"name\\\": _TOOL_OUTPUT_NAME,\\n            \\\"options\\\": None,\\n            \\\"required_inputs\\\": None,\\n            \\\"selected\\\": \\\"Tool\\\",\\n            \\\"tool_mode\\\": True,\\n            \\\"types\\\": [\\\"Tool\\\"],\\n            \\\"value\\\": \\\"__UNDEFINED__\\\",\\n        }\\n    ]\\n\\n\\ndef _scaped_json_stringify(obj: Any) -> str:\\n    \\\"\\\"\\\"Replicate Langflow frontend's scapedJSONStringfy: sorted keys, compact, oe for quotes.\\\"\\\"\\\"\\n    return _custom_stringify(obj).replace('\\\"', _Q)\\n\\n\\ndef _custom_stringify(obj: Any) -> str:\\n    \\\"\\\"\\\"Replicate Langflow frontend's customStringify for edge handle data.\\n\\n    Covers the subset of types used in handle dicts. Uses json.dumps for\\n    strings to handle escaping correctly.\\n    \\\"\\\"\\\"\\n    if obj is None:\\n        return \\\"null\\\"\\n    if isinstance(obj, bool):\\n        return \\\"true\\\" if obj else \\\"false\\\"\\n    if isinstance(obj, (int, float)):\\n        return str(obj)\\n    if isinstance(obj, str):\\n        import json\\n\\n        return json.dumps(obj)\\n    if isinstance(obj, list):\\n        items = \\\",\\\".join(_custom_stringify(item) for item in obj)\\n        return f\\\"[{items}]\\\"\\n    if isinstance(obj, dict):\\n        keys = sorted(obj.keys())\\n        pairs = \\\",\\\".join(f'\\\"{k}\\\":{_custom_stringify(obj[k])}' for k in keys)\\n        return f\\\"{{{pairs}}}\\\"\\n    return str(obj)\\n\\n\\ndef _resolve_output_types(flow: dict, component_id: str, output_name: str) -> list[str]:\\n    \\\"\\\"\\\"Look up output types from the component's node data in the flow.\\n\\n    Raises ValueError if the component or output is not found.\\n    \\\"\\\"\\\"\\n    node_data = _find_node_data(flow, component_id)\\n    if node_data is None:\\n        msg = f\\\"Component not found in flow: {component_id}\\\"\\n        raise ValueError(msg)\\n    outputs = node_data.get(\\\"node\\\", {}).get(\\\"outputs\\\", [])\\n    for output in outputs:\\n        if output.get(\\\"name\\\") == output_name:\\n            return output.get(\\\"types\\\", [\\\"Message\\\"])\\n    available = [o.get(\\\"name\\\") for o in outputs]\\n    msg = f\\\"Output '{output_name}' not found on component '{component_id}'. Available: {available}\\\"\\n    raise ValueError(msg)\\n\\n\\ndef _resolve_input_types(flow: dict, component_id: str, input_name: str) -> tuple[list[str], str]:\\n    \\\"\\\"\\\"Look up input types and field type from the component's template.\\n\\n    Raises ValueError if the component or input is not found.\\n    \\\"\\\"\\\"\\n    node_data = _find_node_data(flow, component_id)\\n    if node_data is None:\\n        msg = f\\\"Component not found in flow: {component_id}\\\"\\n        raise ValueError(msg)\\n    template = node_data.get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n    field = template.get(input_name, {})\\n    if isinstance(field, dict) and field:\\n        return field.get(\\\"input_types\\\", [\\\"Message\\\"]), field.get(\\\"type\\\", \\\"str\\\")\\n    available = [k for k, v in template.items() if isinstance(v, dict) and v.get(\\\"input_types\\\")]\\n    msg = f\\\"Input '{input_name}' not found on component '{component_id}'. Available: {available}\\\"\\n    loop_ports = [o.get(\\\"name\\\") for o in node_data.get(\\\"node\\\", {}).get(\\\"outputs\\\", []) if o.get(\\\"allows_loop\\\")]\\n    if loop_ports:\\n        msg += f\\\" Loop inputs: {loop_ports}\\\"\\n    raise ValueError(msg)\\n\\n\\ndef _resolve_loop_target(flow: dict, component_id: str, port_name: str) -> tuple[list[str], str] | None:\\n    \\\"\\\"\\\"Resolve ``port_name`` as a loop input: an ``allows_loop`` output on the target.\\n\\n    The Loop component's feedback port is an OUTPUT flagged ``allows_loop=True``,\\n    not a template input. The canvas accepts ``[selected ?? types[0], *loop_types]``\\n    into that handle and serializes the edge with an output-shaped targetHandle\\n    (see ``reactflowUtils.ts`` and ``lfx.graph.edge.base.Edge``); this mirrors it.\\n\\n    Returns ``(accepted_types, node_data_type)`` or ``None`` when the component\\n    or a matching loop output is not found (callers decide how to fail).\\n    \\\"\\\"\\\"\\n    node_data = _find_node_data(flow, component_id)\\n    if node_data is None:\\n        return None\\n    for output in node_data.get(\\\"node\\\", {}).get(\\\"outputs\\\", []):\\n        if output.get(\\\"name\\\") != port_name or not output.get(\\\"allows_loop\\\"):\\n            continue\\n        types = output.get(\\\"types\\\") or []\\n        selected = output.get(\\\"selected\\\") or (types[0] if types else \\\"Message\\\")\\n        accepted = [selected, *(output.get(\\\"loop_types\\\") or [])]\\n        data_type = node_data.get(\\\"type\\\") or (component_id.rsplit(\\\"-\\\", 1)[0] if \\\"-\\\" in component_id else \\\"\\\")\\n        return accepted, data_type\\n    return None\\n\\n\\ndef add_connection(\\n    flow: dict,\\n    source_id: str,\\n    source_output: str,\\n    target_id: str,\\n    target_input: str,\\n    source_types: list[str] | None = None,\\n    target_types: list[str] | None = None,\\n    registry: dict[str, dict] | None = None,\\n) -> dict:\\n    \\\"\\\"\\\"Add a connection (edge) between two components.\\n\\n    When source_types/target_types are None they are resolved from the flow\\n    and type-compatibility is enforced.  When the caller passes explicit types\\n    the check is skipped (the caller is taking responsibility).\\n\\n    When source_output is the synthesized \\\"component_as_tool\\\" handle, the\\n    source node is automatically flipped into tool mode before resolving\\n    types \u2014 this mirrors what the canvas does when a user drags from the\\n    Tool Mode toggle, and is required because the static component template\\n    does not list ``component_as_tool`` until tool mode is enabled.\\n\\n    ``registry`` is optional and consulted only for that tool-mode capability\\n    check, where it rescues nodes whose saved template predates the\\n    ``add_tool_output`` flag (see ``_node_supports_tool_mode``).\\n    \\\"\\\"\\\"\\n    # dataType must equal the node's live data.type or the frontend drops the edge\\n    # (generated components are typed \\\"CustomComponent\\\" but keep a class-named id).\\n    source_node_data = _find_node_data(flow, source_id)\\n    source_type = (source_node_data or {}).get(\\\"type\\\") or (\\n        source_id.rsplit(\\\"-\\\", 1)[0] if \\\"-\\\" in source_id else source_id\\n    )\\n\\n    # Raises ValueError when the source cannot be wrapped as a Tool, so the\\n    # LLM gets a clear domain error instead of \\\"output not found\\\".\\n    if source_output == _TOOL_OUTPUT_NAME:\\n        _enable_tool_mode(flow, source_id, registry)\\n\\n    # Resolve types from the flow's node data if not explicitly provided\\n    types_resolved = source_types is None and target_types is None\\n    if source_types is None:\\n        source_types = _resolve_output_types(flow, source_id, source_output)\\n    loop_target: tuple[list[str], str] | None = None\\n    if target_types is None:\\n        try:\\n            target_types, target_field_type = _resolve_input_types(flow, target_id, target_input)\\n        except ValueError:\\n            # Template inputs keep priority; only ports that are NOT template\\n            # inputs may resolve as loop inputs (allows_loop outputs).\\n            loop_target = _resolve_loop_target(flow, target_id, target_input)\\n            if loop_target is None:\\n                raise\\n            target_types = loop_target[0]\\n            target_field_type = \\\"\\\"\\n    else:\\n        target_field_type = \\\"str\\\"\\n        # Template inputs keep priority here too: a same-named allows_loop\\n        # output must not shadow a real template input (CollidingPorts case).\\n        if _has_template_input(flow, target_id, target_input):\\n            loop_target = None\\n        else:\\n            loop_target = _resolve_loop_target(flow, target_id, target_input)\\n\\n    if types_resolved and not types_compatible(source_types, target_types):\\n        msg = (\\n            f\\\"Type mismatch: output '{source_output}' on '{source_id}' produces {source_types}, \\\"\\n            f\\\"but input '{target_input}' on '{target_id}' accepts {target_types}.\\\"\\n            f\\\"{_conversion_hint(source_id, source_output, source_types, target_id, target_input, target_types)}\\\"\\n        )\\n        raise ValueError(msg)\\n\\n    source_handle_dict = {\\n        \\\"dataType\\\": source_type,\\n        \\\"id\\\": source_id,\\n        \\\"name\\\": source_output,\\n        \\\"output_types\\\": source_types,\\n    }\\n    if loop_target is not None:\\n        # Loop feedback edges use an output-shaped targetHandle \u2014 the runtime\\n        # branches on `\\\"name\\\" in target_handle` (lfx.graph.edge.base.Edge).\\n        target_handle_dict: dict[str, Any] = {\\n            \\\"dataType\\\": loop_target[1],\\n            \\\"id\\\": target_id,\\n            \\\"name\\\": target_input,\\n            \\\"output_types\\\": target_types,\\n        }\\n    else:\\n        target_handle_dict = {\\n            \\\"fieldName\\\": target_input,\\n            \\\"id\\\": target_id,\\n            \\\"inputTypes\\\": target_types,\\n            \\\"type\\\": target_field_type,\\n        }\\n\\n    source_handle_s = _scaped_json_stringify(source_handle_dict)\\n    target_handle_s = _scaped_json_stringify(target_handle_dict)\\n\\n    edge_id = f\\\"reactflow__edge-{source_id}{source_handle_s}-{target_id}{target_handle_s}\\\"\\n\\n    # Idempotency is structural (ids + port names), not by edge id: UI-saved\\n    # edges use a different id prefix (`xy-edge__` vs `reactflow__edge-`).\\n    for existing in flow[\\\"data\\\"][\\\"edges\\\"]:\\n        existing_target = (existing.get(\\\"data\\\") or {}).get(\\\"targetHandle\\\", {})\\n        existing_port = existing_target.get(\\\"fieldName\\\") or existing_target.get(\\\"name\\\")\\n        if (\\n            existing.get(\\\"source\\\") == source_id\\n            and existing.get(\\\"target\\\") == target_id\\n            and (existing.get(\\\"data\\\") or {}).get(\\\"sourceHandle\\\", {}).get(\\\"name\\\") == source_output\\n            and existing_port == target_input\\n        ):\\n            return existing\\n\\n    edge = {\\n        \\\"animated\\\": False,\\n        \\\"className\\\": \\\"\\\",\\n        \\\"data\\\": {\\n            \\\"sourceHandle\\\": source_handle_dict,\\n            \\\"targetHandle\\\": target_handle_dict,\\n        },\\n        \\\"id\\\": edge_id,\\n        \\\"selected\\\": False,\\n        \\\"source\\\": source_id,\\n        \\\"sourceHandle\\\": source_handle_s,\\n        \\\"target\\\": target_id,\\n        \\\"targetHandle\\\": target_handle_s,\\n    }\\n    flow[\\\"data\\\"][\\\"edges\\\"].append(edge)\\n    # Pinned here, not per-caller: the incremental edit tools and the external MCP\\n    # tools reach this function directly and never run the spec builder (LE-1776).\\n    sync_dropdown_selected_outputs(flow)\\n    return edge\\n\\n\\ndef remove_connection(\\n    flow: dict,\\n    source_id: str,\\n    target_id: str,\\n    source_output: str | None = None,\\n    target_input: str | None = None,\\n) -> int:\\n    \\\"\\\"\\\"Remove connections between two components. Returns count removed.\\\"\\\"\\\"\\n    edges = flow[\\\"data\\\"][\\\"edges\\\"]\\n    original_count = len(edges)\\n\\n    def keep(e: dict) -> bool:\\n        if e.get(\\\"source\\\") != source_id or e.get(\\\"target\\\") != target_id:\\n            return True\\n        if source_output and e.get(\\\"data\\\", {}).get(\\\"sourceHandle\\\", {}).get(\\\"name\\\") != source_output:\\n            return True\\n        if not target_input:\\n            return False\\n        target_handle = e.get(\\\"data\\\", {}).get(\\\"targetHandle\\\", {})\\n        return (target_handle.get(\\\"fieldName\\\") or target_handle.get(\\\"name\\\")) != target_input\\n\\n    flow[\\\"data\\\"][\\\"edges\\\"] = [e for e in edges if keep(e)]\\n    return original_count - len(flow[\\\"data\\\"][\\\"edges\\\"])\\n\\n\\ndef list_connections(flow: dict) -> list[dict]:\\n    \\\"\\\"\\\"List all connections in a flow.\\\"\\\"\\\"\\n    results = []\\n    for edge in flow.get(\\\"data\\\", {}).get(\\\"edges\\\", []):\\n        source_handle = edge.get(\\\"data\\\", {}).get(\\\"sourceHandle\\\", {})\\n        target_handle = edge.get(\\\"data\\\", {}).get(\\\"targetHandle\\\", {})\\n        results.append(\\n            {\\n                \\\"source_id\\\": edge.get(\\\"source\\\", \\\"\\\"),\\n                \\\"target_id\\\": edge.get(\\\"target\\\", \\\"\\\"),\\n                \\\"source_output\\\": source_handle.get(\\\"name\\\", \\\"\\\"),\\n                \\\"target_input\\\": target_handle.get(\\\"fieldName\\\") or target_handle.get(\\\"name\\\", \\\"\\\"),\\n                \\\"source_types\\\": source_handle.get(\\\"output_types\\\", []),\\n                \\\"target_types\\\": target_handle.get(\\\"inputTypes\\\") or target_handle.get(\\\"output_types\\\", []),\\n            }\\n        )\\n    return results\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/flow_builder/flow.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7b8d2a1cd4ddc9acead4d9c6fae0c8dbfdb3c47cbf3530d16d6dd44302275597\",\"content\":\"\\\"\\\"\\\"Flow creation and inspection.\\n\\nPure functions for creating flow dicts and extracting summaries.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\n\\ndef empty_flow(name: str = \\\"Untitled Flow\\\", description: str = \\\"\\\") -> dict:\\n    \\\"\\\"\\\"Create a minimal valid Langflow flow structure.\\\"\\\"\\\"\\n    return {\\n        \\\"name\\\": name,\\n        \\\"description\\\": description,\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [],\\n            \\\"edges\\\": [],\\n            \\\"viewport\\\": {\\\"x\\\": 0, \\\"y\\\": 0, \\\"zoom\\\": 1},\\n        },\\n    }\\n\\n\\ndef flow_info(flow: dict) -> dict:\\n    \\\"\\\"\\\"Extract summary information from a flow dict.\\\"\\\"\\\"\\n    data = flow.get(\\\"data\\\", {})\\n    nodes = data.get(\\\"nodes\\\", [])\\n    edges = data.get(\\\"edges\\\", [])\\n\\n    inputs = []\\n    outputs = []\\n    components = []\\n    for node in nodes:\\n        node_data = node.get(\\\"data\\\", {})\\n        node_config = node_data.get(\\\"node\\\", {})\\n        display_name = node_config.get(\\\"display_name\\\", node_data.get(\\\"type\\\", \\\"Unknown\\\"))\\n        node_type = node_data.get(\\\"type\\\", \\\"\\\")\\n        component_id = node_data.get(\\\"id\\\", node.get(\\\"id\\\", \\\"\\\"))\\n\\n        components.append(\\n            {\\n                \\\"id\\\": component_id,\\n                \\\"display_name\\\": display_name,\\n                \\\"type\\\": node_type,\\n            }\\n        )\\n\\n        if \\\"ChatInput\\\" in node_type or \\\"TextInput\\\" in node_type:\\n            inputs.append(component_id)\\n        if \\\"ChatOutput\\\" in node_type or \\\"TextOutput\\\" in node_type:\\n            outputs.append(component_id)\\n\\n    return {\\n        \\\"name\\\": flow.get(\\\"name\\\", \\\"Unknown\\\"),\\n        \\\"description\\\": flow.get(\\\"description\\\", \\\"\\\"),\\n        \\\"node_count\\\": len(nodes),\\n        \\\"edge_count\\\": len(edges),\\n        \\\"components\\\": components,\\n        \\\"inputs\\\": inputs,\\n        \\\"outputs\\\": outputs,\\n    }\\n\\n\\nEMPTY_CANVAS_SUMMARY = \\\"(empty canvas)\\\"\\n\\n\\ndef flow_to_spec_summary(flow: dict) -> str:\\n    \\\"\\\"\\\"Convert a flow dict to a compact summary with component IDs for LLM context.\\n\\n    Includes full component IDs so the agent can reference them in tool calls.\\n    Field values are NOT included -- the agent should use get_field_value to inspect.\\n    \\\"\\\"\\\"\\n    data = flow.get(\\\"data\\\", {})\\n    nodes = data.get(\\\"nodes\\\", [])\\n    edges = data.get(\\\"edges\\\", [])\\n\\n    if not nodes:\\n        return EMPTY_CANVAS_SUMMARY\\n\\n    id_to_type: dict[str, str] = {}\\n    lines = [f\\\"name: {flow.get('name', 'Untitled')}\\\"]\\n\\n    lines.append(\\\"\\\\ncomponents:\\\")\\n    for node in nodes:\\n        nd = node.get(\\\"data\\\", {})\\n        nid = nd.get(\\\"id\\\", node.get(\\\"id\\\", \\\"\\\"))\\n        ntype = nd.get(\\\"type\\\", \\\"?\\\")\\n        id_to_type[nid] = ntype\\n        lines.append(f\\\"  {nid}: {ntype}\\\")\\n\\n    if edges:\\n        lines.append(\\\"\\\\nconnections:\\\")\\n        for edge in edges:\\n            src = edge.get(\\\"source\\\", \\\"\\\")\\n            tgt = edge.get(\\\"target\\\", \\\"\\\")\\n            edge_data = edge.get(\\\"data\\\", {})\\n            src_handle = edge_data.get(\\\"sourceHandle\\\", {}).get(\\\"name\\\", \\\"?\\\")\\n            tgt_handle = edge_data.get(\\\"targetHandle\\\", {}).get(\\\"fieldName\\\", \\\"?\\\")\\n            lines.append(f\\\"  {src}.{src_handle} -> {tgt}.{tgt_handle}\\\")\\n\\n    return \\\"\\\\n\\\".join(lines)\\n\\n\\ndef flow_graph_repr(flow: dict) -> str:\\n    \\\"\\\"\\\"Build an ASCII DAG representation of a flow's graph.\\n\\n    Uses lfx's ASCII graph renderer (grandalf-based Sugiyama layout),\\n    falling back to a simple chain representation if unavailable.\\n    \\\"\\\"\\\"\\n    data = flow.get(\\\"data\\\", {})\\n    nodes = data.get(\\\"nodes\\\", [])\\n    edges = data.get(\\\"edges\\\", [])\\n\\n    if not nodes:\\n        return \\\"(empty)\\\"\\n\\n    # Build id -> label map, disambiguating duplicate types\\n    id_to_label: dict[str, str] = {}\\n    type_count: dict[str, int] = {}\\n    for node in nodes:\\n        nd = node.get(\\\"data\\\", {})\\n        nid = nd.get(\\\"id\\\", node.get(\\\"id\\\", \\\"\\\"))\\n        node_type = nd.get(\\\"type\\\", \\\"?\\\")\\n        count = type_count.get(node_type, 0) + 1\\n        type_count[node_type] = count\\n        id_to_label[nid] = f\\\"{node_type} #{count}\\\" if count > 1 else node_type\\n\\n    # Go back and suffix the first occurrence too when there are duplicates\\n    for nid, label in id_to_label.items():\\n        if \\\"#\\\" not in label and type_count.get(label, 0) > 1:\\n            id_to_label[nid] = f\\\"{label} #1\\\"\\n\\n    if not edges:\\n        return \\\", \\\".join(sorted(id_to_label.values()))\\n\\n    vertexes = list(id_to_label.values())\\n    edge_pairs = []\\n    for edge in edges:\\n        src_label = id_to_label.get(edge.get(\\\"source\\\", \\\"\\\"))\\n        tgt_label = id_to_label.get(edge.get(\\\"target\\\", \\\"\\\"))\\n        if src_label and tgt_label:\\n            edge_pairs.append((src_label, tgt_label))\\n\\n    try:\\n        from lfx.graph.graph.ascii import draw_graph\\n\\n        return draw_graph(vertexes, edge_pairs, return_ascii=True) or \\\"(empty)\\\"\\n    except ImportError:\\n        # grandalf not available; fall back to simple representation\\n        return \\\", \\\".join(f\\\"{s} -> {t}\\\" for s, t in edge_pairs)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/flow_builder/layout.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"642755ae627e16fd8b301ab7e437762cfc75b1b9dcafd334cc69dc4e0cb11e0f\",\"content\":\"\\\"\\\"\\\"Graph layout: assign positions to nodes using a layered algorithm.\\n\\nUses topological sorting to assign nodes to layers (columns),\\nthen spaces them out horizontally and vertically.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom collections import defaultdict, deque\\n\\nfrom lfx.graph.flow_builder._utils import node_id as _node_id\\n\\n# Canvas nodes render 384px wide (frontend NODE_WIDTH), so column spacing\\n# of 480 leaves a ~96px visual gap between layers.\\nLAYER_SPACING_X = 480\\nNODE_SPACING_Y = 350\\n\\n\\ndef layout_flow(flow: dict) -> None:\\n    \\\"\\\"\\\"Assign positions to all nodes in a flow based on edge topology.\\\"\\\"\\\"\\n    nodes = flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", [])\\n    edges = flow.get(\\\"data\\\", {}).get(\\\"edges\\\", [])\\n\\n    if not nodes:\\n        return\\n\\n    node_ids = [_node_id(n) for n in nodes]\\n    id_to_node = {_node_id(n): n for n in nodes}\\n\\n    # Build adjacency: source -> [targets]\\n    successors: dict[str, list[str]] = defaultdict(list)\\n    predecessors: dict[str, list[str]] = defaultdict(list)\\n    for edge in edges:\\n        src = edge.get(\\\"source\\\", \\\"\\\")\\n        tgt = edge.get(\\\"target\\\", \\\"\\\")\\n        if src in id_to_node and tgt in id_to_node:\\n            successors[src].append(tgt)\\n            predecessors[tgt].append(src)\\n\\n    # Assign layers via longest path from sources (nodes with no predecessors)\\n    layers = _assign_layers(node_ids, successors, predecessors)\\n\\n    # Group nodes by layer\\n    layer_groups: dict[int, list[str]] = defaultdict(list)\\n    for nid, layer in layers.items():\\n        layer_groups[layer].append(nid)\\n\\n    # Assign positions\\n    for layer_idx, group in sorted(layer_groups.items()):\\n        x = layer_idx * LAYER_SPACING_X\\n        total_height = (len(group) - 1) * NODE_SPACING_Y\\n        start_y = -total_height / 2\\n        for i, nid in enumerate(group):\\n            node = id_to_node[nid]\\n            node[\\\"position\\\"] = {\\\"x\\\": x, \\\"y\\\": start_y + i * NODE_SPACING_Y}\\n\\n\\ndef _assign_layers(\\n    node_ids: list[str],\\n    successors: dict[str, list[str]],\\n    predecessors: dict[str, list[str]],\\n) -> dict[str, int]:\\n    \\\"\\\"\\\"Assign each node to a layer using longest-path layering.\\\"\\\"\\\"\\n    layers: dict[str, int] = {}\\n    in_degree = {nid: len(predecessors.get(nid, [])) for nid in node_ids}\\n\\n    # Start with source nodes (no predecessors)\\n    queue = deque()\\n    for nid in node_ids:\\n        if in_degree[nid] == 0:\\n            queue.append(nid)\\n            layers[nid] = 0\\n\\n    # BFS: each node's layer = max(predecessor layers) + 1\\n    while queue:\\n        nid = queue.popleft()\\n        for succ in successors.get(nid, []):\\n            new_layer = layers[nid] + 1\\n            if succ not in layers or new_layer > layers[succ]:\\n                layers[succ] = new_layer\\n            in_degree[succ] -= 1\\n            if in_degree[succ] == 0:\\n                queue.append(succ)\\n\\n    # Handle disconnected nodes (no edges)\\n    next_layer = max(layers.values(), default=-1) + 1\\n    for nid in node_ids:\\n        if nid not in layers:\\n            layers[nid] = next_layer\\n            next_layer += 1\\n\\n    return layers\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/flow_builder/spec.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f5ff0bde694eb4781aceabb5291defbd09a5d148d095e45d029cd5f8f2228f73\",\"content\":\"\\\"\\\"\\\"Parse compact flow spec text into a structured dict.\\n\\nFormat:\\n    name: My Flow\\n    description: What it does\\n\\n    nodes:\\n      A: ChatInput\\n      B: OpenAIModel\\n      C: ChatOutput\\n\\n    edges:\\n      A.message -> B.input_value\\n      B.text_output -> C.input_value\\n\\n    config:\\n      B.model_name: gpt-4o\\n      B.temperature: 0.5\\n      C.system_prompt: |\\n        Multi-line value\\n        continues here.\\n\\nConfig values are auto-coerced: numbers become int/float, true/false\\nbecome booleans. Multi-line values (starting with ``|``) stay as\\nstrings. Continuation lines are dedented by up to 4 leading spaces.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport re\\n\\n# A config key is `Node.field` followed by ':' and an OPTIONAL inline\\n# value. The value is optional (and the space after ':' is optional) so a\\n# key whose value is on following lines \u2014 `C.model:` then a YAML list \u2014\\n# is still recognized as a NEW key and correctly terminates an open `|`\\n# block instead of being swallowed into it. Deterministic and\\n# LLM-agnostic: tolerates the format variations weaker models emit.\\n_CONFIG_KEY_RE = re.compile(r\\\"^(\\\\w+\\\\.\\\\w+):\\\\s*(.*)$\\\")\\n\\n\\ndef _coerce_value(v: str):\\n    \\\"\\\"\\\"Coerce a string value to int, float, bool, or None if applicable.\\\"\\\"\\\"\\n    if v.lower() == \\\"true\\\":\\n        return True\\n    if v.lower() == \\\"false\\\":\\n        return False\\n    if v.lower() in (\\\"null\\\", \\\"none\\\"):\\n        return None\\n    try:\\n        return int(v)\\n    except ValueError:\\n        pass\\n    try:\\n        return float(v)\\n    except ValueError:\\n        pass\\n    return v\\n\\n\\ndef parse_flow_spec(text: str) -> dict:\\n    \\\"\\\"\\\"Parse a flow spec string into a structured dict.\\n\\n    Returns:\\n        {\\n            \\\"name\\\": str,\\n            \\\"description\\\": str,\\n            \\\"nodes\\\": [{\\\"id\\\": \\\"A\\\", \\\"type\\\": \\\"ChatInput\\\"}, ...],\\n            \\\"edges\\\": [{\\\"source_id\\\": \\\"A\\\", \\\"source_output\\\": \\\"message\\\",\\n                        \\\"target_id\\\": \\\"B\\\", \\\"target_input\\\": \\\"input_value\\\"}, ...],\\n            \\\"config\\\": {\\\"A\\\": {\\\"field\\\": value, ...}, ...},\\n        }\\n    \\\"\\\"\\\"\\n    lines = text.strip().split(\\\"\\\\n\\\")\\n\\n    result: dict = {\\n        \\\"name\\\": \\\"\\\",\\n        \\\"description\\\": \\\"\\\",\\n        \\\"nodes\\\": [],\\n        \\\"edges\\\": [],\\n        \\\"config\\\": {},\\n    }\\n\\n    section: str | None = None\\n    current_config_key: str | None = None\\n    current_config_lines: list[str] = []\\n    current_config_is_multiline: bool = False\\n    config_key_indent: int | None = None  # indent level of config keys\\n\\n    def _flush_config():\\n        nonlocal current_config_key, current_config_lines, current_config_is_multiline\\n        if current_config_key and current_config_lines:\\n            node_id, field = current_config_key.split(\\\".\\\", 1)\\n            raw = \\\"\\\\n\\\".join(current_config_lines).strip()\\n            value = raw if current_config_is_multiline else _coerce_value(raw)\\n            result[\\\"config\\\"].setdefault(node_id, {})[field] = value\\n        current_config_key = None\\n        current_config_lines = []\\n        current_config_is_multiline = False\\n\\n    for raw_line in lines:\\n        line = raw_line.strip()\\n\\n        if not line:\\n            if section == \\\"config\\\" and current_config_key:\\n                current_config_lines.append(\\\"\\\")\\n            continue\\n\\n        # Top-level keys\\n        if line == \\\"nodes:\\\":\\n            _flush_config()\\n            section = \\\"nodes\\\"\\n            continue\\n        if line == \\\"edges:\\\":\\n            _flush_config()\\n            section = \\\"edges\\\"\\n            continue\\n        if line == \\\"config:\\\":\\n            _flush_config()\\n            section = \\\"config\\\"\\n            continue\\n\\n        if section is None:\\n            if line.startswith(\\\"name:\\\"):\\n                result[\\\"name\\\"] = line[5:].strip()\\n            elif line.startswith(\\\"description:\\\"):\\n                result[\\\"description\\\"] = line[12:].strip()\\n            else:\\n                msg = f\\\"Unrecognized line: '{line}'. Expected 'name:', 'description:', or a section header.\\\"\\n                raise ValueError(msg)\\n            continue\\n\\n        _expected_split_parts = 2\\n\\n        if section == \\\"nodes\\\":\\n            # \\\"A: ChatInput\\\"\\n            parts = line.split(\\\":\\\", 1)\\n            if len(parts) != _expected_split_parts:\\n                msg = f\\\"Invalid node definition: '{line}'. Expected format: 'ID: ComponentType'\\\"\\n                raise ValueError(msg)\\n            result[\\\"nodes\\\"].append(\\n                {\\n                    \\\"id\\\": parts[0].strip(),\\n                    \\\"type\\\": parts[1].strip(),\\n                }\\n            )\\n\\n        elif section == \\\"edges\\\":\\n            # \\\"A.message -> B.input_value\\\"\\n            if \\\" -> \\\" not in line:\\n                msg = f\\\"Invalid edge definition: '{line}'. Expected format: 'Node.output -> Node.input'\\\"\\n                raise ValueError(msg)\\n            left, right = line.split(\\\" -> \\\", 1)\\n            src_parts = left.strip().split(\\\".\\\", 1)\\n            tgt_parts = right.strip().split(\\\".\\\", 1)\\n            if len(src_parts) != _expected_split_parts or len(tgt_parts) != _expected_split_parts:\\n                msg = f\\\"Invalid edge definition: '{line}'. Both sides must be 'Node.port'\\\"\\n                raise ValueError(msg)\\n            result[\\\"edges\\\"].append(\\n                {\\n                    \\\"source_id\\\": src_parts[0],\\n                    \\\"source_output\\\": src_parts[1],\\n                    \\\"target_id\\\": tgt_parts[0],\\n                    \\\"target_input\\\": tgt_parts[1],\\n                }\\n            )\\n\\n        elif section == \\\"config\\\":\\n            # Determine indentation of this line\\n            line_indent = len(raw_line) - len(raw_line.lstrip())\\n\\n            # In multiline mode, lines indented deeper than the key level\\n            # are continuations, not new keys.\\n            is_continuation = (\\n                current_config_is_multiline and config_key_indent is not None and line_indent > config_key_indent\\n            )\\n\\n            if not is_continuation:\\n                match = _CONFIG_KEY_RE.match(line)\\n                if match:\\n                    _flush_config()\\n                    if config_key_indent is None:\\n                        config_key_indent = line_indent\\n                    current_config_key = match.group(1)\\n                    value = match.group(2)\\n                    current_config_lines = []\\n                    if value == \\\"|\\\":\\n                        current_config_is_multiline = True\\n                    elif value:\\n                        current_config_lines.append(value)\\n                    continue\\n                if not current_config_key:\\n                    msg = f\\\"Invalid config entry: '{line}'. Expected format: 'Node.field: value'\\\"\\n                    raise ValueError(msg)\\n\\n            # Continuation of multi-line value\\n            if current_config_key:\\n                # Preserve relative indentation (strip up to 4 leading spaces)\\n                stripped = raw_line\\n                for _ in range(4):\\n                    stripped = stripped.removeprefix(\\\" \\\")\\n                current_config_lines.append(stripped)\\n\\n    _flush_config()\\n\\n    if not result[\\\"nodes\\\"]:\\n        msg = \\\"No nodes found in spec. Expected 'nodes:' section with 'ID: Type' entries.\\\"\\n        raise ValueError(msg)\\n\\n    return result\\n\\n\\ndef validate_spec_references(parsed: dict) -> None:\\n    \\\"\\\"\\\"Validate that all edge and config references point to existing nodes.\\n\\n    This is extracted as a shared function because the same validation\\n    is needed in create_flow_from_spec, update_flow_from_spec, and\\n    build_flow_from_spec. Keeping it in one place prevents the three\\n    copies from drifting out of sync.\\n\\n    Raises:\\n        ValueError: If any reference points to an unknown node.\\n    \\\"\\\"\\\"\\n    node_ids = {n[\\\"id\\\"] for n in parsed.get(\\\"nodes\\\", [])}\\n    for spec_id in parsed.get(\\\"config\\\", {}):\\n        if spec_id not in node_ids:\\n            msg = f\\\"Config references unknown node '{spec_id}'. Available: {sorted(node_ids)}\\\"\\n            raise ValueError(msg)\\n    for edge in parsed.get(\\\"edges\\\", []):\\n        if edge[\\\"source_id\\\"] not in node_ids:\\n            msg = f\\\"Edge references unknown source '{edge['source_id']}'. Available: {sorted(node_ids)}\\\"\\n            raise ValueError(msg)\\n        if edge[\\\"target_id\\\"] not in node_ids:\\n            msg = f\\\"Edge references unknown target '{edge['target_id']}'. Available: {sorted(node_ids)}\\\"\\n            raise ValueError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/graph/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/graph/ascii.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fa361623f666cf6e267cb3b126bcc820d67475b42077d3d725fab065ad37c5ab\",\"content\":\"\\\"\\\"\\\"This code is adapted from the DVC project.\\n\\nOriginal source:\\nhttps://github.com/iterative/dvc/blob/c5bac1c8cfdb2c0f54d52ac61ff754e6f583822a/dvc/dagascii.py\\n\\nThe original code has been modified to focus on drawing a Directed Acyclic Graph (DAG) in ASCII\\nusing the `grandalf` library. Non-essential parts have been removed, and the code has been\\nrefactored to suit this specific use case.\\n\\n\\n\\\"\\\"\\\"\\n\\nimport math\\n\\nfrom grandalf.graphs import Edge as GrandalfEdge\\nfrom grandalf.graphs import Graph as GrandalfGraph\\nfrom grandalf.graphs import Vertex as GrandalfVertex\\nfrom grandalf.layouts import SugiyamaLayout\\nfrom grandalf.routing import EdgeViewer, route_with_lines\\n\\nMINIMUM_EDGE_VIEW_POINTS = 2\\n\\n\\nclass VertexViewer:\\n    \\\"\\\"\\\"Class to define vertex box boundaries that will be accounted for during graph building by grandalf.\\\"\\\"\\\"\\n\\n    HEIGHT = 3  # top and bottom box edges + text\\n\\n    def __init__(self, name) -> None:\\n        self._h = self.HEIGHT  # top and bottom box edges + text\\n        self._w = len(name) + 2  # right and left bottom edges + text\\n\\n    @property\\n    def h(self):\\n        return self._h\\n\\n    @property\\n    def w(self):\\n        return self._w\\n\\n\\nclass AsciiCanvas:\\n    \\\"\\\"\\\"Class for drawing in ASCII.\\\"\\\"\\\"\\n\\n    def __init__(self, cols, lines) -> None:\\n        if cols <= 1:\\n            msg = \\\"cols must be greater than 1\\\"\\n            raise ValueError(msg)\\n        if lines <= 1:\\n            msg = \\\"lines must be greater than 1\\\"\\n            raise ValueError(msg)\\n        self.cols = cols\\n        self.lines = lines\\n        self.canvas = [[\\\" \\\"] * cols for _ in range(lines)]\\n\\n    def get_lines(self):\\n        return map(\\\"\\\".join, self.canvas)\\n\\n    def draws(self):\\n        return \\\"\\\\n\\\".join(self.get_lines())\\n\\n    def draw(self) -> None:\\n        \\\"\\\"\\\"Draws ASCII canvas on the screen.\\\"\\\"\\\"\\n        lines = self.get_lines()\\n        print(\\\"\\\\n\\\".join(lines))  # noqa: T201\\n\\n    def point(self, x, y, char) -> None:\\n        \\\"\\\"\\\"Create a point on ASCII canvas.\\\"\\\"\\\"\\n        if len(char) != 1:\\n            msg = \\\"char must be a single character\\\"\\n            raise ValueError(msg)\\n        if x < 0 or x >= self.cols:\\n            msg = \\\"x is out of bounds\\\"\\n            raise ValueError(msg)\\n        if y < 0 or y >= self.lines:\\n            msg = \\\"y is out of bounds\\\"\\n            raise ValueError(msg)\\n        self.canvas[y][x] = char\\n\\n    def line(self, x0, y0, x1, y1, char) -> None:\\n        \\\"\\\"\\\"Create a line on ASCII canvas.\\\"\\\"\\\"\\n        if x0 > x1:\\n            x1, x0 = x0, x1\\n            y1, y0 = y0, y1\\n\\n        dx = x1 - x0\\n        dy = y1 - y0\\n\\n        if dx == 0 and dy == 0:\\n            self.point(x0, y0, char)\\n        elif abs(dx) >= abs(dy):\\n            for x in range(x0, x1 + 1):\\n                y = y0 + round((x - x0) * dy / float(dx)) if dx else y0\\n                self.point(x, y, char)\\n        else:\\n            for y in range(min(y0, y1), max(y0, y1) + 1):\\n                x = x0 + round((y - y0) * dx / float(dy)) if dy else x0\\n                self.point(x, y, char)\\n\\n    def text(self, x, y, text) -> None:\\n        \\\"\\\"\\\"Print a text on ASCII canvas.\\\"\\\"\\\"\\n        for i, char in enumerate(text):\\n            self.point(x + i, y, char)\\n\\n    def box(self, x0, y0, width, height) -> None:\\n        \\\"\\\"\\\"Create a box on ASCII canvas.\\\"\\\"\\\"\\n        if width <= 1:\\n            msg = \\\"width must be greater than 1\\\"\\n            raise ValueError(msg)\\n        if height <= 1:\\n            msg = \\\"height must be greater than 1\\\"\\n            raise ValueError(msg)\\n        width -= 1\\n        height -= 1\\n\\n        for x in range(x0, x0 + width):\\n            self.point(x, y0, \\\"-\\\")\\n            self.point(x, y0 + height, \\\"-\\\")\\n        for y in range(y0, y0 + height):\\n            self.point(x0, y, \\\"|\\\")\\n            self.point(x0 + width, y, \\\"|\\\")\\n        self.point(x0, y0, \\\"+\\\")\\n        self.point(x0 + width, y0, \\\"+\\\")\\n        self.point(x0, y0 + height, \\\"+\\\")\\n        self.point(x0 + width, y0 + height, \\\"+\\\")\\n\\n\\ndef build_sugiyama_layout(vertexes, edges):\\n    vertexes = {v: GrandalfVertex(v) for v in vertexes}\\n    edges = [GrandalfEdge(vertexes[s], vertexes[e]) for s, e in edges]\\n    graph = GrandalfGraph(vertexes.values(), edges)\\n\\n    for vertex in vertexes.values():\\n        vertex.view = VertexViewer(vertex.data)\\n\\n    minw = min(v.view.w for v in vertexes.values())\\n\\n    for edge in edges:\\n        edge.view = EdgeViewer()\\n\\n    sug = SugiyamaLayout(graph.C[0])\\n    roots = [v for v in sug.g.sV if len(v.e_in()) == 0]\\n    sug.init_all(roots=roots, optimize=True)\\n\\n    sug.yspace = VertexViewer.HEIGHT\\n    sug.xspace = minw\\n    sug.route_edge = route_with_lines\\n\\n    sug.draw()\\n    return sug\\n\\n\\ndef draw_graph(vertexes, edges, *, return_ascii=True):\\n    \\\"\\\"\\\"Build a DAG and draw it in ASCII.\\\"\\\"\\\"\\n    sug = build_sugiyama_layout(vertexes, edges)\\n\\n    xlist = []\\n    ylist = []\\n\\n    for vertex in sug.g.sV:\\n        xlist.extend([vertex.view.xy[0] - vertex.view.w / 2.0, vertex.view.xy[0] + vertex.view.w / 2.0])\\n        ylist.extend([vertex.view.xy[1], vertex.view.xy[1] + vertex.view.h])\\n\\n    for edge in sug.g.sE:\\n        for x, y in edge.view._pts:\\n            xlist.append(x)\\n            ylist.append(y)\\n\\n    minx = min(xlist)\\n    miny = min(ylist)\\n    maxx = max(xlist)\\n    maxy = max(ylist)\\n\\n    canvas_cols = math.ceil(maxx - minx) + 1\\n    canvas_lines = round(maxy - miny)\\n\\n    canvas = AsciiCanvas(canvas_cols, canvas_lines)\\n\\n    for edge in sug.g.sE:\\n        if len(edge.view._pts) < MINIMUM_EDGE_VIEW_POINTS:\\n            msg = \\\"edge.view._pts must have at least 2 points\\\"\\n            raise ValueError(msg)\\n        for index in range(1, len(edge.view._pts)):\\n            start = edge.view._pts[index - 1]\\n            end = edge.view._pts[index]\\n            canvas.line(\\n                round(start[0] - minx),\\n                round(start[1] - miny),\\n                round(end[0] - minx),\\n                round(end[1] - miny),\\n                \\\"*\\\",\\n            )\\n\\n    for vertex in sug.g.sV:\\n        x = vertex.view.xy[0] - vertex.view.w / 2.0\\n        y = vertex.view.xy[1]\\n        canvas.box(round(x - minx), round(y - miny), vertex.view.w, vertex.view.h)\\n        canvas.text(round(x - minx) + 1, round(y - miny) + 1, vertex.data)\\n    if return_ascii:\\n        return canvas.draws()\\n    canvas.draw()\\n    return None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/graph/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"55a6129c431f818e264ef12b415fd6cc177fc433d34f0cda5c89716e3ce1d4ad\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nimport contextvars\\nimport copy\\nimport json\\nimport queue\\nimport sys\\nimport threading\\nimport traceback\\nimport uuid\\nfrom collections import defaultdict, deque\\nfrom datetime import datetime, timezone\\nfrom functools import partial\\nfrom itertools import chain\\nfrom typing import TYPE_CHECKING, Any, cast\\n\\nfrom ag_ui.core import RunFinishedEvent, RunStartedEvent\\n\\nfrom lfx.exceptions.component import ComponentBuildError\\nfrom lfx.graph.edge.base import CycleEdge, Edge\\nfrom lfx.graph.exceptions import GraphPausedException\\nfrom lfx.graph.graph.constants import Finish, lazy_load_vertex_dict\\nfrom lfx.graph.graph.runnable_vertices_manager import RunnableVerticesManager\\nfrom lfx.graph.graph.schema import GraphData, GraphDump, StartConfigDict, VertexBuildResult\\nfrom lfx.graph.graph.state_model import create_state_model_from_graph\\nfrom lfx.graph.graph.utils import (\\n    find_all_cycle_edges,\\n    find_cycle_vertices,\\n    find_start_component_id,\\n    get_sorted_vertices,\\n    process_flow,\\n    should_continue,\\n)\\nfrom lfx.graph.schema import InterfaceComponentTypes, RunOutputs\\nfrom lfx.graph.utils import log_vertex_build\\nfrom lfx.graph.vertex.base import Vertex, VertexStates\\nfrom lfx.graph.vertex.schema import NodeData, NodeTypeEnum\\nfrom lfx.graph.vertex.vertex_types import ComponentVertex, InterfaceVertex, StateVertex\\nfrom lfx.log.logger import LogConfig, configure, logger\\nfrom lfx.observability import (\\n    APPLICATION_TRACER_NAME,\\n    _root_error_type,\\n    get_execution_client,\\n    get_execution_protocol,\\n    get_queued_trace_link,\\n)\\nfrom lfx.schema.dotdict import dotdict\\nfrom lfx.schema.schema import INPUT_FIELD_NAME, InputType, OutputValue\\nfrom lfx.services.cache.utils import CacheMiss\\nfrom lfx.services.deps import get_chat_service, get_tracing_service\\nfrom lfx.utils.async_helpers import run_until_complete\\n\\ntry:\\n    from opentelemetry import trace as otel_trace\\n    from opentelemetry.context import Context as OtelContext\\nexcept ImportError:\\n    # lfx does not depend on opentelemetry. Under langflow it is installed and the application\\n    # span is emitted; under bare lfx this stays None and the span code path is a no-op.\\n    otel_trace = None\\n    OtelContext = None\\n\\nFLOW_EXECUTION_SPAN_NAME = \\\"flow.execute\\\"\\n\\n\\nclass FlowSpanScope:\\n    \\\"\\\"\\\"Lets a driver that handles its own component errors still mark the run as failed.\\n\\n    The /build vertex walk catches a component exception, turns it into an error output for the\\n    client and stops walking, rather than re-raising. The span's own except clauses therefore\\n    never see it, and without this the run would be exported as a success. Callers that let\\n    exceptions propagate (arun, async_start, process) need none of this and ignore the scope.\\n\\n    Only the exception *type* is accepted, never the message: component output ends up in those\\n    messages and must not reach the operator's APM.\\n    \\\"\\\"\\\"\\n\\n    __slots__ = (\\\"error_type\\\",)\\n\\n    def __init__(self) -> None:\\n        self.error_type: str | None = None\\n\\n    def record_error(self, error_type: str) -> None:\\n        self.error_type = error_type\\n\\n\\nINPUT_TYPE_COMPONENT_TYPES = {\\n    \\\"chat\\\": {InterfaceComponentTypes.ChatInput.value},\\n    \\\"text\\\": {InterfaceComponentTypes.TextInput.value},\\n}\\n\\nif TYPE_CHECKING:\\n    from collections.abc import AsyncIterator, Callable, Generator, Iterable\\n    from typing import Any\\n\\n    from lfx.custom.custom_component.component import Component\\n    from lfx.events.event_manager import EventManager\\n    from lfx.graph.checkpoint.schema import GraphCheckpoint\\n    from lfx.graph.checkpoint.store import CheckpointStore\\n    from lfx.graph.edge.schema import EdgeData\\n    from lfx.graph.schema import ResultData\\n    from lfx.schema.schema import InputValueRequest\\n    from lfx.services.chat.schema import GetCache, SetCache\\n    from lfx.services.tracing.service import TracingService\\n\\n\\ndef _serving_trace_end_user_enabled() -> bool:\\n    \\\"\\\"\\\"Whether the operator opted into forwarding the end-user id to the tracing provider (I4).\\n\\n    Default False (fail-closed): the end-user id is PII and tracing providers are third-party. Reads\\n    the serving setting lazily; any resolution failure (lfx-standalone / no settings) is treated as\\n    off so telemetry never leaks the identity by accident.\\n    \\\"\\\"\\\"\\n    try:\\n        from lfx.services.deps import get_settings_service\\n\\n        settings_service = get_settings_service()\\n    except (ImportError, AttributeError, RuntimeError):\\n        return False\\n    if settings_service is None:\\n        return False\\n    return bool(getattr(settings_service.settings, \\\"serving_trace_end_user\\\", False))\\n\\n\\nclass Graph:\\n    \\\"\\\"\\\"A class representing a graph of vertices and edges.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        start: Component | None = None,\\n        end: Component | None = None,\\n        flow_id: str | None = None,\\n        flow_name: str | None = None,\\n        description: str | None = None,\\n        user_id: str | None = None,\\n        log_config: LogConfig | None = None,\\n        context: dict[str, Any] | None = None,\\n        *,\\n        instantiate_components: bool = True,\\n    ) -> None:\\n        \\\"\\\"\\\"Initializes a new Graph instance.\\n\\n        If both start and end components are provided, the graph is initialized and prepared for execution.\\n        If only one is provided, a ValueError is raised. The context must be a dictionary if specified,\\n        otherwise a TypeError is raised. Internal data structures for vertices, edges, state management,\\n        run management, and tracing are set up during initialization.\\n        \\\"\\\"\\\"\\n        if log_config:\\n            configure(**log_config)\\n\\n        self._start = start\\n        self._state_model = None\\n        self._end = end\\n        self._prepared = False\\n        self._runs = 0\\n        self._updates = 0\\n        self.flow_id = flow_id\\n        # Server-set provenance for a public flow whose execution uses a virtual\\n        # flow_id. Request data must never populate this storage scope.\\n        self.source_flow_id: str | None = None\\n        self.flow_name = flow_name\\n        self.description = description\\n        self.user_id = user_id\\n        # Warm-registry templates need the parsed graph structure without\\n        # executing component constructors at preload/reconcile time. Normal\\n        # graphs keep the historical eager-instantiation behavior.\\n        self._instantiate_components_on_initialize = instantiate_components\\n        # Warm parsing cannot emit migration/error events into an authenticated\\n        # user's keyspace. Such templates stay cold-only so request parsing can\\n        # preserve the historical per-user extension-event contract.\\n        self.requires_extension_event_replay = False\\n        # Optional caller-supplied label forwarded to tracing providers. Kept\\n        # distinct from ``self.user_id`` so request-supplied identifiers can be\\n        # surfaced in external traces (e.g. Langfuse trace metadata) without\\n        # leaking into authn/authz paths.\\n        self.tracing_user_id: str | None = None\\n        # Serving-plane end-user id (the gateway-injected identity for this run).\\n        # In-memory only, never persisted: the single carrier every service reads to\\n        # scope memory (and, later, telemetry and agent file writes) to the end user\\n        # while execution still runs as ``self.user_id`` (the service account). ``None``\\n        # on the editor plane and for anonymous/feature-off runs, so those paths are\\n        # byte-for-byte unchanged.\\n        self.end_user_id: str | None = None\\n        self._is_input_vertices: list[str] = []\\n        self._is_output_vertices: list[str] = []\\n        self._is_state_vertices: list[str] | None = None\\n        self.has_session_id_vertices: list[str] = []\\n        self._sorted_vertices_layers: list[list[str]] = []\\n        self._run_id = \\\"\\\"\\n        self._session_id = \\\"\\\"\\n        # Whether components in this run may persist chat memory. Set False for\\n        # anonymous serving-plane runs (ephemeral); bound per component execution\\n        # in get_instance_results so astore_message can skip the DB write.\\n        self.persist_messages: bool = True\\n        self._start_time = datetime.now(timezone.utc)\\n        self.inactivated_vertices: set = set()\\n        # Branch stops are transient and must be released by the vertex that\\n        # created them. The graph can execute sibling vertices concurrently, so\\n        # a graph-wide reset when one sibling finishes would otherwise revive a\\n        # branch stopped by another sibling that is still running.\\n        self.branch_inactivation_sources: dict[str, set[str]] = {}\\n        self.activated_vertices: list[str] = []\\n        self.vertices_layers: list[list[str]] = []\\n        self.vertices_to_run: set[str] = set()\\n        self.stop_vertex: str | None = None\\n        self.inactive_vertices: set = set()\\n        # Conditional routing system (separate from ACTIVE/INACTIVE cycle management)\\n        self.conditionally_excluded_vertices: set = set()  # Vertices excluded by conditional routing\\n        self.conditional_exclusion_sources: dict[str, set[str]] = {}  # Maps source vertex -> excluded vertices\\n        self.edges: list[CycleEdge] = []\\n        self.vertices: list[Vertex] = []\\n        self.run_manager = RunnableVerticesManager()\\n        self._vertices: list[NodeData] = []\\n        self._edges: list[EdgeData] = []\\n\\n        self.top_level_vertices: list[str] = []\\n        self.vertex_map: dict[str, Vertex] = {}\\n        self.predecessor_map: dict[str, list[str]] = defaultdict(list)\\n        self.successor_map: dict[str, list[str]] = defaultdict(list)\\n        self.in_degree_map: dict[str, int] = defaultdict(int)\\n        self.parent_child_map: dict[str, list[str]] = defaultdict(list)\\n        self._run_queue: deque[str] = deque()\\n        self._first_layer: list[str] = []\\n        self._lock: asyncio.Lock | None = None\\n        self.raw_graph_data: GraphData = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        self._is_cyclic: bool | None = None\\n        self._cycles: list[tuple[str, str]] | None = None\\n        self._cycle_vertices: set[str] | None = None\\n        self._call_order: list[str] = []\\n        self._snapshots: list[dict[str, Any]] = []\\n        self._end_trace_tasks: set[asyncio.Task] = set()\\n        self._is_subgraph = False\\n        self.checkpointing_enabled = False\\n        self.pause_requested = False\\n        self.pause_info: dict[str, Any] | None = None\\n        self.checkpoint_store: CheckpointStore | None = None\\n        self.job_id: str | None = None\\n        self.resumed_from_checkpoint = False\\n        # Vertices already built at checkpoint time: on resume their async generators are exhausted,\\n        # so the output-collection loop must NOT re-consume them. Empty for fresh (non-resume) runs.\\n        self.checkpoint_restored_built_ids: set[str] = set()\\n        # Built vertices whose live output (Tool/model client) was opaque-dropped to None in the\\n        # checkpoint: only these re-run on resume to regenerate the object, so producers whose output\\n        # round-tripped (e.g. an Agent's Message) are not needlessly re-executed. Empty otherwise.\\n        self.checkpoint_opaque_dropped_ids: set[str] = set()\\n        self.pause_probe: Callable[[str], Any] | None = None\\n\\n        if context and not isinstance(context, dict):\\n            msg = \\\"Context must be a dictionary\\\"\\n            raise TypeError(msg)\\n        self._context = dotdict(context or {})\\n        # Lazy initialization - only get tracing service when needed\\n        self._tracing_service: TracingService | None = None\\n        self._tracing_service_initialized = False\\n        if start is not None and end is not None:\\n            self._set_start_and_end(start, end)\\n            self.prepare(start_component_id=start.get_id())\\n        if (start is not None and end is None) or (start is None and end is not None):\\n            msg = \\\"You must provide both input and output components\\\"\\n            raise ValueError(msg)\\n\\n    @property\\n    def lock(self):\\n        \\\"\\\"\\\"Lazy initialization of asyncio.Lock to avoid event loop binding issues.\\\"\\\"\\\"\\n        if self._lock is None:\\n            self._lock = asyncio.Lock()\\n        return self._lock\\n\\n    @property\\n    def context(self) -> dotdict:\\n        if isinstance(self._context, dotdict):\\n            return self._context\\n        return dotdict(self._context)\\n\\n    @context.setter\\n    def context(self, value: dict[str, Any]):\\n        if not isinstance(value, dict):\\n            msg = \\\"Context must be a dictionary\\\"\\n            raise TypeError(msg)\\n        if isinstance(value, dict):\\n            value = dotdict(value)\\n        self._context = value\\n\\n    @property\\n    def session_id(self):\\n        return self._session_id\\n\\n    @session_id.setter\\n    def session_id(self, value: str):\\n        self._session_id = value\\n\\n    @property\\n    def state_model(self):\\n        if not self._state_model:\\n            self._state_model = create_state_model_from_graph(self)\\n        return self._state_model\\n\\n    def __add__(self, other):\\n        if not isinstance(other, Graph):\\n            msg = \\\"Can only add Graph objects\\\"\\n            raise TypeError(msg)\\n        # Add the vertices and edges from the other graph to this graph\\n        new_instance = copy.deepcopy(self)\\n        for vertex in other.vertices:\\n            # This updates the edges as well\\n            new_instance.add_vertex(vertex)\\n        new_instance.build_graph_maps(new_instance.edges)\\n        new_instance.define_vertices_lists()\\n        return new_instance\\n\\n    def __iadd__(self, other):\\n        if not isinstance(other, Graph):\\n            msg = \\\"Can only add Graph objects\\\"\\n            raise TypeError(msg)\\n        # Add the vertices and edges from the other graph to this graph\\n        for vertex in other.vertices:\\n            # This updates the edges as well\\n            self.add_vertex(vertex)\\n        self.build_graph_maps(self.edges)\\n        self.define_vertices_lists()\\n        return self\\n\\n    @property\\n    def tracing_service(self) -> TracingService | None:\\n        \\\"\\\"\\\"Lazily initialize tracing service only when accessed.\\\"\\\"\\\"\\n        if not self._tracing_service_initialized:\\n            try:\\n                self._tracing_service = get_tracing_service()\\n            except Exception:  # noqa: BLE001\\n                logger.exception(\\\"Error getting tracing service\\\")\\n                self._tracing_service = None\\n            self._tracing_service_initialized = True\\n        return self._tracing_service\\n\\n    def dumps(\\n        self,\\n        name: str | None = None,\\n        description: str | None = None,\\n        endpoint_name: str | None = None,\\n    ) -> str:\\n        graph_dict = self.dump(name, description, endpoint_name)\\n        return json.dumps(graph_dict, indent=4, sort_keys=True)\\n\\n    def dump(\\n        self, name: str | None = None, description: str | None = None, endpoint_name: str | None = None\\n    ) -> GraphDump:\\n        if self.raw_graph_data != {\\\"nodes\\\": [], \\\"edges\\\": []}:\\n            data_dict = self.raw_graph_data\\n        else:\\n            # we need to convert the vertices and edges to json\\n            nodes = [node.to_data() for node in self.vertices]\\n            edges = [edge.to_data() for edge in self.edges]\\n            self.raw_graph_data = {\\\"nodes\\\": nodes, \\\"edges\\\": edges}\\n            data_dict = self.raw_graph_data\\n        graph_dict: GraphDump = {\\n            \\\"data\\\": data_dict,\\n            \\\"is_component\\\": len(data_dict.get(\\\"nodes\\\", [])) == 1 and data_dict[\\\"edges\\\"] == [],\\n        }\\n        if name:\\n            graph_dict[\\\"name\\\"] = name\\n        elif name is None and self.flow_name:\\n            graph_dict[\\\"name\\\"] = self.flow_name\\n        if description:\\n            graph_dict[\\\"description\\\"] = description\\n        elif description is None and self.description:\\n            graph_dict[\\\"description\\\"] = self.description\\n        if endpoint_name is not None:\\n            graph_dict[\\\"endpoint_name\\\"] = str(endpoint_name)\\n        return graph_dict\\n\\n    def add_nodes_and_edges(self, nodes: list[NodeData], edges: list[EdgeData]) -> None:\\n        self._vertices = nodes\\n        self._edges = edges\\n        self.raw_graph_data = {\\\"nodes\\\": nodes, \\\"edges\\\": edges}\\n        self.top_level_vertices = []\\n        for vertex in self._vertices:\\n            if vertex_id := vertex.get(\\\"id\\\"):\\n                self.top_level_vertices.append(vertex_id)\\n\\n        self._cycle_vertices = None\\n        self._is_cyclic = None\\n        self._graph_data = process_flow(self.raw_graph_data)\\n\\n        self._vertices = self._graph_data[\\\"nodes\\\"]\\n        self._edges = self._graph_data[\\\"edges\\\"]\\n        self._cycle_vertices = None\\n        self._is_cyclic = None\\n        self.run_manager.cycle_vertices.clear()\\n        self.initialize()\\n\\n    def add_component(self, component: Component, component_id: str | None = None) -> str:\\n        component_id = component_id or component.get_id()\\n        if component_id in self.vertex_map:\\n            return component_id\\n        component.set_id(component_id)\\n        if component_id in self.vertex_map:\\n            msg = f\\\"Component ID {component_id} already exists\\\"\\n            raise ValueError(msg)\\n        frontend_node = component.to_frontend_node()\\n        self._vertices.append(frontend_node)\\n        vertex = self._create_vertex(frontend_node)\\n        vertex.add_component_instance(component)\\n        self._add_vertex(vertex)\\n        if component.get_edges():\\n            for edge in component.get_edges():\\n                self._add_edge(edge)\\n\\n        if component.get_components():\\n            for _component in component.get_components():\\n                self.add_component(_component)\\n\\n        return component_id\\n\\n    def _set_start_and_end(self, start: Component, end: Component) -> None:\\n        if not hasattr(start, \\\"to_frontend_node\\\"):\\n            msg = f\\\"start must be a Component. Got {type(start)}\\\"\\n            raise TypeError(msg)\\n        if not hasattr(end, \\\"to_frontend_node\\\"):\\n            msg = f\\\"end must be a Component. Got {type(end)}\\\"\\n            raise TypeError(msg)\\n        self.add_component(start, start.get_id())\\n        self.add_component(end, end.get_id())\\n\\n    def add_component_edge(self, source_id: str, output_input_tuple: tuple[str, str], target_id: str) -> None:\\n        source_vertex = self.get_vertex(source_id)\\n        if not isinstance(source_vertex, ComponentVertex):\\n            msg = f\\\"Source vertex {source_id} is not a component vertex.\\\"\\n            raise TypeError(msg)\\n        target_vertex = self.get_vertex(target_id)\\n        if not isinstance(target_vertex, ComponentVertex):\\n            msg = f\\\"Target vertex {target_id} is not a component vertex.\\\"\\n            raise TypeError(msg)\\n        output_name, input_name = output_input_tuple\\n        if source_vertex.custom_component is None:\\n            msg = f\\\"Source vertex {source_id} does not have a custom component.\\\"\\n            raise ValueError(msg)\\n        if target_vertex.custom_component is None:\\n            msg = f\\\"Target vertex {target_id} does not have a custom component.\\\"\\n            raise ValueError(msg)\\n\\n        try:\\n            input_field = target_vertex.get_input(input_name)\\n            input_types = input_field.input_types\\n            input_field_type = str(input_field.field_type)\\n        except ValueError as e:\\n            input_field = target_vertex.data.get(\\\"node\\\", {}).get(\\\"template\\\", {}).get(input_name)\\n            if not input_field:\\n                msg = f\\\"Input field {input_name} not found in target vertex {target_id}\\\"\\n                raise ValueError(msg) from e\\n            input_types = input_field.get(\\\"input_types\\\", [])\\n            input_field_type = input_field.get(\\\"type\\\", \\\"\\\")\\n\\n        edge_data: EdgeData = {\\n            \\\"source\\\": source_id,\\n            \\\"target\\\": target_id,\\n            \\\"data\\\": {\\n                \\\"sourceHandle\\\": {\\n                    \\\"dataType\\\": source_vertex.custom_component.name\\n                    or source_vertex.custom_component.__class__.__name__,\\n                    \\\"id\\\": source_vertex.id,\\n                    \\\"name\\\": output_name,\\n                    \\\"output_types\\\": source_vertex.get_output(output_name).types,\\n                },\\n                \\\"targetHandle\\\": {\\n                    \\\"fieldName\\\": input_name,\\n                    \\\"id\\\": target_vertex.id,\\n                    \\\"inputTypes\\\": input_types,\\n                    \\\"type\\\": input_field_type,\\n                },\\n            },\\n        }\\n        self._add_edge(edge_data)\\n\\n    @contextlib.contextmanager\\n    def _flow_span_scope(self, *, open_flow_span: bool):\\n        \\\"\\\"\\\"Open the flow span for a run, or defer to the caller that already opened one.\\n\\n        The guard is here because deferring and then not opening one is the failure this flag\\n        makes possible, and it is silent: the run simply produces no flow span. Warn rather than\\n        raise, because telemetry must never take a run down.\\n        \\\"\\\"\\\"\\n        if open_flow_span:\\n            with self.flow_execution_span(make_current=False):\\n                yield\\n            return\\n        if otel_trace is not None and not otel_trace.get_current_span().is_recording():\\n            logger.warning(\\n                \\\"async_start was told the caller owns the flow span, but no span is current, \\\"\\n                \\\"so this run will not be recorded. The caller should open \\\"\\n                \\\"graph.flow_execution_span() around its consumption of the stream.\\\"\\n            )\\n        yield\\n\\n    async def async_start(\\n        self,\\n        inputs: list[dict] | None = None,\\n        max_iterations: int | None = None,\\n        config: StartConfigDict | None = None,\\n        event_manager: EventManager | None = None,\\n        *,\\n        reset_output_values: bool = True,\\n        fallback_to_env_vars: bool = False,\\n        open_flow_span: bool = True,\\n    ):\\n        \\\"\\\"\\\"Run the graph, yielding each step.\\n\\n        open_flow_span=False says the caller already opened the flow span and this run belongs\\n        to it. Prefer that: a span opened here cannot be made current, because this is an async\\n        generator and the context token would be attached and detached across its suspension\\n        points, so nothing that runs inside the graph nests under the flow span. A caller that\\n        is a coroutine has no such problem, so the span it opens is a real parent.\\n\\n        Left defaulting to True so a caller that has not been converted still gets a span rather\\n        than silently none. Those runs keep the flat shape.\\n        \\\"\\\"\\\"\\n        with self._flow_span_scope(open_flow_span=open_flow_span):\\n            # Preserve start_component_id from constructor if available\\n            start_component_id = self._start.get_id() if self._start else None\\n            self.prepare(start_component_id=start_component_id)\\n            if reset_output_values:\\n                self._reset_all_output_values()\\n\\n            await self.initialize_run()\\n\\n            # The idea is for this to return a generator that yields the result of\\n            # each step call and raise StopIteration when the graph is done\\n            if config is not None:\\n                self.__apply_config(config)\\n            # I want to keep a counter of how many tyimes result.vertex.id\\n            # has been yielded\\n            yielded_counts: dict[str, int] = defaultdict(int)\\n\\n            while should_continue(yielded_counts, max_iterations):\\n                result = await self.astep(\\n                    event_manager=event_manager, inputs=inputs, fallback_to_env_vars=fallback_to_env_vars\\n                )\\n                yield result\\n                if isinstance(result, Finish):\\n                    return\\n                if hasattr(result, \\\"vertex\\\"):\\n                    yielded_counts[result.vertex.id] += 1\\n                    # Emit on_end_vertex event for each completed vertex\\n                    if event_manager is not None:\\n                        result_data_dict = None\\n                        if hasattr(result, \\\"result_dict\\\") and result.result_dict:\\n                            try:\\n                                result_data_dict = result.result_dict.model_dump()\\n                            except (AttributeError, TypeError):\\n                                result_data_dict = result.result_dict\\n                        build_data = {\\n                            \\\"id\\\": result.vertex.id,\\n                            \\\"valid\\\": result.valid if hasattr(result, \\\"valid\\\") else True,\\n                            \\\"data\\\": result_data_dict,\\n                        }\\n                        event_manager.on_end_vertex(data={\\\"build_data\\\": build_data})\\n\\n            msg = \\\"Max iterations reached\\\"\\n            raise ValueError(msg)\\n\\n    def _snapshot(self):\\n        return {\\n            \\\"_run_queue\\\": self._run_queue.copy(),\\n            \\\"_first_layer\\\": self._first_layer.copy(),\\n            \\\"vertices_layers\\\": copy.deepcopy(self.vertices_layers),\\n            \\\"vertices_to_run\\\": copy.deepcopy(self.vertices_to_run),\\n            \\\"run_manager\\\": copy.deepcopy(self.run_manager.to_dict()),\\n        }\\n\\n    def __apply_config(self, config: StartConfigDict) -> None:\\n        for vertex in self.vertices:\\n            if vertex.custom_component is None:\\n                continue\\n            for output in vertex.custom_component.get_outputs_map().values():\\n                for key, value in config[\\\"output\\\"].items():\\n                    setattr(output, key, value)\\n\\n    def _reset_all_output_values(self) -> None:\\n        for vertex in self.vertices:\\n            if vertex.custom_component is None:\\n                continue\\n            vertex.custom_component.reset_all_output_values()\\n\\n    def start(\\n        self,\\n        inputs: list[dict] | None = None,\\n        max_iterations: int | None = None,\\n        config: StartConfigDict | None = None,\\n        event_manager: EventManager | None = None,\\n    ) -> Generator:\\n        \\\"\\\"\\\"Starts the graph execution synchronously by creating a new event loop in a separate thread.\\n\\n        Args:\\n            inputs: Optional list of input dictionaries\\n            max_iterations: Optional maximum number of iterations\\n            config: Optional configuration dictionary\\n            event_manager: Optional event manager\\n\\n        Returns:\\n            Generator yielding results from graph execution\\n        \\\"\\\"\\\"\\n        if self.is_cyclic and max_iterations is None:\\n            msg = \\\"You must specify a max_iterations if the graph is cyclic\\\"\\n            raise ValueError(msg)\\n\\n        if config is not None:\\n            self.__apply_config(config)\\n\\n        # Create a queue for passing results and errors between threads\\n        result_queue: queue.Queue[VertexBuildResult | Exception | None] = queue.Queue()\\n\\n        # Function to run async code in separate thread\\n        def run_async_code():\\n            # Create new event loop for this thread\\n            loop = asyncio.new_event_loop()\\n            asyncio.set_event_loop(loop)\\n\\n            try:\\n                # Nothing is caught inside this block on purpose. A failure has to leave the\\n                # span scope for the span to see it: caught in here, the context manager exits\\n                # cleanly and a failed run is exported as status \\\"ok\\\", which is worse than no\\n                # telemetry because it looks like a healthy run.\\n                #\\n                # A thread entry point rather than a generator, so the span can be current for\\n                # every anext below. See async_start.\\n                try:\\n                    with self.flow_execution_span():\\n                        # By keyword: async_start takes (inputs, max_iterations, config,\\n                        # event_manager), so positionally the event manager lands in config and\\n                        # __apply_config subscripts it. config is already applied above, so it\\n                        # is deliberately not forwarded again.\\n                        async_gen = self.async_start(\\n                            inputs=inputs,\\n                            max_iterations=max_iterations,\\n                            event_manager=event_manager,\\n                            open_flow_span=False,\\n                        )\\n\\n                        while True:\\n                            try:\\n                                result = loop.run_until_complete(anext(async_gen))\\n                                result_queue.put(result)\\n\\n                                if isinstance(result, Finish):\\n                                    break\\n\\n                            except StopAsyncIteration:\\n                                break\\n                except Exception as exc:  # noqa: BLE001 - the worker boundary; see below\\n                    # Every Exception, not just ValueError. This runs on a thread, so anything\\n                    # not put on the queue dies with the thread while the caller reads the None\\n                    # below and sees a clean end of stream. The generator consumer re-raises\\n                    # whatever arrives here, so the caller gets the failure it would have got\\n                    # from a synchronous call.\\n                    result_queue.put(exc)\\n            finally:\\n                # Ensure all pending tasks are completed\\n                pending = asyncio.all_tasks(loop)\\n                if pending:\\n                    # Create a future to gather all pending tasks\\n                    cleanup_future = asyncio.gather(*pending, return_exceptions=True)\\n                    loop.run_until_complete(cleanup_future)\\n\\n                # Close the loop\\n                loop.close()\\n                # Signal completion, after any exception above so the caller reads that first.\\n                result_queue.put(None)\\n\\n        # Start thread for async execution, carrying the caller's context into it.\\n        #\\n        # A new thread starts with an empty context, so without this the flow span opened inside\\n        # run_async_code finds no current span and starts a brand-new trace: measured, the\\n        # caller's span and flow.execute came back with different trace ids and no parent or\\n        # link between them, which is exactly the correlation this PR exists to provide. The\\n        # same copy carries the protocol and client contextvars, which are set at the entry\\n        # point for the same reason.\\n        #\\n        # The caller's span is still recording while the generator below is consumed, so the\\n        # flow span parents to it normally. A caller that abandons the generator early leaves a\\n        # dead parent, which flow_execution_span already handles by linking instead.\\n        context = contextvars.copy_context()\\n        thread = threading.Thread(target=context.run, args=(run_async_code,))\\n        thread.start()\\n\\n        # Yield results from queue\\n        while True:\\n            result = result_queue.get()\\n            if result is None:\\n                break\\n            if isinstance(result, Exception):\\n                raise result\\n            yield result\\n\\n        # Wait for thread to complete\\n        thread.join()\\n\\n    def _add_edge(self, edge: EdgeData) -> None:\\n        self.add_edge(edge)\\n        source_id = edge[\\\"data\\\"][\\\"sourceHandle\\\"][\\\"id\\\"]\\n        target_id = edge[\\\"data\\\"][\\\"targetHandle\\\"][\\\"id\\\"]\\n        self.predecessor_map[target_id].append(source_id)\\n        self.successor_map[source_id].append(target_id)\\n        self.in_degree_map[target_id] += 1\\n        self.parent_child_map[source_id].append(target_id)\\n\\n    def add_node(self, node: NodeData) -> None:\\n        self._vertices.append(node)\\n\\n    def add_edge(self, edge: EdgeData) -> None:\\n        # Check if the edge already exists\\n        if edge in self._edges:\\n            return\\n        self._edges.append(edge)\\n\\n    def initialize(self) -> None:\\n        self._build_graph()\\n        self.build_graph_maps(self.edges)\\n        self.define_vertices_lists()\\n\\n    @property\\n    def is_state_vertices(self) -> list[str]:\\n        \\\"\\\"\\\"Returns a cached list of vertex IDs for vertices marked as state vertices.\\n\\n        The list is computed on first access by filtering vertices with `is_state` set to True and is\\n        cached for future calls.\\n        \\\"\\\"\\\"\\n        if self._is_state_vertices is None:\\n            self._is_state_vertices = [vertex.id for vertex in self.vertices if vertex.is_state]\\n        return self._is_state_vertices\\n\\n    def activate_state_vertices(self, name: str, caller: str) -> None:\\n        \\\"\\\"\\\"Activates vertices associated with a given state name.\\n\\n        Marks vertices with the specified state name, as well as their successors and related\\n        predecessors. The state manager is then updated with the new state record.\\n        \\\"\\\"\\\"\\n        vertices_ids = set()\\n        new_predecessor_map = {}\\n        activated_vertices = []\\n        for vertex_id in self.is_state_vertices:\\n            caller_vertex = self.get_vertex(caller)\\n            vertex = self.get_vertex(vertex_id)\\n            if vertex_id == caller or vertex.display_name == caller_vertex.display_name:\\n                continue\\n            ctx_key = vertex.raw_params.get(\\\"context_key\\\")\\n            if isinstance(ctx_key, str) and name in ctx_key and vertex_id != caller and isinstance(vertex, StateVertex):\\n                activated_vertices.append(vertex_id)\\n                vertices_ids.add(vertex_id)\\n                successors = self.get_all_successors(vertex, flat=True)\\n                # Update run_manager.run_predecessors because we are activating vertices\\n                # The run_prdecessors is the predecessor map of the vertices\\n                # we remove the vertex_id from the predecessor map whenever we run a vertex\\n                # So we need to get all edges of the vertex and successors\\n                # and run self.build_adjacency_maps(edges) to get the new predecessor map\\n                # that is not complete but we can use to update the run_predecessors\\n                successors_predecessors = set()\\n                for sucessor in successors:\\n                    successors_predecessors.update(self.get_all_predecessors(sucessor))\\n\\n                edges_set = set()\\n                for _vertex in [vertex, *successors, *successors_predecessors]:\\n                    edges_set.update(_vertex.edges)\\n                    if _vertex.state == VertexStates.INACTIVE:\\n                        _vertex.set_state(\\\"ACTIVE\\\")\\n\\n                    vertices_ids.add(_vertex.id)\\n                edges = list(edges_set)\\n                predecessor_map, _ = self.build_adjacency_maps(edges)\\n                new_predecessor_map.update(predecessor_map)\\n\\n        vertices_ids.update(new_predecessor_map.keys())\\n        vertices_ids.update(v_id for value_list in new_predecessor_map.values() for v_id in value_list)\\n\\n        self.activated_vertices = activated_vertices\\n        self.vertices_to_run.update(vertices_ids)\\n        self.run_manager.update_run_state(\\n            run_predecessors=new_predecessor_map,\\n            vertices_to_run=self.vertices_to_run,\\n        )\\n\\n    def reset_activated_vertices(self) -> None:\\n        \\\"\\\"\\\"Resets the activated vertices in the graph.\\\"\\\"\\\"\\n        self.activated_vertices = []\\n\\n    def validate_stream(self) -> None:\\n        \\\"\\\"\\\"Validates the stream configuration of the graph.\\n\\n        If there are two vertices in the same graph (connected by edges)\\n        that have `stream=True` or `streaming=True`, raises a `ValueError`.\\n\\n        Raises:\\n            ValueError: If two connected vertices have `stream=True` or `streaming=True`.\\n        \\\"\\\"\\\"\\n        for vertex in self.vertices:\\n            if vertex.params.get(\\\"stream\\\") or vertex.params.get(\\\"streaming\\\"):\\n                successors = self.get_all_successors(vertex)\\n                for successor in successors:\\n                    if successor.params.get(\\\"stream\\\") or successor.params.get(\\\"streaming\\\"):\\n                        msg = (\\n                            f\\\"Components {vertex.display_name} and {successor.display_name} \\\"\\n                            \\\"are connected and both have stream or streaming set to True\\\"\\n                        )\\n                        raise ValueError(msg)\\n\\n    @property\\n    def first_layer(self):\\n        if self._first_layer is None:\\n            msg = \\\"Graph not prepared. Call prepare() first.\\\"\\n            raise ValueError(msg)\\n        return self._first_layer\\n\\n    @property\\n    def is_cyclic(self):\\n        \\\"\\\"\\\"Check if the graph has any cycles.\\n\\n        Returns:\\n            bool: True if the graph has any cycles, False otherwise.\\n        \\\"\\\"\\\"\\n        if self._is_cyclic is None:\\n            self._is_cyclic = bool(self.cycle_vertices)\\n        return self._is_cyclic\\n\\n    @property\\n    def run_id(self):\\n        \\\"\\\"\\\"The ID of the current run.\\n\\n        Returns:\\n            str: The run ID.\\n\\n        Raises:\\n            ValueError: If the run ID is not set.\\n        \\\"\\\"\\\"\\n        if not self._run_id:\\n            msg = \\\"Run ID not set\\\"\\n            raise ValueError(msg)\\n        return self._run_id\\n\\n    def set_run_id(self, run_id: uuid.UUID | str | None = None) -> None:\\n        \\\"\\\"\\\"Sets the ID of the current run.\\n\\n        Args:\\n            run_id (str): The run ID.\\n        \\\"\\\"\\\"\\n        if run_id is None:\\n            run_id = uuid.uuid4()\\n\\n        self._run_id = str(run_id)\\n\\n    def request_pause(self, reason: str = \\\"pause_requested\\\", data: dict[str, Any] | None = None) -> None:\\n        self.pause_requested = True\\n        self.pause_info = {\\\"reason\\\": reason, \\\"data\\\": data or {}}\\n\\n    @classmethod\\n    def resume_from_checkpoint(cls, checkpoint: GraphCheckpoint, *, checkpoint_store: CheckpointStore | None = None):\\n        from lfx.graph.checkpoint.resume import restore_graph_from_checkpoint\\n\\n        return restore_graph_from_checkpoint(checkpoint, store=checkpoint_store)\\n\\n    def resume_first_layer(self) -> list[str]:\\n        from lfx.graph.checkpoint.resume import compute_resume_layer\\n\\n        return compute_resume_layer(self)\\n\\n    def build_checkpoint(self) -> GraphCheckpoint:\\n        from lfx.graph.checkpoint.builder import build_checkpoint\\n\\n        return build_checkpoint(self)\\n\\n    def _persist_resolved_branch_exclusions(self) -> None:\\n        \\\"\\\"\\\"Promote already-answered HumanInput decisions into the persistent exclusion channel.\\n\\n        A HumanInput stops its non-chosen branches with ``self.stop()`` (transient INACTIVE: reset\\n        per build and never checkpointed). When a later HumanInput pauses, the earlier node's dead\\n        branches would revive on resume and run \u2014 surfacing extra outputs and a re-paused first node.\\n        Move each resolved decision into ``conditionally_excluded_vertices`` (the same durable channel\\n        ConditionalRouter uses) so the dead branches stay dead across the resume. Derived from graph\\n        edges plus the recorded decision, so it also covers saved flows whose frozen component code\\n        predates any in-component exclusion call.\\n        \\\"\\\"\\\"\\n        decisions = getattr(self, \\\"human_input_decisions\\\", {}) or {}\\n        if not decisions:\\n            return\\n        for vertex in self.vertices:\\n            if (getattr(vertex, \\\"data\\\", None) or {}).get(\\\"type\\\") != \\\"HumanInput\\\":\\n                continue\\n            decision = decisions.get(f\\\"{vertex.id}:{self.run_id}\\\")\\n            if not decision:\\n                continue\\n            chosen = decision.get(\\\"action_id\\\")\\n            branch_outputs = {\\n                edge.source_handle.name\\n                for edge in self.edges\\n                if edge.source_id == vertex.id and edge.source_handle.name.startswith(\\\"branch_\\\")\\n            }\\n            non_chosen = sorted(branch_outputs - {f\\\"branch_{chosen}\\\"})\\n            if non_chosen:\\n                self.exclude_branches_conditionally(vertex.id, non_chosen)\\n\\n    async def _check_for_pause_signal(self) -> None:\\n        if self.pause_probe is None or self.job_id is None:\\n            return\\n        decision = await self.pause_probe(self.job_id)\\n        if decision == \\\"pause\\\":\\n            self.request_pause()\\n        elif decision == \\\"cancel\\\":\\n            raise asyncio.CancelledError\\n\\n    async def check_and_handle_pause(self) -> None:\\n        \\\"\\\"\\\"Boundary hook: consult the probe and suspend if a pause is pending.\\n\\n        Raises GraphPausedException after persisting the checkpoint. Default-off:\\n        with no probe, no pause request, or checkpointing disabled this is a no-op,\\n        so existing flows are unchanged.\\n        \\\"\\\"\\\"\\n        await self._check_for_pause_signal()\\n        if not (self.checkpointing_enabled and self.pause_requested):\\n            return\\n        self._persist_resolved_branch_exclusions()\\n        checkpoint = self.build_checkpoint()\\n        store = self.checkpoint_store\\n        if store is None:\\n            from lfx.services.deps import get_checkpoint_service\\n\\n            store = get_checkpoint_service()\\n        await store.save(checkpoint)\\n        info = self.pause_info or {}\\n        raise GraphPausedException(\\n            checkpoint_id=checkpoint.checkpoint_id,\\n            reason=info.get(\\\"reason\\\", \\\"pause_requested\\\"),\\n            data=info.get(\\\"data\\\"),\\n        )\\n\\n    async def initialize_run(self) -> None:\\n        if not self._run_id:\\n            self.set_run_id()\\n        if self.tracing_service:\\n            # Serving-plane telemetry attribution: surface the end user as the SEPARATE tracing label\\n            # (never the primary trace user_id, which stays the SID). Gated OFF by default: the\\n            # end-user id is PII and tracing providers are third-party SaaS, so it is forwarded only\\n            # when the operator opts in via ``serving_trace_end_user``, matching the fail-closed\\n            # posture of outbound MCP forwarding. Only fills when an identified serving run set\\n            # end_user_id and no explicit caller label was already provided.\\n            if self.end_user_id and not self.tracing_user_id and _serving_trace_end_user_enabled():\\n                self.tracing_user_id = self.end_user_id\\n            run_name = f\\\"{self.flow_name} - {self.flow_id}\\\"\\n            await self.tracing_service.start_tracers(\\n                run_id=uuid.UUID(self._run_id),\\n                run_name=run_name,\\n                user_id=self.user_id,\\n                session_id=self.session_id,\\n                flow_id=self.flow_id,\\n                tracing_user_id=self.tracing_user_id,\\n            )\\n\\n    @contextlib.contextmanager\\n    def flow_execution_span(self, *, make_current: bool = True):\\n        \\\"\\\"\\\"One application span per flow execution, for the operator's APM.\\n\\n        Attributes are set on exit because run_id is assigned by initialize_run, inside this scope.\\n        The span carries identifiers only: prompts, completions and component payloads belong to the\\n        LLM tracer integrations and must never reach the operator's APM, which is also why the error\\n        attribute is the exception type and not its message. Subgraphs (Loop iterations) are skipped\\n        so a loop over N items stays one span instead of N.\\n\\n        That rule is enforced per signal, and this is only the span half: the export filter lives in\\n        ``ApplicationOnlySpanProcessor``, and the same content is kept off the logs signal by the\\n        body policy in ``lfx.log.logger``. Neither covers container stdout or the local log file,\\n        which still carry full messages by design.\\n\\n        make_current attaches the span to the OTel context so a flow run from inside another flow\\n        (flow-as-tool, sub-flow components) nests under its caller instead of appearing as a sibling\\n        of it. It must stay False when the scope wraps an async generator: the context token would be\\n        attached and detached across the generator's suspension points, which leaks it into whatever\\n        task resumes the generator.\\n\\n        The status attribute exists because OTel's StatusCode has three values and a paused run is\\n        none of them: it did not fail, and calling it OK would tell an operator the work finished\\n        when a human is still holding it. Span status stays UNSET for a pause so alerting on the\\n        error rate does not fire, and the attribute carries the distinction.\\n\\n        A parent that has already ended is turned into a link instead. Several drivers outlive the\\n        request that started them: the v1 build route hands the work to a task and returns the\\n        job_id, so the server span is closed before the flow runs, and ``create_task`` copies the\\n        context regardless. Parenting to it yields a child that starts after its parent finished,\\n        which renders as a broken trace. Detecting it here rather than asking callers to declare it\\n        keeps the v2 stream correct for free: its server span stays open for the whole response, so\\n        it is still a real parent and is left as one.\\n\\n        Yields a :class:`FlowSpanScope`. Callers that let exceptions propagate can ignore it; a\\n        driver that catches component failures itself must call ``record_error`` or its run is\\n        exported as a success.\\n        \\\"\\\"\\\"\\n        scope = FlowSpanScope()\\n        if otel_trace is None or self._is_subgraph:\\n            yield scope\\n            return\\n        tracer = otel_trace.get_tracer(APPLICATION_TRACER_NAME)\\n        # is_recording() goes False once a span has ended, which is the signal that this run\\n        # outlived its request. An empty Context is what makes the replacement a root; without it\\n        # start_span would pick the dead span up as parent anyway.\\n        parent = otel_trace.get_current_span()\\n        parent_context = parent.get_span_context()\\n        queued_link = get_queued_trace_link()\\n        if queued_link is not None and not parent.is_recording():\\n            # A run picked off a queue, carrying the context of the request that queued it on\\n            # the job row.\\n            #\\n            # Checked before the ended-parent branch, and gated on the parent not recording\\n            # rather than on no span being current. Whatever ended span the worker happens to\\n            # be holding is not necessarily this run's originator: a worker task started from\\n            # a request inherits that request's context permanently, so every later run it\\n            # serves would link back to that first request. The carrier was written for this\\n            # specific job and is the authoritative answer; an ambient ended span is only a\\n            # good guess. A live parent still wins over both, below.\\n            span = tracer.start_span(\\n                FLOW_EXECUTION_SPAN_NAME,\\n                context=OtelContext(),\\n                links=[queued_link],\\n            )\\n        elif parent_context.is_valid and not parent.is_recording():\\n            span = tracer.start_span(\\n                FLOW_EXECUTION_SPAN_NAME,\\n                context=OtelContext(),\\n                links=[otel_trace.Link(parent_context)],\\n            )\\n        else:\\n            span = tracer.start_span(FLOW_EXECUTION_SPAN_NAME)\\n        status = \\\"ok\\\"\\n        try:\\n            with contextlib.ExitStack() as stack:\\n                if make_current:\\n                    # Not end_on_exit: the finally below ends it after the attributes are set.\\n                    # Neither recording nor status-setting is delegated, because the SDK's version\\n                    # of both writes the exception message onto the span and that can carry flow data.\\n                    stack.enter_context(\\n                        otel_trace.use_span(\\n                            span, end_on_exit=False, record_exception=False, set_status_on_exception=False\\n                        )\\n                    )\\n                yield scope\\n        except GraphPausedException:\\n            # A HITL pause suspends the unit of work; it is not a failed request. The resume is\\n            # driven through Graph.process by the durable runner, which opens its own span.\\n            status = \\\"paused\\\"\\n            raise\\n        except asyncio.CancelledError:\\n            # CancelledError is a BaseException, so the handler below does not see it and the\\n            # span would otherwise report the run as \\\"ok\\\". Reached by a user pressing stop (the\\n            # job service marks the job CANCELLED and re-raises) and by any asyncio.wait_for\\n            # ceiling wrapped around a span-carrying run: the v2 build driver, a2a, and the\\n            # agentic assistant all have one. The run did not finish, so it gets its own value.\\n            #\\n            # Span status stays UNSET, which is right for a stop button and arguable for a\\n            # timeout: a server-imposed ceiling is closer to a fault, and an operator alerting\\n            # on span error rate will not see it. Left as one value for now because the two are\\n            # indistinguishable here; the job row (CANCELLED vs FAILED) still tells them apart.\\n            status = \\\"cancelled\\\"\\n            raise\\n        except Exception as exc:\\n            status = \\\"error\\\"\\n            error_type = _root_error_type(exc)\\n            span.set_status(otel_trace.Status(otel_trace.StatusCode.ERROR, error_type))\\n            span.set_attribute(\\\"error.type\\\", error_type)\\n            raise\\n        finally:\\n            if self.flow_id:\\n                span.set_attribute(\\\"flow_id\\\", str(self.flow_id))\\n            if self._run_id:\\n                span.set_attribute(\\\"run_id\\\", self._run_id)\\n            if self.session_id:\\n                span.set_attribute(\\\"session_id\\\", str(self.session_id))\\n            # Absent rather than \\\"unknown\\\" when nothing set it: a missing attribute is a wiring\\n            # gap the operator can see, an \\\"unknown\\\" value looks like a protocol we support.\\n            if (protocol := get_execution_protocol()) is not None:\\n                span.set_attribute(\\\"protocol\\\", protocol)\\n            # Absent when the caller did not identify itself, same rule as protocol: a missing\\n            # attribute is \\\"nobody said\\\", which an operator can see and act on.\\n            if (client := get_execution_client()) is not None:\\n                span.set_attribute(\\\"client\\\", client)\\n            # A driver that swallowed its own component error exits this scope cleanly, so the\\n            # only signal is what it recorded on the way out.\\n            if status == \\\"ok\\\" and scope.error_type is not None:\\n                status = \\\"error\\\"\\n                span.set_status(otel_trace.Status(otel_trace.StatusCode.ERROR, scope.error_type))\\n                span.set_attribute(\\\"error.type\\\", scope.error_type)\\n            span.set_attribute(\\\"status\\\", status)\\n            span.end()\\n\\n    def _end_all_traces_async(self, outputs: dict[str, Any] | None = None, error: Exception | None = None) -> None:\\n        # Subgraphs don't end traces - the parent graph owns the trace lifecycle\\n        if self._is_subgraph:\\n            return\\n        task = asyncio.create_task(self.end_all_traces(outputs, error))\\n        self._end_trace_tasks.add(task)\\n        task.add_done_callback(self._end_trace_tasks.discard)\\n\\n    def end_all_traces_in_context(\\n        self,\\n        outputs: dict[str, Any] | None = None,\\n        error: Exception | None = None,\\n    ) -> Callable:\\n        # BackgroundTasks run in different context, so we need to copy the context\\n        context = contextvars.copy_context()\\n\\n        async def async_end_traces_func():\\n            coro = self.end_all_traces(outputs, error)\\n            if sys.version_info >= (3, 11):\\n                await asyncio.create_task(coro, context=context)\\n            else:\\n                # Python 3.10's asyncio.create_task does not accept context=.\\n                # Invoke create_task inside the captured context so the new\\n                # Task copies it as its current context.\\n                task = context.run(asyncio.create_task, coro)\\n                await task\\n\\n        return async_end_traces_func\\n\\n    async def end_all_traces(self, outputs: dict[str, Any] | None = None, error: Exception | None = None) -> None:\\n        if not self.tracing_service:\\n            return\\n        self._end_time = datetime.now(timezone.utc)\\n        if outputs is None:\\n            outputs = {}\\n        outputs |= self.metadata\\n        await self.tracing_service.end_tracers(outputs, error)\\n\\n    @property\\n    def sorted_vertices_layers(self) -> list[list[str]]:\\n        \\\"\\\"\\\"Returns the sorted layers of vertex IDs by type.\\n\\n        Each layer in the returned list contains vertex IDs grouped by their classification,\\n        such as input, output, session, or state vertices. Sorting is performed if not already done.\\n        \\\"\\\"\\\"\\n        if not self._sorted_vertices_layers:\\n            self.sort_vertices()\\n        return self._sorted_vertices_layers\\n\\n    def define_vertices_lists(self) -> None:\\n        \\\"\\\"\\\"Populates internal lists of input, output, session ID, and state vertex IDs.\\n\\n        Iterates over all vertices and appends their IDs to the corresponding internal lists\\n        based on their classification.\\n        \\\"\\\"\\\"\\n        for vertex in self.vertices:\\n            if vertex.is_input:\\n                self._is_input_vertices.append(vertex.id)\\n            if vertex.is_output:\\n                self._is_output_vertices.append(vertex.id)\\n            if vertex.has_session_id:\\n                self.has_session_id_vertices.append(vertex.id)\\n            if vertex.is_state:\\n                if self._is_state_vertices is None:\\n                    self._is_state_vertices = []\\n                self._is_state_vertices.append(vertex.id)\\n\\n    def _set_inputs(self, input_components: list[str], inputs: dict[str, str], input_type: InputType | None) -> None:\\n        \\\"\\\"\\\"Updates input vertices' parameters with the provided inputs, filtering by component list and input type.\\n\\n        Only vertices whose IDs or display names match the specified input components and whose component type matches\\n        the input type (unless input type is 'any' or None) are updated. Raises a ValueError if a specified\\n        vertex is not found.\\n        \\\"\\\"\\\"\\n        for vertex_id in self._is_input_vertices:\\n            vertex = self.get_vertex(vertex_id)\\n            if vertex is None:\\n                msg = f\\\"Vertex {vertex_id} not found\\\"\\n                raise ValueError(msg)\\n            # If the vertex is not in the input_components list\\n            if input_components and (vertex_id not in input_components and vertex.display_name not in input_components):\\n                continue\\n            if (\\n                input_type is not None\\n                and input_type != \\\"any\\\"\\n                and vertex.data.get(\\\"type\\\") not in INPUT_TYPE_COMPONENT_TYPES.get(input_type, set())\\n            ):\\n                continue\\n            vertex.update_raw_params(inputs, overwrite=True)\\n\\n    async def _run(\\n        self,\\n        *,\\n        inputs: dict[str, str],\\n        input_components: list[str],\\n        input_type: InputType | None,\\n        outputs: list[str],\\n        stream: bool,\\n        session_id: str,\\n        fallback_to_env_vars: bool,\\n        event_manager: EventManager | None = None,\\n    ) -> list[ResultData | None]:\\n        \\\"\\\"\\\"Runs the graph with the given inputs.\\n\\n        Args:\\n            inputs (Dict[str, str]): The input values for the graph.\\n            input_components (list[str]): The components to run for the inputs.\\n            input_type: (Optional[InputType]): The input type.\\n            outputs (list[str]): The outputs to retrieve from the graph.\\n            stream (bool): Whether to stream the results or not.\\n            session_id (str): The session ID for the graph.\\n            fallback_to_env_vars (bool): Whether to fallback to environment variables.\\n            event_manager (EventManager | None): The event manager for the graph.\\n\\n        Returns:\\n            List[Optional[\\\"ResultData\\\"]]: The outputs of the graph.\\n        \\\"\\\"\\\"\\n        if input_components and not isinstance(input_components, list):\\n            msg = f\\\"Invalid components value: {input_components}. Expected list\\\"\\n            raise ValueError(msg)\\n        if input_components is None:\\n            input_components = []\\n\\n        if not isinstance(inputs.get(INPUT_FIELD_NAME, \\\"\\\"), str):\\n            msg = f\\\"Invalid input value: {inputs.get(INPUT_FIELD_NAME)}. Expected string\\\"\\n            raise TypeError(msg)\\n        if inputs:\\n            self._set_inputs(input_components, inputs, input_type)\\n        # Update all the vertices with the session_id\\n        for vertex_id in self.has_session_id_vertices:\\n            vertex = self.get_vertex(vertex_id)\\n            if vertex is None:\\n                msg = f\\\"Vertex {vertex_id} not found\\\"\\n                raise ValueError(msg)\\n            vertex.update_raw_params({\\\"session_id\\\": session_id})\\n        # Process the graph\\n        try:\\n            cache_service = get_chat_service()\\n            if cache_service and self.flow_id:\\n                await cache_service.set_cache(self.flow_id, self)\\n        except Exception:  # noqa: BLE001\\n            logger.exception(\\\"Error setting cache\\\")\\n\\n        try:\\n            # Prioritize the webhook component if it exists\\n            start_component_id = find_start_component_id(self._is_input_vertices)\\n            await self.process(\\n                start_component_id=start_component_id,\\n                fallback_to_env_vars=fallback_to_env_vars,\\n                event_manager=event_manager,\\n            )\\n            self.increment_run_count()\\n        except (GraphPausedException, asyncio.CancelledError):\\n            # Why: a HITL pause/cancel must propagate UNWRAPPED so the job/runner layer suspends the\\n            # run instead of finalizing it; wrapping it as ValueError terminalizes the job (LE-1440).\\n            raise\\n        except Exception as exc:\\n            self._end_all_traces_async(error=exc)\\n            msg = f\\\"Error running graph: {exc}\\\"\\n            raise ValueError(msg) from exc\\n\\n        self._end_all_traces_async()\\n        # Get the outputs\\n        vertex_outputs = []\\n        for vertex in self.vertices:\\n            if not vertex.built:\\n                continue\\n            if vertex is None:\\n                msg = f\\\"Vertex {vertex_id} not found\\\"\\n                raise ValueError(msg)\\n\\n            if (\\n                not vertex.result\\n                and not stream\\n                and vertex.id not in self.checkpoint_restored_built_ids\\n                and hasattr(vertex, \\\"consume_async_generator\\\")\\n            ):\\n                # A vertex restored from a checkpoint already consumed its generator in the original\\n                # run; re-consuming here would re-iterate an exhausted/absent iterator and raise.\\n                await vertex.consume_async_generator()\\n            if (not outputs and vertex.is_output) or (vertex.display_name in outputs or vertex.id in outputs):\\n                vertex_outputs.append(vertex.result)\\n\\n        return vertex_outputs\\n\\n    async def arun(\\n        self,\\n        inputs: list[dict[str, str]],\\n        *,\\n        inputs_components: list[list[str]] | None = None,\\n        types: list[InputType | None] | None = None,\\n        outputs: list[str] | None = None,\\n        session_id: str | None = None,\\n        stream: bool = False,\\n        fallback_to_env_vars: bool = False,\\n        event_manager: EventManager | None = None,\\n    ) -> list[RunOutputs]:\\n        \\\"\\\"\\\"Runs the graph with the given inputs via the configured executor.\\\"\\\"\\\"\\n        from lfx.execution import aget_default_coordinator\\n\\n        coordinator = await aget_default_coordinator()\\n        return await coordinator.run_to_completion(\\n            self,\\n            inputs=inputs,\\n            inputs_components=inputs_components,\\n            types=types,\\n            outputs=outputs,\\n            session_id=session_id,\\n            stream=stream,\\n            fallback_to_env_vars=fallback_to_env_vars,\\n            event_manager=event_manager,\\n            _use_arun_legacy=True,\\n        )\\n\\n    async def _arun_legacy(\\n        self,\\n        inputs: list[dict[str, str]],\\n        *,\\n        inputs_components: list[list[str]] | None = None,\\n        types: list[InputType | None] | None = None,\\n        outputs: list[str] | None = None,\\n        session_id: str | None = None,\\n        stream: bool = False,\\n        fallback_to_env_vars: bool = False,\\n        event_manager: EventManager | None = None,\\n    ) -> list[RunOutputs]:\\n        vertex_outputs = []\\n        if not isinstance(inputs, list):\\n            inputs = [inputs]\\n        elif not inputs:\\n            inputs = [{}]\\n        # Length of all should be the as inputs length\\n        # just add empty lists to complete the length\\n        if inputs_components is None:\\n            inputs_components = []\\n        for _ in range(len(inputs) - len(inputs_components)):\\n            inputs_components.append([])\\n        if types is None:\\n            types = []\\n        if session_id:\\n            self.session_id = session_id\\n        for _ in range(len(inputs) - len(types)):\\n            types.append(\\\"chat\\\")  # default to chat\\n        with self.flow_execution_span():\\n            for run_inputs, components, input_type in zip(inputs, inputs_components, types, strict=True):\\n                run_outputs = await self._run(\\n                    inputs=run_inputs,\\n                    input_components=components,\\n                    input_type=input_type,\\n                    outputs=outputs or [],\\n                    stream=stream,\\n                    session_id=session_id or \\\"\\\",\\n                    fallback_to_env_vars=fallback_to_env_vars,\\n                    event_manager=event_manager,\\n                )\\n                run_output_object = RunOutputs(inputs=run_inputs, outputs=run_outputs)\\n                await logger.adebug(f\\\"Run outputs: {run_output_object}\\\")\\n                vertex_outputs.append(run_output_object)\\n        return vertex_outputs\\n\\n    def next_vertex_to_build(self):\\n        \\\"\\\"\\\"Returns the next vertex to be built.\\n\\n        Yields:\\n            str: The ID of the next vertex to be built.\\n        \\\"\\\"\\\"\\n        yield from chain.from_iterable(self.vertices_layers)\\n\\n    @property\\n    def metadata(self):\\n        \\\"\\\"\\\"The metadata of the graph.\\n\\n        Returns:\\n            dict: The metadata of the graph.\\n        \\\"\\\"\\\"\\n        time_format = \\\"%Y-%m-%d %H:%M:%S %Z\\\"\\n        return {\\n            \\\"start_time\\\": self._start_time.strftime(time_format),\\n            \\\"end_time\\\": self._end_time.strftime(time_format),\\n            \\\"time_elapsed\\\": f\\\"{(self._end_time - self._start_time).total_seconds()} seconds\\\",\\n            \\\"flow_id\\\": self.flow_id,\\n            \\\"flow_name\\\": self.flow_name,\\n        }\\n\\n    def build_graph_maps(self, edges: list[CycleEdge] | None = None, vertices: list[Vertex] | None = None) -> None:\\n        \\\"\\\"\\\"Builds the adjacency maps for the graph.\\\"\\\"\\\"\\n        if edges is None:\\n            edges = self.edges\\n\\n        if vertices is None:\\n            vertices = self.vertices\\n\\n        self.predecessor_map, self.successor_map = self.build_adjacency_maps(edges)\\n\\n        self.in_degree_map = self.build_in_degree(edges)\\n        self.parent_child_map = self.build_parent_child_map(vertices)\\n\\n    def _held_branch_inactivations(self) -> set[str]:\\n        \\\"\\\"\\\"Vertices a source vertex stopped and has not released yet.\\\"\\\"\\\"\\n        return set().union(*self.branch_inactivation_sources.values())\\n\\n    def reset_inactivated_vertices(self, source_vertex_id: str | None = None) -> None:\\n        \\\"\\\"\\\"Reactivate inactivated vertices.\\n\\n        With ``source_vertex_id``, release only the branch stops that completed\\n        vertex made; a vertex another source still holds stays inactive.\\n        Inactivations with no recorded source (graphs cached or checkpointed\\n        before ownership was tracked) keep the legacy behavior and are released\\n        by any completion. Without a source, every inactivation is reset.\\n        \\\"\\\"\\\"\\n        if source_vertex_id is None:\\n            self.branch_inactivation_sources.clear()\\n        else:\\n            self.branch_inactivation_sources.pop(source_vertex_id, None)\\n        for vertex_id in self.inactivated_vertices - self._held_branch_inactivations():\\n            self.mark_vertex(vertex_id, \\\"ACTIVE\\\")\\n\\n    def mark_all_vertices(self, state: str) -> None:\\n        \\\"\\\"\\\"Marks all vertices in the graph.\\\"\\\"\\\"\\n        # Every vertex now shares one state, so no earlier branch stop is held.\\n        self.branch_inactivation_sources.clear()\\n        for vertex in self.vertices:\\n            vertex.set_state(state)\\n\\n    def mark_vertex(self, vertex_id: str, state: str) -> None:\\n        \\\"\\\"\\\"Marks a vertex in the graph.\\\"\\\"\\\"\\n        vertex = self.get_vertex(vertex_id)\\n        vertex.set_state(state)\\n        if state == VertexStates.INACTIVE:\\n            self.run_manager.remove_from_predecessors(vertex_id)\\n\\n    def _get_output_names(self, vertex_id: str) -> set[str]:\\n        return {\\n            edge.source_handle.name\\n            for edge in self.edges\\n            if edge.source_id == vertex_id and getattr(edge.source_handle, \\\"name\\\", None)\\n        }\\n\\n    def _collect_branch_vertices(self, vertex_id: str, output_names: set[str] | None = None) -> set[str]:\\n        visited: set[str] = {vertex_id}\\n\\n        def walk(current_id: str, *, is_source: bool = False) -> None:\\n            for edge in self.edges:\\n                if edge.source_id != current_id:\\n                    continue\\n                if is_source and output_names is not None and edge.source_handle.name not in output_names:\\n                    continue\\n                child_id = edge.target_id\\n                if child_id in visited:\\n                    continue\\n                visited.add(child_id)\\n                walk(child_id)\\n\\n        walk(vertex_id, is_source=True)\\n        visited.discard(vertex_id)\\n        return visited\\n\\n    def _get_vertices_reachable_from_other_outputs(self, vertex_id: str, output_names: set[str]) -> set[str]:\\n        other_output_names = self._get_output_names(vertex_id) - output_names\\n        if not other_output_names:\\n            return set()\\n        return self._collect_branch_vertices(vertex_id, other_output_names)\\n\\n    def _mark_branch(\\n        self,\\n        vertex_id: str,\\n        state: str,\\n        visited: set | None = None,\\n        output_name: str | None = None,\\n        protected_vertices: set[str] | None = None,\\n    ) -> set:\\n        \\\"\\\"\\\"Marks a branch of the graph.\\\"\\\"\\\"\\n        if visited is None:\\n            visited = set()\\n        else:\\n            if state == VertexStates.INACTIVE and vertex_id in (protected_vertices or set()):\\n                return visited\\n            self.mark_vertex(vertex_id, state)\\n        if vertex_id in visited:\\n            return visited\\n        visited.add(vertex_id)\\n\\n        for child_id in self.parent_child_map[vertex_id]:\\n            # Only child_id that have an edge with the vertex_id through the output_name\\n            # should be marked\\n            if output_name:\\n                edge = self.get_edge(vertex_id, child_id)\\n                if edge and edge.source_handle.name != output_name:\\n                    continue\\n            self._mark_branch(child_id, state, visited, protected_vertices=protected_vertices)\\n        return visited\\n\\n    def mark_branch(self, vertex_id: str, state: str, output_name: str | None = None) -> None:\\n        protected_vertices = (\\n            self._get_vertices_reachable_from_other_outputs(vertex_id, {output_name})\\n            if state == VertexStates.INACTIVE and output_name\\n            else None\\n        )\\n        visited = self._mark_branch(\\n            vertex_id=vertex_id,\\n            state=state,\\n            output_name=output_name,\\n            protected_vertices=protected_vertices,\\n        )\\n        self._track_branch_inactivation(vertex_id, state, visited - {vertex_id})\\n        new_predecessor_map, _ = self.build_adjacency_maps(self.edges)\\n        new_predecessor_map = {k: v for k, v in new_predecessor_map.items() if k in visited}\\n        if vertex_id in self.cycle_vertices:\\n            # Remove dependencies that are not in the cycle and have run at least once\\n            new_predecessor_map = {\\n                k: [dep for dep in v if dep in self.cycle_vertices and dep in self.run_manager.ran_at_least_once]\\n                for k, v in new_predecessor_map.items()\\n            }\\n        self.run_manager.update_run_state(\\n            run_predecessors=new_predecessor_map,\\n            vertices_to_run=self.vertices_to_run,\\n        )\\n\\n    def _track_branch_inactivation(self, source_vertex_id: str, state: str, branch_vertices: set[str]) -> None:\\n        \\\"\\\"\\\"Record which source holds each stopped vertex so a completion releases only its own stops.\\\"\\\"\\\"\\n        if state == VertexStates.INACTIVE:\\n            stopped = branch_vertices & self.inactivated_vertices\\n            if stopped:\\n                held = self.branch_inactivation_sources.get(source_vertex_id, set())\\n                self.branch_inactivation_sources[source_vertex_id] = held | stopped\\n        elif state == VertexStates.ACTIVE:\\n            remaining = self.branch_inactivation_sources.pop(source_vertex_id, set()) - branch_vertices\\n            if remaining:\\n                self.branch_inactivation_sources[source_vertex_id] = remaining\\n            # start() releases only this source's stops; one another still-running\\n            # vertex holds on a shared descendant stays in effect.\\n            for held_vertex_id in branch_vertices & self._held_branch_inactivations():\\n                self.mark_vertex(held_vertex_id, VertexStates.INACTIVE)\\n\\n    def _replace_conditional_exclusions(self, vertex_id: str, excluded: set[str]) -> None:\\n        \\\"\\\"\\\"Replace ``vertex_id``'s conditional exclusions with ``excluded``.\\n\\n        Any vertices this source previously excluded are cleared first so the routing\\n        decision can be re-evaluated (e.g. on later cycle iterations where the condition\\n        may change) before the new set is applied and recorded against the source.\\n        \\\"\\\"\\\"\\n        if vertex_id in self.conditional_exclusion_sources:\\n            self.conditionally_excluded_vertices -= self.conditional_exclusion_sources.pop(vertex_id)\\n        self.conditionally_excluded_vertices.update(excluded)\\n        if excluded:\\n            self.conditional_exclusion_sources[vertex_id] = excluded\\n\\n    def exclude_branch_conditionally(self, vertex_id: str, output_name: str | None = None) -> None:\\n        \\\"\\\"\\\"Marks a branch as conditionally excluded (for conditional routing).\\n\\n        This system is separate from the ACTIVE/INACTIVE state used for cycle management:\\n        - ACTIVE/INACTIVE: Reset after each cycle iteration to allow cycles to continue\\n        - Conditional exclusion: Persists until explicitly cleared by the same source vertex\\n\\n        Used by ConditionalRouter to ensure only one branch executes per condition evaluation.\\n        If this vertex has previously excluded branches, they are cleared first to allow\\n        re-evaluation on subsequent iterations (e.g., in cycles where condition may change).\\n\\n        Args:\\n            vertex_id: The source vertex making the exclusion decision\\n            output_name: The output name to follow when excluding downstream vertices. A falsy\\n                value (``None`` or an empty string) excludes the entire downstream branch\\n                (every output), matching the historical behavior.\\n        \\\"\\\"\\\"\\n        if output_name:\\n            # A single named output is the multi-branch case with one branch; delegating\\n            # keeps the \\\"keep shared downstream nodes reachable from a sibling output\\\" logic\\n            # (e.g. a merge node fed by both branches of an If-Else) in one place.\\n            self.exclude_branches_conditionally(vertex_id, [output_name])\\n            return\\n\\n        # Whole-branch exclusion (no output filter): exclude every descendant.\\n        self._replace_conditional_exclusions(vertex_id, self._collect_branch_vertices(vertex_id))\\n\\n    def exclude_branches_conditionally(self, vertex_id: str, output_names: list[str]) -> None:\\n        \\\"\\\"\\\"Conditionally exclude several output branches of a single source vertex at once.\\n\\n        Behaves like :meth:`exclude_branch_conditionally` but accumulates the branches of\\n        every output in ``output_names`` under one source key, so excluding one branch does\\n        not clear its siblings. This is required by multi-way routers (e.g. Smart Router)\\n        that keep a single matched output and must persistently exclude all the others.\\n\\n        Like the single-branch variant, any previous exclusions from this source vertex are\\n        cleared first so the decision can be re-evaluated (e.g. on later cycle iterations).\\n\\n        Args:\\n            vertex_id: The source vertex making the exclusion decision.\\n            output_names: The output names whose downstream branches should be excluded.\\n        \\\"\\\"\\\"\\n        # Exclude each requested branch, then keep shared descendants that are still\\n        # reachable from a non-excluded output (for example, a merge node downstream\\n        # of both a selected and an unselected branch).\\n        output_names_set = set(output_names)\\n        excluded: set[str] = set()\\n        for output_name in output_names:\\n            excluded.update(self._collect_branch_vertices(vertex_id, {output_name}))\\n        excluded -= self._get_vertices_reachable_from_other_outputs(vertex_id, output_names_set)\\n        self._replace_conditional_exclusions(vertex_id, excluded)\\n\\n    def get_edge(self, source_id: str, target_id: str) -> CycleEdge | None:\\n        \\\"\\\"\\\"Returns the edge between two vertices.\\\"\\\"\\\"\\n        for edge in self.edges:\\n            if edge.source_id == source_id and edge.target_id == target_id:\\n                return edge\\n        return None\\n\\n    def build_parent_child_map(self, vertices: list[Vertex]):\\n        parent_child_map = defaultdict(list)\\n        for vertex in vertices:\\n            parent_child_map[vertex.id] = [child.id for child in self.get_successors(vertex)]\\n        return parent_child_map\\n\\n    def increment_run_count(self) -> None:\\n        self._runs += 1\\n\\n    def increment_update_count(self) -> None:\\n        self._updates += 1\\n\\n    def __getstate__(self):\\n        # Get all attributes that are useful in runs.\\n        # We don't need to save the state_manager because it is\\n        # a singleton and it is not necessary to save it\\n        return {\\n            \\\"vertices\\\": self.vertices,\\n            \\\"edges\\\": self.edges,\\n            \\\"flow_id\\\": self.flow_id,\\n            \\\"source_flow_id\\\": self.source_flow_id,\\n            \\\"flow_name\\\": self.flow_name,\\n            \\\"description\\\": self.description,\\n            \\\"user_id\\\": self.user_id,\\n            \\\"raw_graph_data\\\": self.raw_graph_data,\\n            \\\"top_level_vertices\\\": self.top_level_vertices,\\n            \\\"inactivated_vertices\\\": self.inactivated_vertices,\\n            \\\"branch_inactivation_sources\\\": self.branch_inactivation_sources,\\n            \\\"run_manager\\\": self.run_manager.to_dict(),\\n            \\\"_run_id\\\": self._run_id,\\n            \\\"in_degree_map\\\": self.in_degree_map,\\n            \\\"parent_child_map\\\": self.parent_child_map,\\n            \\\"predecessor_map\\\": self.predecessor_map,\\n            \\\"successor_map\\\": self.successor_map,\\n            \\\"activated_vertices\\\": self.activated_vertices,\\n            \\\"vertices_layers\\\": self.vertices_layers,\\n            \\\"vertices_to_run\\\": self.vertices_to_run,\\n            \\\"stop_vertex\\\": self.stop_vertex,\\n            \\\"_run_queue\\\": self._run_queue,\\n            \\\"_first_layer\\\": self._first_layer,\\n            \\\"_vertices\\\": self._vertices,\\n            \\\"_edges\\\": self._edges,\\n            \\\"_is_input_vertices\\\": self._is_input_vertices,\\n            \\\"_is_output_vertices\\\": self._is_output_vertices,\\n            \\\"has_session_id_vertices\\\": self.has_session_id_vertices,\\n            \\\"_sorted_vertices_layers\\\": self._sorted_vertices_layers,\\n            \\\"_instantiate_components_on_initialize\\\": self._instantiate_components_on_initialize,\\n        }\\n\\n    def _copy_graph(\\n        self,\\n        memo: dict,\\n        *,\\n        user_id: str | None,\\n        instantiate_components: bool,\\n        before_initialize: Callable[[Graph], None] | None = None,\\n    ) -> Graph:\\n        \\\"\\\"\\\"Copy this graph, optionally binding component construction to one user.\\n\\n        ``add_nodes_and_edges`` eagerly instantiates every component. Keeping the\\n        user override on graph construction (instead of stamping it afterward)\\n        preserves the cold-path constructor contract for components that inspect\\n        ``_user_id`` during ``__init__``.\\n        \\\"\\\"\\\"\\n        # Check if we've already copied this instance\\n        if id(self) in memo:\\n            return memo[id(self)]\\n\\n        if self._start is not None and self._end is not None:\\n            # Deep copy start and end components\\n            start_copy = copy.deepcopy(self._start, memo)\\n            end_copy = copy.deepcopy(self._end, memo)\\n            new_graph = type(self)(\\n                start=start_copy,\\n                end=end_copy,\\n                flow_id=copy.deepcopy(self.flow_id, memo),\\n                flow_name=copy.deepcopy(self.flow_name, memo),\\n                description=copy.deepcopy(self.description, memo),\\n                user_id=user_id,\\n                instantiate_components=instantiate_components,\\n            )\\n            if before_initialize is not None:\\n                before_initialize(new_graph)\\n            new_graph.source_flow_id = copy.deepcopy(self.source_flow_id, memo)\\n        else:\\n            # Create a new graph without start and end, binding the requested user\\n            # before add_nodes_and_edges instantiates request-local components.\\n            new_graph = type(self)(\\n                flow_id=copy.deepcopy(self.flow_id, memo),\\n                flow_name=copy.deepcopy(self.flow_name, memo),\\n                description=copy.deepcopy(self.description, memo),\\n                user_id=user_id,\\n                instantiate_components=instantiate_components,\\n            )\\n            # add_nodes_and_edges synchronously builds FileInput parameters, so\\n            # trusted public-flow provenance must exist before reconstruction.\\n            new_graph.source_flow_id = copy.deepcopy(self.source_flow_id, memo)\\n            # Rebuild parsed graphs from their original frontend shape. ``_vertices``\\n            # and ``_edges`` have already been flattened by ``process_flow``; using\\n            # them here would turn grouped children into top-level vertices and\\n            # change grouped execution/status semantics. Programmatic graphs do not\\n            # necessarily have raw frontend data, so retain the processed fallback.\\n            has_raw_graph_data = self.raw_graph_data != {\\\"nodes\\\": [], \\\"edges\\\": []} or not (\\n                self._vertices or self._edges\\n            )\\n            source_graph_data = (\\n                self.raw_graph_data\\n                if has_raw_graph_data\\n                else {\\n                    \\\"nodes\\\": self._vertices,\\n                    \\\"edges\\\": self._edges,\\n                }\\n            )\\n            source_graph_data = copy.deepcopy(source_graph_data, memo)\\n            if has_raw_graph_data:\\n                # Match cold-path ordering: request-local raw overrides run on\\n                # the original frontend shape before groups are flattened.\\n                new_graph.raw_graph_data = source_graph_data\\n                if before_initialize is not None:\\n                    before_initialize(new_graph)\\n                source_graph_data = new_graph.raw_graph_data\\n            new_graph.add_nodes_and_edges(source_graph_data[\\\"nodes\\\"], source_graph_data[\\\"edges\\\"])\\n            if not has_raw_graph_data and before_initialize is not None:\\n                before_initialize(new_graph)\\n\\n        new_graph.requires_extension_event_replay = self.requires_extension_event_replay\\n\\n        # Store the newly created object in memo\\n        memo[id(self)] = new_graph\\n\\n        return new_graph\\n\\n    def __deepcopy__(self, memo):\\n        return self._copy_graph(\\n            memo,\\n            user_id=copy.deepcopy(self.user_id, memo),\\n            instantiate_components=self._instantiate_components_on_initialize,\\n            before_initialize=None,\\n        )\\n\\n    def copy_for_run(\\n        self,\\n        *,\\n        user_id: str | None,\\n        before_instantiate: Callable[[Graph], None] | None = None,\\n    ) -> Graph:\\n        \\\"\\\"\\\"Return an isolated executable graph whose constructors see run defaults.\\n\\n        ``before_instantiate`` can apply request-local raw-parameter overrides\\n        (for example the implicit streaming value) after frontend-data copying,\\n        before group flattening and component construction observe them.\\n        \\\"\\\"\\\"\\n        new_graph = self._copy_graph(\\n            {},\\n            user_id=user_id,\\n            instantiate_components=False,\\n            before_initialize=before_instantiate,\\n        )\\n        new_graph._instantiate_components_in_vertices()  # noqa: SLF001\\n        new_graph._instantiate_components_on_initialize = True  # noqa: SLF001\\n        return new_graph\\n\\n    def __setstate__(self, state):\\n        # Cache/checkpoint payloads written before lazy warm templates existed\\n        # must retain the historical eager-instantiation behavior.\\n        state.setdefault(\\\"_instantiate_components_on_initialize\\\", True)\\n        state.setdefault(\\\"requires_extension_event_replay\\\", False)\\n        # Graphs cached before source-flow provenance was introduced remain\\n        # loadable and simply have no additional trusted storage namespace.\\n        state.setdefault(\\\"source_flow_id\\\", None)\\n        state.setdefault(\\\"branch_inactivation_sources\\\", {})\\n        run_manager = state[\\\"run_manager\\\"]\\n        if isinstance(run_manager, RunnableVerticesManager):\\n            state[\\\"run_manager\\\"] = run_manager\\n        else:\\n            state[\\\"run_manager\\\"] = RunnableVerticesManager.from_dict(run_manager)\\n        self.__dict__.update(state)\\n        self.vertex_map = {vertex.id: vertex for vertex in self.vertices}\\n        # Tracing service will be lazily initialized via property when needed\\n        self.set_run_id(self._run_id)\\n\\n    @classmethod\\n    def from_payload(\\n        cls,\\n        payload: dict,\\n        flow_id: str | None = None,\\n        flow_name: str | None = None,\\n        user_id: str | None = None,\\n        context: dict | None = None,\\n        *,\\n        instantiate_components: bool = True,\\n        emit_extension_events: bool = True,\\n    ) -> Graph:\\n        \\\"\\\"\\\"Creates a graph from a payload.\\n\\n        Args:\\n            payload: The payload to create the graph from.\\n            flow_id: The ID of the flow.\\n            flow_name: The flow name.\\n            user_id: The user ID.\\n            context: Optional context dictionary for request-specific data.\\n            instantiate_components: Whether to run component constructors while\\n                parsing. Warm templates disable this and instantiate only on the\\n                request-local copy with the authenticated caller identity.\\n            emit_extension_events: Whether migration reports should be published\\n                to the extension event service. Background warm parsing disables\\n                this because it is not scoped to an active caller.\\n\\n        Returns:\\n            Graph: The created graph.\\n        \\\"\\\"\\\"\\n        from lfx.extension.migration import migrate_flow_payload\\n        from lfx.services.deps import get_catalog_policy_service\\n        from lfx.utils.flow_validation import (\\n            substitute_outdated_component_code_in_place,\\n            validate_catalog_policy_for_flow,\\n            validate_flow_for_current_settings,\\n        )\\n\\n        if \\\"data\\\" in payload:\\n            payload = payload[\\\"data\\\"]\\n        # Catalog identity is the exact, case-sensitive stored node.data.type.\\n        # Validate it before extension migration rewrites legacy identifiers.\\n        # Reuse this same immutable snapshot below so migrated executable types\\n        # are checked against the identical policy view without a TOCTOU gap.\\n        catalog_policy_snapshot = get_catalog_policy_service().snapshot\\n        validate_catalog_policy_for_flow(payload, snapshot=catalog_policy_snapshot)\\n        # Rewrite legacy component references in place against the append-only\\n        # extension migration table.  Best-effort: a corrupt table or unmapped\\n        # reference produces typed errors on the report but never raises, so\\n        # flow load remains as forgiving as it was pre-Phase-A.\\n        migration_report = migrate_flow_payload(payload)\\n        # Surface every typed error from the report through the standard\\n        # logger so unmapped or ambiguous component references are not\\n        # silently dropped.  We log rather than raise because the\\n        # rewriter is intentionally tolerant -- a partially-broken flow\\n        # still loads, and the frontend renders missing nodes as red\\n        # placeholders.  The structured ``code``/``hint`` come from\\n        # ``ExtensionError`` so log scrapers can parse the payload.\\n        for migration_error in migration_report.errors:\\n            # Use %s-style positional formatting consistent with the rest of\\n            # the extension subsystem so the rendered message is readable\\n            # without relying on structlog's keyword-binding behavior.\\n            logger.warning(\\n                \\\"extension migration: code=%s flow_id=%s location=%s hint=%s message=%s\\\",\\n                migration_error.code,\\n                flow_id,\\n                migration_error.location,\\n                migration_error.hint,\\n                migration_error.message,\\n            )\\n        # Emit extension events so the frontend can surface migration results.\\n        if emit_extension_events:\\n            try:\\n                from lfx.services.deps import get_extension_events_service\\n\\n                _svc = get_extension_events_service()\\n                if _svc is not None:\\n                    # Per-user keyspace so flow_id / migration error details only\\n                    # reach the user that loaded the flow; fall back to \\\"global\\\"\\n                    # for unauthenticated paths (CLI, tests, single-user dev).\\n                    _keyspace = f\\\"user:{user_id}\\\" if user_id else \\\"global\\\"\\n                    if migration_report.any_rewritten:\\n                        _svc.emit(\\n                            \\\"flow_migrated\\\",\\n                            {\\n                                \\\"flow_id\\\": str(flow_id) if flow_id else None,\\n                                \\\"rewritten_count\\\": migration_report.rewritten_count,\\n                            },\\n                            keyspace=_keyspace,\\n                        )\\n                    for migration_error in migration_report.errors:\\n                        _svc.emit(\\n                            \\\"extension_error\\\",\\n                            {\\n                                \\\"flow_id\\\": str(flow_id) if flow_id else None,\\n                                \\\"code\\\": migration_error.code,\\n                                \\\"message\\\": migration_error.message,\\n                                \\\"hint\\\": migration_error.hint,\\n                                \\\"location\\\": migration_error.location,\\n                            },\\n                            keyspace=_keyspace,\\n                        )\\n            except Exception:  # noqa: BLE001 -- best-effort emit; never break flow load on an event-bus failure\\n                logger.warning(\\n                    \\\"extension.event_emit_failed: failed to emit migration events in from_payload.\\\",\\n                    exc_info=True,\\n                )\\n        # Restricted deployments (allow_custom_components=False) never execute a node's stored\\n        # code \u2014 the build substitutes this server's copy keyed by code hash. Rewrite the code of\\n        # recognized built-ins whose stored copy has merely drifted across versions, so the\\n        # validation below passes on its own and the flow builds with this server's component\\n        # instead of being refused over code it was not going to run. No-op when custom\\n        # components are allowed or the operator turned the substitution off; a node whose type\\n        # is not a known server component is left untouched and still refused below.\\n        # Public routes sanitize before handing the payload to the executor, but a hot extension\\n        # reload can occur before graph construction. In restricted mode the substitution below\\n        # may therefore select a newer source generation than the route checked. Re-run the public\\n        # code-execution gate for the anonymous execution principal against the exact\\n        # post-substitution bytes and the same registry snapshot, before component instantiation.\\n        from lfx.services.authorization import PUBLIC_ANONYMOUS_ACTOR_ID\\n\\n        validate_public_execution = str(user_id) == str(PUBLIC_ANONYMOUS_ACTOR_ID)\\n        substitute_outdated_component_code_in_place(\\n            payload,\\n            validate_public_execution=validate_public_execution,\\n        )\\n        # Defense-in-depth: validate here so that no code path can construct\\n        # a graph with blocked/custom components, even if an API endpoint\\n        # forgets its own pre-check. Ideally this would live only at the API\\n        # boundary (middleware or endpoint dependency) so from_payload stays\\n        # pure deserialization, but a missed endpoint means arbitrary code\\n        # execution, so we keep this as a safety net.\\n        validate_flow_for_current_settings(payload, catalog_policy_snapshot=catalog_policy_snapshot)\\n        try:\\n            # The extension migrator intentionally rewrites only the nodes at\\n            # the payload level it receives, while process_flow later flattens\\n            # inlined nested flows for execution. Build that executable view\\n            # on a deep copy, migrate it, and enforce the same snapshot so a\\n            # nested legacy alias cannot bypass a block on its canonical key.\\n            # Migration errors on this policy-only copy remain best-effort and\\n            # are not exposed. Skip the work for the default allow-all policy.\\n            if catalog_policy_snapshot.blocked_component_keys:\\n                effective_catalog_payload = process_flow(payload)\\n                migrate_flow_payload(effective_catalog_payload)\\n                validate_catalog_policy_for_flow(effective_catalog_payload, snapshot=catalog_policy_snapshot)\\n            vertices = payload[\\\"nodes\\\"]\\n            edges = payload[\\\"edges\\\"]\\n            graph = cls(\\n                flow_id=flow_id,\\n                flow_name=flow_name,\\n                user_id=user_id,\\n                context=context,\\n                instantiate_components=instantiate_components,\\n            )\\n            graph.add_nodes_and_edges(vertices, edges)\\n            graph.requires_extension_event_replay = bool(migration_report.any_rewritten or migration_report.errors)\\n        except KeyError as exc:\\n            logger.exception(\\\"Extension migration replay failed while reading the payload\\\")\\n            if \\\"nodes\\\" not in payload and \\\"edges\\\" not in payload:\\n                msg = f\\\"Invalid payload. Expected keys 'nodes' and 'edges'. Found {list(payload.keys())}\\\"\\n                raise ValueError(msg) from exc\\n\\n            msg = f\\\"Error while creating graph from payload: {exc}\\\"\\n            raise ValueError(msg) from exc\\n        else:\\n            return graph\\n\\n    def __eq__(self, /, other: object) -> bool:\\n        if not isinstance(other, Graph):\\n            return False\\n        return self.__repr__() == other.__repr__()\\n\\n    # update this graph with another graph by comparing the __repr__ of each vertex\\n    # and if the __repr__ of a vertex is not the same as the other\\n    # then update the .data of the vertex to the self\\n    # both graphs have the same vertices and edges\\n    # but the data of the vertices might be different\\n\\n    def update_edges_from_vertex(self, other_vertex: Vertex) -> None:\\n        \\\"\\\"\\\"Updates the edges of a vertex in the Graph.\\\"\\\"\\\"\\n        new_edges = []\\n        for edge in self.edges:\\n            if other_vertex.id in {edge.source_id, edge.target_id}:\\n                continue\\n            new_edges.append(edge)\\n        new_edges += other_vertex.edges\\n        self.edges = new_edges\\n\\n    def vertex_data_is_identical(self, vertex: Vertex, other_vertex: Vertex) -> bool:\\n        data_is_equivalent = vertex == other_vertex\\n        if not data_is_equivalent:\\n            return False\\n        return self.vertex_edges_are_identical(vertex, other_vertex)\\n\\n    @staticmethod\\n    def vertex_edges_are_identical(vertex: Vertex, other_vertex: Vertex) -> bool:\\n        same_length = len(vertex.edges) == len(other_vertex.edges)\\n        if not same_length:\\n            return False\\n        return all(edge in other_vertex.edges for edge in vertex.edges)\\n\\n    def update(self, other: Graph) -> Graph:\\n        # Existing vertices in self graph\\n        existing_vertex_ids = {vertex.id for vertex in self.vertices}\\n        # Vertex IDs in the other graph\\n        other_vertex_ids = set(other.vertex_map.keys())\\n\\n        # Find vertices that are in other but not in self (new vertices)\\n        new_vertex_ids = other_vertex_ids - existing_vertex_ids\\n\\n        # Find vertices that are in self but not in other (removed vertices)\\n        removed_vertex_ids = existing_vertex_ids - other_vertex_ids\\n\\n        # Remove vertices that are not in the other graph\\n        for vertex_id in removed_vertex_ids:\\n            with contextlib.suppress(ValueError):\\n                self.remove_vertex(vertex_id)\\n\\n        # The order here matters because adding the vertex is required\\n        # if any of them have edges that point to any of the new vertices\\n        # By adding them first, them adding the edges we ensure that the\\n        # edges have valid vertices to point to\\n\\n        # Add new vertices\\n        for vertex_id in new_vertex_ids:\\n            new_vertex = other.get_vertex(vertex_id)\\n            self._add_vertex(new_vertex)\\n\\n        # Now update the edges\\n        for vertex_id in new_vertex_ids:\\n            new_vertex = other.get_vertex(vertex_id)\\n            self._update_edges(new_vertex)\\n            # Graph is set at the end because the edges come from the graph\\n            # and the other graph is where the new edges and vertices come from\\n            new_vertex.graph = self\\n\\n        # Update existing vertices that have changed\\n        for vertex_id in existing_vertex_ids.intersection(other_vertex_ids):\\n            self_vertex = self.get_vertex(vertex_id)\\n            other_vertex = other.get_vertex(vertex_id)\\n            # If the vertices are not identical, update the vertex\\n            if not self.vertex_data_is_identical(self_vertex, other_vertex):\\n                self.update_vertex_from_another(self_vertex, other_vertex)\\n\\n        self.build_graph_maps()\\n        self.define_vertices_lists()\\n        self.increment_update_count()\\n        return self\\n\\n    def update_vertex_from_another(self, vertex: Vertex, other_vertex: Vertex) -> None:\\n        \\\"\\\"\\\"Updates a vertex from another vertex.\\n\\n        Args:\\n            vertex (Vertex): The vertex to be updated.\\n            other_vertex (Vertex): The vertex to update from.\\n        \\\"\\\"\\\"\\n        vertex.full_data = other_vertex.full_data\\n        vertex.parse_data()\\n        # Now we update the edges of the vertex\\n        self.update_edges_from_vertex(other_vertex)\\n        vertex.params = {}\\n        vertex.build_params()\\n        vertex.graph = self\\n        # If the vertex is frozen, we don't want\\n        # to reset the results nor the built attribute\\n        if not vertex.frozen:\\n            vertex.built = False\\n            vertex.result = None\\n            vertex.artifacts = {}\\n            vertex.set_top_level(self.top_level_vertices)\\n        self.reset_all_edges_of_vertex(vertex)\\n\\n    def reset_all_edges_of_vertex(self, vertex: Vertex) -> None:\\n        \\\"\\\"\\\"Resets all the edges of a vertex.\\\"\\\"\\\"\\n        for edge in vertex.edges:\\n            for vid in [edge.source_id, edge.target_id]:\\n                if vid in self.vertex_map:\\n                    vertex_ = self.vertex_map[vid]\\n                    if not vertex_.frozen:\\n                        vertex_.build_params()\\n\\n    def _add_vertex(self, vertex: Vertex) -> None:\\n        \\\"\\\"\\\"Adds a vertex to the graph.\\\"\\\"\\\"\\n        self.vertices.append(vertex)\\n        self.vertex_map[vertex.id] = vertex\\n\\n    def add_vertex(self, vertex: Vertex) -> None:\\n        \\\"\\\"\\\"Adds a new vertex to the graph.\\\"\\\"\\\"\\n        self._add_vertex(vertex)\\n        self._update_edges(vertex)\\n\\n    def _update_edges(self, vertex: Vertex) -> None:\\n        \\\"\\\"\\\"Updates the edges of a vertex.\\\"\\\"\\\"\\n        # Vertex has edges, so we need to update the edges\\n        for edge in vertex.edges:\\n            if edge not in self.edges and edge.source_id in self.vertex_map and edge.target_id in self.vertex_map:\\n                self.edges.append(edge)\\n\\n    def _build_graph(self) -> None:\\n        \\\"\\\"\\\"Builds the graph from the vertices and edges.\\\"\\\"\\\"\\n        self.vertices = self._build_vertices()\\n        self.vertex_map = {vertex.id: vertex for vertex in self.vertices}\\n        self.edges = self._build_edges()\\n\\n        # This is a hack to make sure that the LLM vertex is sent to\\n        # the toolkit vertex\\n        self._build_vertex_params()\\n        if self._instantiate_components_on_initialize:\\n            self._instantiate_components_in_vertices()\\n        self._set_cache_to_vertices_in_cycle()\\n        self._set_cache_if_listen_notify_components()\\n        for vertex in self.vertices:\\n            if vertex.id in self.cycle_vertices:\\n                self.run_manager.add_to_cycle_vertices(vertex.id)\\n\\n    def _get_edges_as_list_of_tuples(self) -> list[tuple[str, str]]:\\n        \\\"\\\"\\\"Returns the edges of the graph as a list of tuples.\\n\\n        Each tuple contains the source and target handle IDs from the edge data.\\n\\n        Returns:\\n            list[tuple[str, str]]: List of (source_id, target_id) tuples representing graph edges.\\n        \\\"\\\"\\\"\\n        return [(e[\\\"data\\\"][\\\"sourceHandle\\\"][\\\"id\\\"], e[\\\"data\\\"][\\\"targetHandle\\\"][\\\"id\\\"]) for e in self._edges]\\n\\n    def _set_cache_if_listen_notify_components(self) -> None:\\n        \\\"\\\"\\\"Disables caching for all vertices if Listen/Notify components are present.\\n\\n        If the graph contains any Listen or Notify components, caching is disabled for all vertices\\n        by setting cache=False on their outputs. This ensures proper handling of real-time\\n        communication between components.\\n        \\\"\\\"\\\"\\n        has_listen_or_notify_component = any(\\n            vertex.id.split(\\\"-\\\")[0] in {\\\"Listen\\\", \\\"Notify\\\"} for vertex in self.vertices\\n        )\\n        if has_listen_or_notify_component:\\n            for vertex in self.vertices:\\n                vertex.apply_on_outputs(lambda output_object: setattr(output_object, \\\"cache\\\", False))\\n\\n    def _set_cache_to_vertices_in_cycle(self) -> None:\\n        \\\"\\\"\\\"Sets the cache to the vertices in cycle.\\\"\\\"\\\"\\n        edges = self._get_edges_as_list_of_tuples()\\n        cycle_vertices = set(find_cycle_vertices(edges))\\n        for vertex in self.vertices:\\n            if vertex.id in cycle_vertices:\\n                vertex.apply_on_outputs(lambda output_object: setattr(output_object, \\\"cache\\\", False))\\n\\n    def _instantiate_components_in_vertices(self) -> None:\\n        \\\"\\\"\\\"Instantiates the components in the vertices.\\\"\\\"\\\"\\n        for vertex in self.vertices:\\n            vertex.instantiate_component(self.user_id)\\n\\n    def remove_vertex(self, vertex_id: str) -> None:\\n        \\\"\\\"\\\"Removes a vertex from the graph.\\\"\\\"\\\"\\n        vertex = self.get_vertex(vertex_id)\\n        if vertex is None:\\n            return\\n        self.vertices.remove(vertex)\\n        self.vertex_map.pop(vertex_id)\\n        self.edges = [edge for edge in self.edges if vertex_id not in {edge.source_id, edge.target_id}]\\n\\n    def _build_vertex_params(self) -> None:\\n        \\\"\\\"\\\"Identifies and handles the LLM vertex within the graph.\\\"\\\"\\\"\\n        for vertex in self.vertices:\\n            vertex.build_params()\\n\\n    def _validate_vertex(self, vertex: Vertex) -> bool:\\n        \\\"\\\"\\\"Validates a vertex.\\\"\\\"\\\"\\n        # All vertices that do not have edges are invalid\\n        return len(self.get_vertex_edges(vertex.id)) > 0\\n\\n    def get_vertex(self, vertex_id: str) -> Vertex:\\n        \\\"\\\"\\\"Returns a vertex by id.\\\"\\\"\\\"\\n        try:\\n            return self.vertex_map[vertex_id]\\n        except KeyError as e:\\n            msg = f\\\"Vertex {vertex_id} not found\\\"\\n            raise ValueError(msg) from e\\n\\n    def get_root_of_group_node(self, vertex_id: str) -> Vertex:\\n        \\\"\\\"\\\"Returns the root of a group node.\\\"\\\"\\\"\\n        if vertex_id in self.top_level_vertices:\\n            # Get all vertices with vertex_id as .parent_node_id\\n            # then get the one at the top\\n            vertices = [vertex for vertex in self.vertices if vertex.parent_node_id == vertex_id]\\n            # Now go through successors of the vertices\\n            # and get the one that none of its successors is in vertices\\n            for vertex in vertices:\\n                successors = self.get_all_successors(vertex, recursive=False)\\n                if not any(successor in vertices for successor in successors):\\n                    return vertex\\n        msg = f\\\"Vertex {vertex_id} is not a top level vertex or no root vertex found\\\"\\n        raise ValueError(msg)\\n\\n    def get_next_in_queue(self):\\n        if not self._run_queue:\\n            return None\\n        return self._run_queue.popleft()\\n\\n    def extend_run_queue(self, vertices: list[str]) -> None:\\n        self._run_queue.extend(vertices)\\n\\n    async def astep(\\n        self,\\n        inputs: InputValueRequest | None = None,\\n        files: list[str] | None = None,\\n        user_id: str | None = None,\\n        event_manager: EventManager | None = None,\\n        *,\\n        fallback_to_env_vars: bool = False,\\n    ):\\n        if not self._prepared:\\n            msg = \\\"Graph not prepared. Call prepare() first.\\\"\\n            raise ValueError(msg)\\n        if not self._run_queue:\\n            self._end_all_traces_async()\\n            return Finish()\\n        vertex_id = self.get_next_in_queue()\\n        if not vertex_id:\\n            msg = \\\"No vertex to run\\\"\\n            raise ValueError(msg)\\n\\n        # Emit build_start event before building vertex\\n        if event_manager is not None:\\n            event_manager.on_build_start(data={\\\"id\\\": vertex_id})\\n\\n        chat_service = get_chat_service()\\n\\n        # Provide fallback cache functions if chat service is unavailable\\n        if chat_service is not None:\\n            get_cache_func = chat_service.get_cache\\n            set_cache_func = chat_service.set_cache\\n        else:\\n            # Fallback no-op cache functions for tests or when service unavailable\\n            async def get_cache_func(*args, **kwargs):  # noqa: ARG001\\n                return CacheMiss()\\n\\n            async def set_cache_func(*args, **kwargs) -> bool:  # noqa: ARG001\\n                return True\\n\\n        vertex_build_result = await self.build_vertex(\\n            vertex_id=vertex_id,\\n            user_id=user_id,\\n            inputs_dict=inputs.model_dump() if inputs and hasattr(inputs, \\\"model_dump\\\") else {},\\n            files=files,\\n            get_cache=get_cache_func,\\n            set_cache=set_cache_func,\\n            event_manager=event_manager,\\n            fallback_to_env_vars=fallback_to_env_vars,\\n        )\\n\\n        next_runnable_vertices = await self.get_next_runnable_vertices(\\n            self.lock, vertex=vertex_build_result.vertex, cache=False\\n        )\\n        if self.stop_vertex and self.stop_vertex in next_runnable_vertices:\\n            next_runnable_vertices = [self.stop_vertex]\\n        self.extend_run_queue(next_runnable_vertices)\\n        self.reset_inactivated_vertices(vertex_id)\\n        self.reset_activated_vertices()\\n\\n        if chat_service is not None:\\n            await chat_service.set_cache(str(self.flow_id or self._run_id), self)\\n        self._record_snapshot(vertex_id)\\n        return vertex_build_result\\n\\n    def get_snapshot(self):\\n        return copy.deepcopy(\\n            {\\n                \\\"run_manager\\\": self.run_manager.to_dict(),\\n                \\\"run_queue\\\": self._run_queue,\\n                \\\"vertices_layers\\\": self.vertices_layers,\\n                \\\"first_layer\\\": self.first_layer,\\n                \\\"inactive_vertices\\\": self.inactive_vertices,\\n                \\\"activated_vertices\\\": self.activated_vertices,\\n            }\\n        )\\n\\n    def _record_snapshot(self, vertex_id: str | None = None) -> None:\\n        self._snapshots.append(self.get_snapshot())\\n        if vertex_id:\\n            self._call_order.append(vertex_id)\\n\\n    def step(\\n        self,\\n        inputs: InputValueRequest | None = None,\\n        files: list[str] | None = None,\\n        user_id: str | None = None,\\n    ):\\n        \\\"\\\"\\\"Runs the next vertex in the graph.\\n\\n        Note:\\n            This function is a synchronous wrapper around `astep`.\\n            It creates an event loop if one does not exist.\\n\\n        Args:\\n            inputs: The inputs for the vertex. Defaults to None.\\n            files: The files for the vertex. Defaults to None.\\n            user_id: The user ID. Defaults to None.\\n        \\\"\\\"\\\"\\n        return run_until_complete(self.astep(inputs, files, user_id))\\n\\n    async def build_vertex(\\n        self,\\n        vertex_id: str,\\n        *,\\n        get_cache: GetCache | None = None,\\n        set_cache: SetCache | None = None,\\n        inputs_dict: dict[str, str] | None = None,\\n        files: list[str] | None = None,\\n        user_id: str | None = None,\\n        fallback_to_env_vars: bool = False,\\n        event_manager: EventManager | None = None,\\n    ) -> VertexBuildResult:\\n        \\\"\\\"\\\"Builds a vertex in the graph.\\n\\n        Args:\\n            vertex_id (str): The ID of the vertex to build.\\n            get_cache (GetCache): A coroutine to get the cache.\\n            set_cache (SetCache): A coroutine to set the cache.\\n            inputs_dict (Optional[Dict[str, str]]): Optional dictionary of inputs for the vertex. Defaults to None.\\n            files: (Optional[List[str]]): Optional list of files. Defaults to None.\\n            user_id (Optional[str]): Optional user ID. Defaults to None.\\n            fallback_to_env_vars (bool): Whether to fallback to environment variables. Defaults to False.\\n            event_manager (Optional[EventManager]): Optional event manager. Defaults to None.\\n\\n        Returns:\\n            Tuple: A tuple containing the next runnable vertices, top level vertices, result dictionary,\\n            parameters, validity flag, artifacts, and the built vertex.\\n\\n        Raises:\\n            ValueError: If no result is found for the vertex.\\n        \\\"\\\"\\\"\\n        vertex = self.get_vertex(vertex_id)\\n        self.run_manager.add_to_vertices_being_run(vertex_id)\\n        try:\\n            params = \\\"\\\"\\n            should_build = False\\n            # Loop components must always build, even when frozen,\\n            # because they need to iterate through their data\\n            is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n            if not vertex.frozen or is_loop_component:\\n                should_build = True\\n            else:\\n                # Frozen results can outlive a role or provider-policy change.\\n                # Reauthorize before even consulting the result cache so a\\n                # revoked provider cannot reuse output from an earlier run.\\n                await vertex.arequire_model_provider_policy(user_id, event_manager=event_manager)\\n                # Check the cache for the vertex\\n                if get_cache is not None:\\n                    cached_result = await get_cache(key=vertex.id)\\n                else:\\n                    cached_result = CacheMiss()\\n                if isinstance(cached_result, CacheMiss):\\n                    should_build = True\\n                else:\\n                    try:\\n                        cached_vertex_dict = cached_result[\\\"result\\\"]\\n                        # Now set update the vertex with the cached vertex\\n                        vertex.built = cached_vertex_dict[\\\"built\\\"]\\n                        vertex.artifacts = cached_vertex_dict[\\\"artifacts\\\"]\\n                        vertex.built_object = cached_vertex_dict[\\\"built_object\\\"]\\n                        vertex.built_result = cached_vertex_dict[\\\"built_result\\\"]\\n                        vertex.full_data = cached_vertex_dict[\\\"full_data\\\"]\\n                        vertex.results = cached_vertex_dict[\\\"results\\\"]\\n                        try:\\n                            vertex.finalize_build()\\n\\n                            if vertex.result is not None:\\n                                vertex.result.used_frozen_result = True\\n                        except Exception:  # noqa: BLE001\\n                            logger.debug(\\\"Error finalizing build\\\", exc_info=True)\\n                            vertex.built = False\\n                            should_build = True\\n                    except KeyError:\\n                        vertex.built = False\\n                        should_build = True\\n\\n            if should_build:\\n                await vertex.build(\\n                    user_id=user_id,\\n                    inputs=inputs_dict,\\n                    fallback_to_env_vars=fallback_to_env_vars,\\n                    files=files,\\n                    event_manager=event_manager,\\n                )\\n                if set_cache is not None:\\n                    vertex_dict = {\\n                        \\\"built\\\": vertex.built,\\n                        \\\"results\\\": vertex.results,\\n                        \\\"artifacts\\\": vertex.artifacts,\\n                        \\\"built_object\\\": vertex.built_object,\\n                        \\\"built_result\\\": vertex.built_result,\\n                        \\\"full_data\\\": vertex.full_data,\\n                    }\\n\\n                    await set_cache(key=vertex.id, data=vertex_dict)\\n\\n        except Exception as exc:\\n            if not isinstance(exc, ComponentBuildError):\\n                await logger.aexception(\\\"Error building Component\\\")\\n            raise\\n\\n        if vertex.result is not None:\\n            params = f\\\"{vertex.built_object_repr()}{params}\\\"\\n            valid = True\\n            result_dict = vertex.result\\n            artifacts = vertex.artifacts\\n        else:\\n            msg = f\\\"Error building Component: no result found for vertex {vertex_id}\\\"\\n            raise ValueError(msg)\\n\\n        return VertexBuildResult(\\n            result_dict=result_dict, params=params, valid=valid, artifacts=artifacts, vertex=vertex\\n        )\\n\\n    def get_vertex_edges(\\n        self,\\n        vertex_id: str,\\n        *,\\n        is_target: bool | None = None,\\n        is_source: bool | None = None,\\n    ) -> list[CycleEdge]:\\n        \\\"\\\"\\\"Returns a list of edges for a given vertex.\\\"\\\"\\\"\\n        # The idea here is to return the edges that have the vertex_id as source or target\\n        # or both\\n        return [\\n            edge\\n            for edge in self.edges\\n            if (edge.source_id == vertex_id and is_source is not False)\\n            or (edge.target_id == vertex_id and is_target is not False)\\n        ]\\n\\n    def get_vertices_with_target(self, vertex_id: str) -> list[Vertex]:\\n        \\\"\\\"\\\"Returns the vertices connected to a vertex.\\\"\\\"\\\"\\n        vertices: list[Vertex] = []\\n        for edge in self.edges:\\n            if edge.target_id == vertex_id:\\n                vertex = self.get_vertex(edge.source_id)\\n                if vertex is None:\\n                    continue\\n                vertices.append(vertex)\\n        return vertices\\n\\n    async def process(\\n        self,\\n        *,\\n        fallback_to_env_vars: bool,\\n        start_component_id: str | None = None,\\n        event_manager: EventManager | None = None,\\n    ) -> Graph:\\n        \\\"\\\"\\\"Processes the graph with vertices in each layer run in parallel.\\\"\\\"\\\"\\n        has_webhook_component = \\\"webhook\\\" in start_component_id.lower() if start_component_id else False\\n        if self.resumed_from_checkpoint:\\n            # A full re-sort would reset the restored run state and re-queue built vertices.\\n            first_layer = self.resume_first_layer()\\n        else:\\n            first_layer = self.sort_vertices(start_component_id=start_component_id)\\n        vertex_task_run_count: dict[str, int] = {}\\n        to_process = deque(first_layer)\\n        layer_index = 0\\n        chat_service = get_chat_service()\\n\\n        # Provide fallback cache functions if chat service is unavailable\\n        if chat_service is not None:\\n            get_cache_func = chat_service.get_cache\\n            set_cache_func = chat_service.set_cache\\n        else:\\n            # Fallback no-op cache functions for tests or when service unavailable\\n            async def get_cache_func(*args, **kwargs):  # noqa: ARG001\\n                return CacheMiss()\\n\\n            async def set_cache_func(*args, **kwargs) -> bool:  # noqa: ARG001\\n                return True\\n\\n        await self.initialize_run()\\n        lock = asyncio.Lock()\\n        while to_process:\\n            await self.check_and_handle_pause()\\n            current_batch = list(to_process)  # Copy current deque items to a list\\n            to_process.clear()  # Clear the deque for new items\\n            tasks = []\\n            for vertex_id in current_batch:\\n                vertex = self.get_vertex(vertex_id)\\n                task = asyncio.create_task(\\n                    self.build_vertex(\\n                        vertex_id=vertex_id,\\n                        user_id=self.user_id,\\n                        inputs_dict={},\\n                        fallback_to_env_vars=fallback_to_env_vars,\\n                        get_cache=get_cache_func,\\n                        set_cache=set_cache_func,\\n                        event_manager=event_manager,\\n                    ),\\n                    name=f\\\"{vertex.id} Run {vertex_task_run_count.get(vertex_id, 0)}\\\",\\n                )\\n                tasks.append(task)\\n                vertex_task_run_count[vertex_id] = vertex_task_run_count.get(vertex_id, 0) + 1\\n\\n            await logger.adebug(f\\\"Running layer {layer_index} with {len(tasks)} tasks, {current_batch}\\\")\\n            try:\\n                next_runnable_vertices = await self._execute_tasks(\\n                    tasks, lock=lock, has_webhook_component=has_webhook_component\\n                )\\n            except Exception:\\n                await logger.aexception(f\\\"Error executing tasks in layer {layer_index}\\\")\\n                raise\\n            if not next_runnable_vertices:\\n                break\\n            to_process.extend(next_runnable_vertices)\\n            layer_index += 1\\n\\n        await logger.adebug(\\\"Graph processing complete\\\")\\n        return self\\n\\n    def find_next_runnable_vertices(self, vertex_successors_ids: list[str]) -> list[str]:\\n        \\\"\\\"\\\"Determines the next set of runnable vertices from a list of successor vertex IDs.\\n\\n        For each successor, if it is not runnable, recursively finds its runnable\\n        predecessors; otherwise, includes the successor itself. Returns a sorted list of all such vertex IDs.\\n        \\\"\\\"\\\"\\n        next_runnable_vertices = set()\\n        for v_id in sorted(vertex_successors_ids):\\n            if not self.is_vertex_runnable(v_id):\\n                next_runnable_vertices.update(self.find_runnable_predecessors_for_successor(v_id))\\n            else:\\n                next_runnable_vertices.add(v_id)\\n\\n        return sorted(next_runnable_vertices)\\n\\n    async def get_next_runnable_vertices(self, lock: asyncio.Lock, vertex: Vertex, *, cache: bool = True) -> list[str]:\\n        \\\"\\\"\\\"Determines the next set of runnable vertex IDs after a vertex completes execution.\\n\\n        If the completed vertex is a state vertex, any recently activated state vertices are also included.\\n        Updates the run manager to reflect the new runnable state and optionally caches the updated graph state.\\n\\n        Args:\\n            lock: An asyncio lock for thread-safe updates.\\n            vertex: The vertex that has just finished execution.\\n            cache: If True, caches the updated graph state.\\n\\n        Returns:\\n            A list of vertex IDs that are ready to be executed next.\\n        \\\"\\\"\\\"\\n        v_id = vertex.id\\n        v_successors_ids = vertex.successors_ids\\n        self.run_manager.ran_at_least_once.add(v_id)\\n        async with lock:\\n            self.run_manager.remove_vertex_from_runnables(v_id)\\n            next_runnable_vertices = self.find_next_runnable_vertices(v_successors_ids)\\n\\n            for next_v_id in set(next_runnable_vertices):  # Use set to avoid duplicates\\n                if next_v_id == v_id:\\n                    next_runnable_vertices.remove(v_id)\\n                else:\\n                    self.run_manager.add_to_vertices_being_run(next_v_id)\\n            if cache and self.flow_id is not None:\\n                set_cache_coro = partial(get_chat_service().set_cache, key=self.flow_id)\\n                await set_cache_coro(data=self, lock=lock)\\n        if vertex.is_state:\\n            next_runnable_vertices.extend(self.activated_vertices)\\n        return next_runnable_vertices\\n\\n    async def _log_vertex_build_from_exception(self, vertex_id: str, result: Exception) -> None:\\n        \\\"\\\"\\\"Logs detailed information about a vertex build exception.\\n\\n        Formats the exception message and stack trace, constructs an error output,\\n        and records the failure using the vertex build logging system.\\n        \\\"\\\"\\\"\\n        if not self.persist_messages:\\n            # Ephemeral (anonymous serving) run: vertex-build rows retain component\\n            # params and outputs, so the no-persist contract covers them too.\\n            return\\n        if isinstance(result, ComponentBuildError):\\n            params = result.message\\n            tb = result.formatted_traceback\\n        else:\\n            from lfx.utils.exceptions import format_exception_message\\n\\n            tb = traceback.format_exc()\\n            await logger.aexception(\\\"Error building Component\\\")\\n\\n            params = format_exception_message(result)\\n        message = {\\\"errorMessage\\\": params, \\\"stackTrace\\\": tb}\\n        vertex = self.get_vertex(vertex_id)\\n        output_label = vertex.outputs[0][\\\"name\\\"] if vertex.outputs else \\\"output\\\"\\n        outputs = {output_label: OutputValue(message=message, type=\\\"error\\\")}\\n        result_data_response = {\\n            \\\"results\\\": {},\\n            \\\"outputs\\\": outputs,\\n            \\\"logs\\\": {},\\n            \\\"message\\\": {},\\n            \\\"artifacts\\\": {},\\n            \\\"timedelta\\\": None,\\n            \\\"duration\\\": None,\\n            \\\"used_frozen_result\\\": False,\\n        }\\n\\n        await log_vertex_build(\\n            flow_id=self.flow_id or \\\"\\\",\\n            vertex_id=vertex_id or \\\"errors\\\",\\n            valid=False,\\n            params=params,\\n            data=result_data_response,\\n            artifacts={},\\n            job_id=self._run_id if self._run_id else None,\\n        )\\n\\n    async def _execute_tasks(\\n        self, tasks: list[asyncio.Task], lock: asyncio.Lock, *, has_webhook_component: bool = False\\n    ) -> list[str]:\\n        \\\"\\\"\\\"Executes tasks in parallel, handling exceptions for each task.\\n\\n        Args:\\n            tasks: List of tasks to execute\\n            lock: Async lock for synchronization\\n            has_webhook_component: Whether the graph has a webhook component\\n        \\\"\\\"\\\"\\n        from lfx.graph.utils import emit_vertex_build_event\\n\\n        results = []\\n        completed_tasks = await asyncio.gather(*tasks, return_exceptions=True)\\n        vertices: list[Vertex] = []\\n        # Store build results for SSE emission after calculating next_runnable_vertices\\n        build_results: dict[str, VertexBuildResult] = {}\\n\\n        for i, result in enumerate(completed_tasks):\\n            task_name = tasks[i].get_name()\\n            vertex_id = tasks[i].get_name().split(\\\" \\\")[0]\\n\\n            if isinstance(result, Exception):\\n                await logger.aerror(f\\\"Task {task_name} failed with exception: {result}\\\")\\n                if has_webhook_component:\\n                    await self._log_vertex_build_from_exception(vertex_id, result)\\n\\n                # Cancel all remaining tasks\\n                for t in tasks[i + 1 :]:\\n                    t.cancel()\\n                raise result\\n            if isinstance(result, VertexBuildResult):\\n                if self.flow_id is not None:\\n                    # Ephemeral (anonymous serving) runs skip the persisted build\\n                    # record \u2014 vertex-build rows retain params/outputs \u2014 but still\\n                    # register the result so live SSE emission is unaffected.\\n                    if self.persist_messages:\\n                        await log_vertex_build(\\n                            flow_id=self.flow_id,\\n                            vertex_id=result.vertex.id,\\n                            valid=result.valid,\\n                            params=result.params,\\n                            data=result.result_dict,\\n                            artifacts=result.artifacts,\\n                            job_id=self._run_id if self._run_id else None,\\n                        )\\n                    # Store for SSE emission later\\n                    build_results[result.vertex.id] = result\\n\\n                vertices.append(result.vertex)\\n            else:\\n                msg = f\\\"Invalid result from task {task_name}: {result}\\\"\\n                raise TypeError(msg)\\n\\n        for v in vertices:\\n            # set all executed vertices as non-runnable to not run them again.\\n            # they could be calculated as predecessor or successors of parallel vertices\\n            # This could usually happen with input vertices like ChatInput\\n            self.run_manager.remove_vertex_from_runnables(v.id)\\n\\n            await logger.adebug(f\\\"Vertex {v.id}, result: {v.built_result}, object: {v.built_object}\\\")\\n\\n        for v in vertices:\\n            next_runnable_vertices = await self.get_next_runnable_vertices(lock, vertex=v, cache=False)\\n            results.extend(next_runnable_vertices)\\n\\n            # Emit SSE event with complete data including next_vertices_ids\\n            if self.flow_id is not None and v.id in build_results:\\n                build_result = build_results[v.id]\\n                # Get top level vertices for these next runnable vertices\\n                top_level = self.get_top_level_vertices(next_runnable_vertices)\\n                # Get inactivated vertices\\n                inactivated = list(self.inactivated_vertices.union(self.conditionally_excluded_vertices))\\n\\n                await emit_vertex_build_event(\\n                    flow_id=self.flow_id,\\n                    vertex_id=v.id,\\n                    valid=build_result.valid,\\n                    params=build_result.params,\\n                    data_dict=build_result.result_dict,\\n                    artifacts_dict=build_result.artifacts,\\n                    next_vertices_ids=next_runnable_vertices,\\n                    top_level_vertices=top_level,\\n                    inactivated_vertices=inactivated,\\n                )\\n\\n        return list(set(results))\\n\\n    def topological_sort(self) -> list[Vertex]:\\n        \\\"\\\"\\\"Performs a topological sort of the vertices in the graph.\\n\\n        Returns:\\n            List[Vertex]: A list of vertices in topological order.\\n\\n        Raises:\\n            ValueError: If the graph contains a cycle.\\n        \\\"\\\"\\\"\\n        # States: 0 = unvisited, 1 = visiting, 2 = visited\\n        state = dict.fromkeys(self.vertices, 0)\\n        sorted_vertices = []\\n\\n        def dfs(vertex) -> None:\\n            if state[vertex] == 1:\\n                # We have a cycle\\n                msg = \\\"Graph contains a cycle, cannot perform topological sort\\\"\\n                raise ValueError(msg)\\n            if state[vertex] == 0:\\n                state[vertex] = 1\\n                for edge in vertex.edges:\\n                    if edge.source_id == vertex.id:\\n                        dfs(self.get_vertex(edge.target_id))\\n                state[vertex] = 2\\n                sorted_vertices.append(vertex)\\n\\n        # Visit each vertex\\n        for vertex in self.vertices:\\n            if state[vertex] == 0:\\n                dfs(vertex)\\n\\n        return list(reversed(sorted_vertices))\\n\\n    def generator_build(self) -> Generator[Vertex, None, None]:\\n        \\\"\\\"\\\"Builds each vertex in the graph and yields it.\\\"\\\"\\\"\\n        sorted_vertices = self.topological_sort()\\n        logger.debug(\\\"There are %s vertices in the graph\\\", len(sorted_vertices))\\n        yield from sorted_vertices\\n\\n    def get_predecessors(self, vertex):\\n        \\\"\\\"\\\"Returns the predecessors of a vertex.\\\"\\\"\\\"\\n        return [self.get_vertex(source_id) for source_id in self.predecessor_map.get(vertex.id, [])]\\n\\n    def get_all_successors(self, vertex: Vertex, *, recursive=True, flat=True, visited=None):\\n        \\\"\\\"\\\"Returns all successors of a given vertex, optionally recursively and as a flat or nested list.\\n\\n        Args:\\n            vertex: The vertex whose successors are to be retrieved.\\n            recursive: If True, retrieves successors recursively; otherwise, only immediate successors.\\n            flat: If True, returns a flat list of successors; if False, returns a nested list structure.\\n            visited: Internal set used to track visited vertices and prevent cycles.\\n\\n        Returns:\\n            A list of successor vertices, either flat or nested depending on the `flat` parameter.\\n        \\\"\\\"\\\"\\n        if visited is None:\\n            visited = set()\\n\\n        # Prevent revisiting vertices to avoid infinite loops in cyclic graphs\\n        if vertex in visited:\\n            return []\\n\\n        visited.add(vertex)\\n\\n        successors = vertex.successors\\n        if not successors:\\n            return []\\n\\n        successors_result = []\\n\\n        for successor in successors:\\n            if recursive:\\n                next_successors = self.get_all_successors(successor, recursive=recursive, flat=flat, visited=visited)\\n                if flat:\\n                    successors_result.extend(next_successors)\\n                else:\\n                    successors_result.append(next_successors)\\n            if flat:\\n                successors_result.append(successor)\\n            else:\\n                successors_result.append([successor])\\n\\n        if not flat and successors_result:\\n            return [successors, *successors_result]\\n\\n        return successors_result\\n\\n    def get_successors(self, vertex: Vertex) -> list[Vertex]:\\n        \\\"\\\"\\\"Returns the immediate successor vertices of the given vertex.\\n\\n        Args:\\n            vertex: The vertex whose successors are to be retrieved.\\n\\n        Returns:\\n            A list of vertices that are direct successors of the specified vertex.\\n        \\\"\\\"\\\"\\n        return [self.get_vertex(target_id) for target_id in self.successor_map.get(vertex.id, set())]\\n\\n    def get_all_predecessors(self, vertex: Vertex, *, recursive: bool = True) -> list[Vertex]:\\n        \\\"\\\"\\\"Retrieves all predecessor vertices of a given vertex.\\n\\n        If `recursive` is True, returns both direct and indirect predecessors by\\n        traversing the graph recursively. If False, returns only the immediate predecessors.\\n        \\\"\\\"\\\"\\n        _predecessors = self.predecessor_map.get(vertex.id, [])\\n        predecessors = [self.get_vertex(v_id) for v_id in _predecessors]\\n        if recursive:\\n            for predecessor in _predecessors:\\n                predecessors.extend(self.get_all_predecessors(self.get_vertex(predecessor), recursive=recursive))\\n        else:\\n            predecessors.extend([self.get_vertex(predecessor) for predecessor in _predecessors])\\n        return predecessors\\n\\n    def get_vertex_neighbors(self, vertex: Vertex) -> dict[Vertex, int]:\\n        \\\"\\\"\\\"Returns a dictionary mapping each direct neighbor of a vertex to the count of connecting edges.\\n\\n        A neighbor is any vertex directly connected to the input vertex, either as a source or target.\\n        The count reflects the number of edges between the input vertex and each neighbor.\\n        \\\"\\\"\\\"\\n        neighbors: dict[Vertex, int] = {}\\n        for edge in self.edges:\\n            if edge.source_id == vertex.id:\\n                neighbor = self.get_vertex(edge.target_id)\\n                if neighbor is None:\\n                    continue\\n                if neighbor not in neighbors:\\n                    neighbors[neighbor] = 0\\n                neighbors[neighbor] += 1\\n            elif edge.target_id == vertex.id:\\n                neighbor = self.get_vertex(edge.source_id)\\n                if neighbor is None:\\n                    continue\\n                if neighbor not in neighbors:\\n                    neighbors[neighbor] = 0\\n                neighbors[neighbor] += 1\\n        return neighbors\\n\\n    @property\\n    def cycles(self):\\n        if self._cycles is None:\\n            if self._start is None:\\n                self._cycles = []\\n            else:\\n                entry_vertex = self._start.get_id()\\n                edges = [(e[\\\"data\\\"][\\\"sourceHandle\\\"][\\\"id\\\"], e[\\\"data\\\"][\\\"targetHandle\\\"][\\\"id\\\"]) for e in self._edges]\\n                self._cycles = find_all_cycle_edges(entry_vertex, edges)\\n        return self._cycles\\n\\n    @property\\n    def cycle_vertices(self):\\n        if self._cycle_vertices is None:\\n            edges = self._get_edges_as_list_of_tuples()\\n            self._cycle_vertices = set(find_cycle_vertices(edges))\\n        return self._cycle_vertices\\n\\n    def _build_edges(self) -> list[CycleEdge]:\\n        \\\"\\\"\\\"Builds the edges of the graph.\\\"\\\"\\\"\\n        # Edge takes two vertices as arguments, so we need to build the vertices first\\n        # and then build the edges\\n        # if we can't find a vertex, we raise an error\\n        edges: set[CycleEdge | Edge] = set()\\n        for edge in self._edges:\\n            new_edge = self.build_edge(edge)\\n            edges.add(new_edge)\\n        if self.vertices and not edges:\\n            logger.warning(\\\"Graph has vertices but no edges\\\")\\n        return list(cast(\\\"Iterable[CycleEdge]\\\", edges))\\n\\n    def build_edge(self, edge: EdgeData) -> CycleEdge | Edge:\\n        source = self.get_vertex(edge[\\\"source\\\"])\\n        target = self.get_vertex(edge[\\\"target\\\"])\\n\\n        if source is None:\\n            msg = f\\\"Source vertex {edge['source']} not found\\\"\\n            raise ValueError(msg)\\n        if target is None:\\n            msg = f\\\"Target vertex {edge['target']} not found\\\"\\n            raise ValueError(msg)\\n        if any(v in self.cycle_vertices for v in [source.id, target.id]):\\n            new_edge: CycleEdge | Edge = CycleEdge(source, target, edge)\\n        else:\\n            new_edge = Edge(source, target, edge)\\n        return new_edge\\n\\n    @staticmethod\\n    def _get_vertex_class(node_type: str, node_base_type: str, node_id: str) -> type[Vertex]:\\n        \\\"\\\"\\\"Returns the node class based on the node type.\\\"\\\"\\\"\\n        # First we check for the node_base_type\\n        node_name = node_id.split(\\\"-\\\")[0]\\n        if node_name in InterfaceComponentTypes or node_type in InterfaceComponentTypes:\\n            return InterfaceVertex\\n        if node_name in {\\\"SharedState\\\", \\\"Notify\\\", \\\"Listen\\\"}:\\n            return StateVertex\\n        if node_base_type in lazy_load_vertex_dict.vertex_type_map:\\n            return lazy_load_vertex_dict.vertex_type_map[node_base_type]\\n        if node_name in lazy_load_vertex_dict.vertex_type_map:\\n            return lazy_load_vertex_dict.vertex_type_map[node_name]\\n\\n        if node_type in lazy_load_vertex_dict.vertex_type_map:\\n            return lazy_load_vertex_dict.vertex_type_map[node_type]\\n        return Vertex\\n\\n    def _build_vertices(self) -> list[Vertex]:\\n        \\\"\\\"\\\"Builds the vertices of the graph.\\\"\\\"\\\"\\n        vertices: list[Vertex] = []\\n        for frontend_data in self._vertices:\\n            if frontend_data.get(\\\"type\\\") == NodeTypeEnum.NoteNode:\\n                continue\\n            try:\\n                vertex_instance = self.get_vertex(frontend_data[\\\"id\\\"])\\n            except ValueError:\\n                vertex_instance = self._create_vertex(frontend_data)\\n            vertices.append(vertex_instance)\\n\\n        return vertices\\n\\n    def _create_vertex(self, frontend_data: NodeData):\\n        vertex_data = frontend_data[\\\"data\\\"]\\n        vertex_type: str = vertex_data[\\\"type\\\"]\\n        vertex_base_type: str = vertex_data[\\\"node\\\"][\\\"template\\\"][\\\"_type\\\"]\\n        if \\\"id\\\" not in vertex_data:\\n            msg = f\\\"Vertex data for {vertex_data['display_name']} does not contain an id\\\"\\n            raise ValueError(msg)\\n\\n        vertex_class = self._get_vertex_class(vertex_type, vertex_base_type, vertex_data[\\\"id\\\"])\\n\\n        vertex_instance = vertex_class(frontend_data, graph=self)\\n        vertex_instance.set_top_level(self.top_level_vertices)\\n        return vertex_instance\\n\\n    def prepare(self, stop_component_id: str | None = None, start_component_id: str | None = None):\\n        self.initialize()\\n        if stop_component_id and start_component_id:\\n            msg = \\\"You can only provide one of stop_component_id or start_component_id\\\"\\n            raise ValueError(msg)\\n\\n        if stop_component_id or start_component_id:\\n            try:\\n                first_layer = self.sort_vertices(stop_component_id, start_component_id)\\n            except Exception:  # noqa: BLE001\\n                logger.exception(\\\"Error sorting vertices\\\")\\n                first_layer = self.sort_vertices()\\n        else:\\n            first_layer = self.sort_vertices()\\n\\n        for vertex_id in first_layer:\\n            self.run_manager.add_to_vertices_being_run(vertex_id)\\n            if vertex_id in self.cycle_vertices:\\n                self.run_manager.add_to_cycle_vertices(vertex_id)\\n        self._first_layer = sorted(first_layer)\\n        self._run_queue = deque(self._first_layer)\\n        self._prepared = True\\n        self._record_snapshot()\\n        return self\\n\\n    @staticmethod\\n    def get_children_by_vertex_type(vertex: Vertex, vertex_type: str) -> list[Vertex]:\\n        \\\"\\\"\\\"Returns the children of a vertex based on the vertex type.\\\"\\\"\\\"\\n        children = []\\n        vertex_types = [vertex.data[\\\"type\\\"]]\\n        if \\\"node\\\" in vertex.data:\\n            vertex_types += vertex.data[\\\"node\\\"][\\\"base_classes\\\"]\\n        if vertex_type in vertex_types:\\n            children.append(vertex)\\n        return children\\n\\n    def __repr__(self) -> str:\\n        vertex_ids = [vertex.id for vertex in self.vertices]\\n        edges_repr = \\\"\\\\n\\\".join([f\\\"  {edge.source_id} --> {edge.target_id}\\\" for edge in self.edges])\\n\\n        return (\\n            f\\\"Graph Representation:\\\\n\\\"\\n            f\\\"----------------------\\\\n\\\"\\n            f\\\"Vertices ({len(vertex_ids)}):\\\\n\\\"\\n            f\\\"  {', '.join(map(str, vertex_ids))}\\\\n\\\\n\\\"\\n            f\\\"Edges ({len(self.edges)}):\\\\n\\\"\\n            f\\\"{edges_repr}\\\"\\n        )\\n\\n    def __hash__(self) -> int:\\n        \\\"\\\"\\\"Return hash of the graph based on its string representation.\\\"\\\"\\\"\\n        return hash(self.__repr__())\\n\\n    def get_vertex_predecessors_ids(self, vertex_id: str) -> list[str]:\\n        \\\"\\\"\\\"Get the predecessor IDs of a vertex.\\\"\\\"\\\"\\n        return [v.id for v in self.get_predecessors(self.get_vertex(vertex_id))]\\n\\n    def get_vertex_successors_ids(self, vertex_id: str) -> list[str]:\\n        \\\"\\\"\\\"Get the successor IDs of a vertex.\\\"\\\"\\\"\\n        return [v.id for v in self.get_vertex(vertex_id).successors]\\n\\n    def get_vertex_input_status(self, vertex_id: str) -> bool:\\n        \\\"\\\"\\\"Check if a vertex is an input vertex.\\\"\\\"\\\"\\n        return self.get_vertex(vertex_id).is_input\\n\\n    def get_parent_map(self) -> dict[str, str | None]:\\n        \\\"\\\"\\\"Get the parent node map for all vertices.\\\"\\\"\\\"\\n        return {vertex.id: vertex.parent_node_id for vertex in self.vertices}\\n\\n    def get_vertex_ids(self) -> list[str]:\\n        \\\"\\\"\\\"Get all vertex IDs in the graph.\\\"\\\"\\\"\\n        return [vertex.id for vertex in self.vertices]\\n\\n    def get_terminal_nodes(self) -> list[str]:\\n        \\\"\\\"\\\"Returns vertex IDs that are terminal nodes (not source of any edge).\\n\\n        Terminal nodes are vertices that have no outgoing edges - they are not\\n        listed as source_id in any of the graph's edges.\\n\\n        Returns:\\n            list[str]: List of vertex IDs that are terminal nodes.\\n        \\\"\\\"\\\"\\n        return [vertex.id for vertex in self.vertices if not self.successor_map.get(vertex.id, [])]\\n\\n    def _orphaned_tool_vertex_ids(self) -> set[str]:\\n        \\\"\\\"\\\"Tool-mode components with no consumer, excluded from scheduling.\\n\\n        A tool-mode component's only output is the synthetic ``component_as_tool`` Tool, meaningful\\n        only when wired into a consumer (an Agent). With no successor it is a leftover \u2014 typically a\\n        tool left behind after its Agent was deleted \u2014 and building it standalone runs its underlying\\n        logic with no inputs (e.g. a URL fetch with no URL), raising a ComponentBuildError that fails\\n        the whole run. Skipping it keeps the rest of the flow runnable.\\n        \\\"\\\"\\\"\\n        orphaned: set[str] = set()\\n        for vertex in self.vertices:\\n            data = getattr(vertex, \\\"data\\\", None)\\n            node = data.get(\\\"node\\\") if isinstance(data, dict) else None\\n            if isinstance(node, dict) and node.get(\\\"tool_mode\\\") and not self.successor_map.get(vertex.id):\\n                orphaned.add(vertex.id)\\n        return orphaned\\n\\n    def sort_vertices(\\n        self,\\n        stop_component_id: str | None = None,\\n        start_component_id: str | None = None,\\n    ) -> list[str]:\\n        \\\"\\\"\\\"Sorts the vertices in the graph.\\\"\\\"\\\"\\n        self.mark_all_vertices(\\\"ACTIVE\\\")\\n\\n        first_layer, remaining_layers = get_sorted_vertices(\\n            vertices_ids=self.get_vertex_ids(),\\n            cycle_vertices=self.cycle_vertices,\\n            stop_component_id=stop_component_id,\\n            start_component_id=start_component_id,\\n            graph_dict=self.__to_dict(),\\n            in_degree_map=self.in_degree_map,\\n            successor_map=self.successor_map,\\n            predecessor_map=self.predecessor_map,\\n            is_input_vertex=self.get_vertex_input_status,\\n            get_vertex_predecessors=self.get_vertex_predecessors_ids,\\n            get_vertex_successors=self.get_vertex_successors_ids,\\n            is_cyclic=self.is_cyclic,\\n        )\\n\\n        # A run that explicitly targets the tool-mode node (the node's play button sets\\n        # stop/start to it) is the user inspecting its toolset output \u2014 never skip that one.\\n        orphaned_tools = self._orphaned_tool_vertex_ids() - {stop_component_id, start_component_id}\\n        if orphaned_tools:\\n            first_layer = [vertex_id for vertex_id in first_layer if vertex_id not in orphaned_tools]\\n            remaining_layers = [\\n                [vertex_id for vertex_id in layer if vertex_id not in orphaned_tools] for layer in remaining_layers\\n            ]\\n\\n        self.increment_run_count()\\n        self._sorted_vertices_layers = [first_layer, *remaining_layers]\\n        self.vertices_layers = remaining_layers\\n        self.vertices_to_run = set(chain.from_iterable([first_layer, *remaining_layers]))\\n        self.build_run_map()\\n        self._first_layer = first_layer\\n        return first_layer\\n\\n    @staticmethod\\n    def sort_interface_components_first(vertices_layers: list[list[str]]) -> list[list[str]]:\\n        \\\"\\\"\\\"Sorts the vertices in the graph so that vertices containing ChatInput or ChatOutput come first.\\\"\\\"\\\"\\n\\n        def contains_interface_component(vertex):\\n            return any(component.value in vertex for component in InterfaceComponentTypes)\\n\\n        # Sort each inner list so that vertices containing ChatInput or ChatOutput come first\\n        return [\\n            sorted(\\n                inner_list,\\n                key=lambda vertex: not contains_interface_component(vertex),\\n            )\\n            for inner_list in vertices_layers\\n        ]\\n\\n    def sort_by_avg_build_time(self, vertices_layers: list[list[str]]) -> list[list[str]]:\\n        \\\"\\\"\\\"Sorts the vertices in the graph so that vertices with the lowest average build time come first.\\\"\\\"\\\"\\n\\n        def sort_layer_by_avg_build_time(vertices_ids: list[str]) -> list[str]:\\n            \\\"\\\"\\\"Sorts the vertices in the graph so that vertices with the lowest average build time come first.\\\"\\\"\\\"\\n            if len(vertices_ids) == 1:\\n                return vertices_ids\\n            vertices_ids.sort(key=lambda vertex_id: self.get_vertex(vertex_id).avg_build_time)\\n\\n            return vertices_ids\\n\\n        return [sort_layer_by_avg_build_time(layer) for layer in vertices_layers]\\n\\n    def is_vertex_runnable(self, vertex_id: str) -> bool:\\n        \\\"\\\"\\\"Returns whether a vertex is runnable.\\\"\\\"\\\"\\n        # Check if vertex is conditionally excluded (for conditional routing)\\n        if vertex_id in self.conditionally_excluded_vertices:\\n            return False\\n        vertex = self.get_vertex(vertex_id)\\n        is_active = vertex.is_active()\\n        is_loop = vertex.is_loop\\n        # A resume keeps the checkpoint's vertices_to_run, so a restored-built vertex stays eligible\\n        # and the backward predecessor walk can re-execute it (Chat Input then persists a duplicate\\n        # User message). Vertices the resume un-builds have built=False and stay eligible.\\n        if not is_loop and vertex.built and vertex_id in self.checkpoint_restored_built_ids:\\n            return False\\n        return self.run_manager.is_vertex_runnable(vertex_id, is_active=is_active, is_loop=is_loop)\\n\\n    def build_run_map(self) -> None:\\n        \\\"\\\"\\\"Builds the run map for the graph.\\n\\n        This method is responsible for building the run map for the graph,\\n        which maps each node in the graph to its corresponding run function.\\n        \\\"\\\"\\\"\\n        self.run_manager.build_run_map(predecessor_map=self.predecessor_map, vertices_to_run=self.vertices_to_run)\\n\\n    def find_runnable_predecessors_for_successors(self, vertex_id: str) -> list[str]:\\n        \\\"\\\"\\\"For each successor of the current vertex, find runnable predecessors if any.\\n\\n        This checks the direct predecessors of each successor to identify any that are\\n        immediately runnable, expanding the search to ensure progress can be made.\\n        \\\"\\\"\\\"\\n        runnable_vertices = []\\n        for successor_id in self.run_manager.run_map.get(vertex_id, []):\\n            runnable_vertices.extend(self.find_runnable_predecessors_for_successor(successor_id))\\n\\n        return sorted(runnable_vertices)\\n\\n    def find_runnable_predecessors_for_successor(self, vertex_id: str) -> list[str]:\\n        runnable_vertices = []\\n        visited = set()\\n\\n        def find_runnable_predecessors(predecessor_id: str) -> None:\\n            if predecessor_id in visited:\\n                return\\n            visited.add(predecessor_id)\\n\\n            if self.is_vertex_runnable(predecessor_id):\\n                runnable_vertices.append(predecessor_id)\\n            else:\\n                for pred_pred_id in self.run_manager.run_predecessors.get(predecessor_id, []):\\n                    find_runnable_predecessors(pred_pred_id)\\n\\n        for predecessor_id in self.run_manager.run_predecessors.get(vertex_id, []):\\n            find_runnable_predecessors(predecessor_id)\\n        return runnable_vertices\\n\\n    def remove_from_predecessors(self, vertex_id: str) -> None:\\n        self.run_manager.remove_from_predecessors(vertex_id)\\n\\n    def remove_vertex_from_runnables(self, vertex_id: str) -> None:\\n        self.run_manager.remove_vertex_from_runnables(vertex_id)\\n\\n    def get_top_level_vertices(self, vertices_ids):\\n        \\\"\\\"\\\"Retrieves the top-level vertices from the given graph based on the provided vertex IDs.\\n\\n        Args:\\n            vertices_ids (list): A list of vertex IDs.\\n\\n        Returns:\\n            list: A list of top-level vertex IDs.\\n\\n        \\\"\\\"\\\"\\n        top_level_vertices = []\\n        for vertex_id in vertices_ids:\\n            vertex = self.get_vertex(vertex_id)\\n            if vertex.parent_is_top_level:\\n                top_level_vertices.append(vertex.parent_node_id)\\n            else:\\n                top_level_vertices.append(vertex_id)\\n        return top_level_vertices\\n\\n    def build_in_degree(self, edges: list[CycleEdge]) -> dict[str, int]:\\n        in_degree: dict[str, int] = defaultdict(int)\\n\\n        for edge in edges:\\n            # We don't need to count if a Component connects more than one\\n            # time to the same vertex.\\n            in_degree[edge.target_id] += 1\\n        for vertex in self.vertices:\\n            if vertex.id not in in_degree:\\n                in_degree[vertex.id] = 0\\n        return in_degree\\n\\n    @contextlib.asynccontextmanager\\n    async def create_subgraph(self, vertex_ids: set[str]) -> AsyncIterator[Graph]:\\n        \\\"\\\"\\\"Create an isolated subgraph containing only specified vertices.\\n\\n        This creates a new Graph instance with only the vertices and edges\\n        that connect the specified vertices. The subgraph shares the same\\n        flow_id and user_id but gets its own context copy.\\n\\n        Must be used as an async context manager to ensure proper cleanup\\n        of any pending trace tasks when the subgraph execution completes.\\n\\n        Args:\\n            vertex_ids: Set of vertex IDs to include in the subgraph\\n\\n        Yields:\\n            A new Graph instance containing only the specified vertices\\n\\n        Example:\\n            async with graph.create_subgraph(vertex_ids) as subgraph:\\n                subgraph.prepare()\\n                async for result in subgraph.async_start():\\n                    process(result)\\n        \\\"\\\"\\\"\\n        # Filter nodes to only include specified vertex IDs\\n        subgraph_nodes = [n for n in self._vertices if n[\\\"id\\\"] in vertex_ids]\\n\\n        # Filter edges to only include those connecting vertices in the subgraph\\n        subgraph_edges = [e for e in self._edges if e[\\\"source\\\"] in vertex_ids and e[\\\"target\\\"] in vertex_ids]\\n\\n        # Create new graph instance with copied context\\n        subgraph = Graph(\\n            flow_id=self.flow_id,\\n            flow_name=f\\\"{self.flow_name}_subgraph\\\" if self.flow_name else \\\"subgraph\\\",\\n            user_id=self.user_id,\\n            context=dict(self.context) if self.context else None,\\n        )\\n\\n        # Inherit parent's tracing context - subgraph is an extension of parent's execution\\n        subgraph._tracing_service = self._tracing_service\\n        subgraph._tracing_service_initialized = True\\n        subgraph._run_id = self._run_id\\n        subgraph.session_id = self.session_id\\n        # A subgraph extends the parent's run, so it inherits the ephemeral\\n        # (no-persist) decision too.\\n        subgraph.persist_messages = self.persist_messages\\n        # Sub-flows and loop iterations run under the same end user as the parent, so\\n        # the identity carrier propagates down (memory scopes to the same end user).\\n        subgraph.end_user_id = self.end_user_id\\n        subgraph.source_flow_id = self.source_flow_id\\n        subgraph._is_subgraph = True\\n\\n        # Add the filtered nodes and edges\\n        subgraph.add_nodes_and_edges(subgraph_nodes, subgraph_edges)\\n\\n        yield subgraph\\n\\n    @staticmethod\\n    def build_adjacency_maps(edges: list[CycleEdge]) -> tuple[dict[str, list[str]], dict[str, list[str]]]:\\n        \\\"\\\"\\\"Returns the adjacency maps for the graph.\\\"\\\"\\\"\\n        predecessor_map: dict[str, list[str]] = defaultdict(list)\\n        successor_map: dict[str, list[str]] = defaultdict(list)\\n        for edge in edges:\\n            predecessor_map[edge.target_id].append(edge.source_id)\\n            successor_map[edge.source_id].append(edge.target_id)\\n        return predecessor_map, successor_map\\n\\n    def __to_dict(self) -> dict[str, dict[str, list[str]]]:\\n        \\\"\\\"\\\"Converts the graph to a dictionary.\\\"\\\"\\\"\\n        result: dict = {}\\n        for vertex in self.vertices:\\n            vertex_id = vertex.id\\n            sucessors = [i.id for i in self.get_all_successors(vertex)]\\n            predecessors = [i.id for i in self.get_predecessors(vertex)]\\n            result |= {vertex_id: {\\\"successors\\\": sucessors, \\\"predecessors\\\": predecessors}}\\n        return result\\n\\n    def raw_event_metrics(self, optional_fields: dict | None = None) -> dict:\\n        if optional_fields is None:\\n            optional_fields = {}\\n        import time\\n\\n        return {\\\"timestamp\\\": time.time(), **optional_fields}\\n\\n    def before_callback_event(self, *args, **kwargs) -> RunStartedEvent:  # noqa: ARG002\\n        metrics = {}\\n        if hasattr(self, \\\"raw_event_metrics\\\"):\\n            metrics = self.raw_event_metrics({\\\"total_components\\\": len(self.vertices)})\\n        return RunStartedEvent(run_id=self._run_id, thread_id=self.flow_id, raw_event=metrics)\\n\\n    def after_callback_event(self, result: Any = None, *args, **kwargs) -> RunFinishedEvent:  # noqa: ARG002\\n        metrics = {}\\n        if hasattr(self, \\\"raw_event_metrics\\\"):\\n            metrics = self.raw_event_metrics({\\\"total_components\\\": len(self.vertices)})\\n        return RunFinishedEvent(run_id=self._run_id, thread_id=self.flow_id, result=None, raw_event=metrics)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/graph/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8f08e5e11c9d57f93fcdac1b23c1488222c77810601fe712b558adc714b25d0b\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.graph.schema import CHAT_COMPONENTS\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.vertex.base import Vertex\\n    from lfx.graph.vertex.vertex_types import CustomComponentVertex\\n\\n\\nclass Finish:\\n    def __bool__(self) -> bool:\\n        return True\\n\\n    def __eq__(self, /, other):\\n        return isinstance(other, Finish)\\n\\n    def __hash__(self) -> int:\\n        return hash(type(self))\\n\\n\\ndef _import_vertex_types():\\n    from lfx.graph.vertex import vertex_types\\n\\n    return vertex_types\\n\\n\\nclass VertexTypesDict:\\n    def __init__(self) -> None:\\n        self._all_types_dict = None\\n        self._types = _import_vertex_types\\n\\n    @property\\n    def all_types_dict(self):\\n        if self._all_types_dict is None:\\n            self._all_types_dict = self._build_dict()\\n        return self._all_types_dict\\n\\n    @property\\n    def vertex_type_map(self) -> dict[str, type[Vertex]]:\\n        return self.all_types_dict\\n\\n    def _build_dict(self):\\n        langchain_types_dict = self.get_type_dict()\\n        return {\\n            **langchain_types_dict,\\n            \\\"Custom\\\": [\\\"Custom Tool\\\", \\\"Python Function\\\"],\\n        }\\n\\n    def get_type_dict(self) -> dict[str, type[Vertex]]:\\n        types = self._types()\\n        return {\\n            \\\"CustomComponent\\\": types.CustomComponentVertex,\\n            \\\"Component\\\": types.ComponentVertex,\\n            **dict.fromkeys(CHAT_COMPONENTS, types.InterfaceVertex),\\n        }\\n\\n    def get_custom_component_vertex_type(self) -> type[CustomComponentVertex]:\\n        return self._types().CustomComponentVertex\\n\\n\\nlazy_load_vertex_dict = VertexTypesDict()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/graph/runnable_vertices_manager.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"73ea903f79282b202c2000c348e3628b3e05211227eaae6400c5fa11020105f0\",\"content\":\"from collections import defaultdict\\n\\n\\nclass RunnableVerticesManager:\\n    def __init__(self) -> None:\\n        self.run_map: dict[str, list[str]] = defaultdict(list)  # Tracks successors of each vertex\\n        self.run_predecessors: dict[str, list[str]] = defaultdict(list)  # Tracks predecessors for each vertex\\n        self.vertices_to_run: set[str] = set()  # Set of vertices that are ready to run\\n        self.vertices_being_run: set[str] = set()  # Set of vertices that are currently running\\n        self.cycle_vertices: set[str] = set()  # Set of vertices that are in a cycle\\n        self.ran_at_least_once: set[str] = set()  # Set of vertices that have been run at least once\\n\\n    def to_dict(self) -> dict:\\n        return {\\n            \\\"run_map\\\": self.run_map,\\n            \\\"run_predecessors\\\": self.run_predecessors,\\n            \\\"vertices_to_run\\\": self.vertices_to_run,\\n            \\\"vertices_being_run\\\": self.vertices_being_run,\\n            \\\"ran_at_least_once\\\": self.ran_at_least_once,\\n        }\\n\\n    @classmethod\\n    def from_dict(cls, data: dict) -> \\\"RunnableVerticesManager\\\":\\n        instance = cls()\\n        instance.run_map = data[\\\"run_map\\\"]\\n        instance.run_predecessors = data[\\\"run_predecessors\\\"]\\n        instance.vertices_to_run = data[\\\"vertices_to_run\\\"]\\n        instance.vertices_being_run = data[\\\"vertices_being_run\\\"]\\n        instance.ran_at_least_once = data.get(\\\"ran_at_least_once\\\", set())\\n        return instance\\n\\n    def __getstate__(self) -> object:\\n        return {\\n            \\\"run_map\\\": self.run_map,\\n            \\\"run_predecessors\\\": self.run_predecessors,\\n            \\\"vertices_to_run\\\": self.vertices_to_run,\\n            \\\"vertices_being_run\\\": self.vertices_being_run,\\n            \\\"ran_at_least_once\\\": self.ran_at_least_once,\\n        }\\n\\n    def __setstate__(self, state: dict) -> None:\\n        self.run_map = state[\\\"run_map\\\"]\\n        self.run_predecessors = state[\\\"run_predecessors\\\"]\\n        self.vertices_to_run = state[\\\"vertices_to_run\\\"]\\n        self.vertices_being_run = state[\\\"vertices_being_run\\\"]\\n        self.ran_at_least_once = state[\\\"ran_at_least_once\\\"]\\n\\n    def all_predecessors_are_fulfilled(self) -> bool:\\n        return all(not value for value in self.run_predecessors.values())\\n\\n    def update_run_state(self, run_predecessors: dict, vertices_to_run: set) -> None:\\n        self.run_predecessors.update(run_predecessors)\\n        self.vertices_to_run.update(vertices_to_run)\\n        self.build_run_map(self.run_predecessors, self.vertices_to_run)\\n\\n    def is_vertex_runnable(self, vertex_id: str, *, is_active: bool, is_loop: bool = False) -> bool:\\n        \\\"\\\"\\\"Determines if a vertex is runnable based on its active state and predecessor fulfillment.\\\"\\\"\\\"\\n        if not is_active:\\n            return False\\n        if vertex_id in self.vertices_being_run:\\n            return False\\n        if vertex_id not in self.vertices_to_run:\\n            return False\\n\\n        return self.are_all_predecessors_fulfilled(vertex_id, is_loop=is_loop)\\n\\n    def are_all_predecessors_fulfilled(self, vertex_id: str, *, is_loop: bool) -> bool:\\n        \\\"\\\"\\\"Determines if all predecessors for a vertex have been fulfilled.\\n\\n        This method checks if a vertex is ready to run by verifying that either:\\n        1. It has no pending predecessors that need to complete first\\n        2. For vertices in cycles, none of its pending predecessors are also cycle vertices\\n           (which would create a circular dependency)\\n\\n        Args:\\n            vertex_id (str): The ID of the vertex to check\\n            is_loop (bool): Whether the vertex is a loop\\n        Returns:\\n            bool: True if all predecessor conditions are met, False otherwise\\n        \\\"\\\"\\\"\\n        # Get pending predecessors, return True if none exist\\n        pending = self.run_predecessors.get(vertex_id, [])\\n        if not pending:\\n            return True\\n\\n        # For cycle vertices, check if any pending predecessors are also in cycle\\n        # Using set intersection is faster than iteration\\n        if vertex_id in self.cycle_vertices:\\n            pending_set = set(pending)\\n            running_predecessors = pending_set & self.vertices_being_run\\n\\n            # If this vertex has already run at least once, be strict: wait until NOTHING is pending or running\\n            if vertex_id in self.ran_at_least_once:\\n                # Wait if there are still pending or running predecessors; otherwise allow.\\n                return not (pending_set or running_predecessors)\\n\\n            # FIRST execution of a cycle vertex\\n            # Allow running **only** if it's a loop AND *all* pending predecessors are cycle vertices\\n            return is_loop and pending_set <= self.cycle_vertices\\n        return False\\n\\n    def remove_from_predecessors(self, vertex_id: str) -> None:\\n        \\\"\\\"\\\"Removes a vertex from the predecessor list of its successors.\\\"\\\"\\\"\\n        predecessors = self.run_map.get(vertex_id, [])\\n        for predecessor in predecessors:\\n            if vertex_id in self.run_predecessors[predecessor]:\\n                self.run_predecessors[predecessor].remove(vertex_id)\\n\\n    def build_run_map(self, predecessor_map, vertices_to_run) -> None:\\n        \\\"\\\"\\\"Builds a map of vertices and their runnable successors.\\\"\\\"\\\"\\n        self.run_map = defaultdict(list)\\n        for vertex_id, predecessors in predecessor_map.items():\\n            for predecessor in predecessors:\\n                self.run_map[predecessor].append(vertex_id)\\n        self.run_predecessors = predecessor_map.copy()\\n        self.vertices_to_run = vertices_to_run\\n\\n    def update_vertex_run_state(self, vertex_id: str, *, is_runnable: bool) -> None:\\n        \\\"\\\"\\\"Updates the runnable state of a vertex.\\\"\\\"\\\"\\n        if is_runnable:\\n            self.vertices_to_run.add(vertex_id)\\n        else:\\n            self.vertices_being_run.discard(vertex_id)\\n\\n    def remove_vertex_from_runnables(self, v_id) -> None:\\n        self.update_vertex_run_state(v_id, is_runnable=False)\\n        self.remove_from_predecessors(v_id)\\n\\n    def add_to_vertices_being_run(self, v_id) -> None:\\n        self.vertices_being_run.add(v_id)\\n\\n    def add_to_cycle_vertices(self, v_id):\\n        self.cycle_vertices.add(v_id)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/graph/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d5af2989cb5d45537a072aa9be1398bbb85e0de56cec0dde1a966e60817b91a6\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, NamedTuple, Protocol\\n\\nfrom typing_extensions import NotRequired, TypedDict\\n\\nfrom lfx.graph.edge.schema import EdgeData\\nfrom lfx.graph.vertex.schema import NodeData\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.schema import ResultData\\n    from lfx.graph.vertex.base import Vertex\\n    from lfx.schema.log import LoggableType\\n\\n\\nclass ViewPort(TypedDict):\\n    x: float\\n    y: float\\n    zoom: float\\n\\n\\nclass GraphData(TypedDict):\\n    nodes: list[NodeData]\\n    edges: list[EdgeData]\\n    viewport: NotRequired[ViewPort]\\n\\n\\nclass GraphDump(TypedDict, total=False):\\n    data: GraphData\\n    is_component: bool\\n    name: str\\n    description: str\\n    endpoint_name: str\\n\\n\\nclass VertexBuildResult(NamedTuple):\\n    result_dict: ResultData\\n    params: str\\n    valid: bool\\n    artifacts: dict\\n    vertex: Vertex\\n\\n\\nclass OutputConfigDict(TypedDict):\\n    cache: bool\\n\\n\\nclass StartConfigDict(TypedDict):\\n    output: OutputConfigDict\\n\\n\\nclass LogCallbackFunction(Protocol):\\n    def __call__(self, event_name: str, log: LoggableType) -> None: ...\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/graph/state_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3896087df790ff7763b4c748b0c99876e2ebd896d7f4643937f489fcf65e1c9e\",\"content\":\"import re\\n\\nfrom lfx.graph.state.model import create_state_model\\nfrom lfx.helpers.base_model import BaseModel\\n\\n\\ndef camel_to_snake(camel_str: str) -> str:\\n    return re.sub(r\\\"(?<!^)(?=[A-Z])\\\", \\\"_\\\", camel_str).lower()\\n\\n\\ndef create_state_model_from_graph(graph: BaseModel) -> type[BaseModel]:\\n    \\\"\\\"\\\"Create a Pydantic state model from a graph representation.\\n\\n    This function generates a Pydantic model that represents the state of an entire graph.\\n    It creates getter methods for each vertex in the graph, allowing access to the state\\n    of individual components within the graph structure.\\n\\n    Args:\\n        graph (BaseModel): The graph object from which to create the state model.\\n            This should be a Pydantic model representing the graph structure,\\n            with a 'vertices' attribute containing all graph vertices.\\n\\n    Returns:\\n        type[BaseModel]: A dynamically created Pydantic model class representing\\n            the state of the entire graph. This model will have properties\\n            corresponding to each vertex in the graph, with names converted from\\n            the vertex IDs to snake case.\\n\\n    Raises:\\n        ValueError: If any vertex in the graph does not have a properly initialized\\n            component instance (i.e., if vertex.custom_component is None).\\n\\n    Notes:\\n        - Each vertex in the graph must have a 'custom_component' attribute.\\n        - The 'custom_component' must have a 'get_state_model_instance_getter' method.\\n        - Vertex IDs are converted from camel case to snake case for the resulting model's field names.\\n        - The resulting model uses the 'create_state_model' function with validation disabled.\\n\\n    Example:\\n        >>> class Vertex(BaseModel):\\n        ...     id: str\\n        ...     custom_component: Any\\n        >>> class Graph(BaseModel):\\n        ...     vertices: List[Vertex]\\n        >>> # Assume proper setup of vertices and components\\n        >>> graph = Graph(vertices=[...])\\n        >>> GraphStateModel = create_state_model_from_graph(graph)\\n        >>> graph_state = GraphStateModel()\\n        >>> # Access component states, e.g.:\\n        >>> print(graph_state.some_component_name)\\n    \\\"\\\"\\\"\\n    for vertex in graph.vertices:\\n        if hasattr(vertex, \\\"custom_component\\\") and vertex.custom_component is None:\\n            msg = f\\\"Vertex {vertex.id} does not have a component instance.\\\"\\n            raise ValueError(msg)\\n\\n    state_model_getters = [\\n        vertex.custom_component.get_state_model_instance_getter()\\n        for vertex in graph.vertices\\n        if hasattr(vertex, \\\"custom_component\\\") and hasattr(vertex.custom_component, \\\"get_state_model_instance_getter\\\")\\n    ]\\n    fields = {\\n        camel_to_snake(vertex.id): state_model_getter\\n        for vertex, state_model_getter in zip(graph.vertices, state_model_getters, strict=False)\\n    }\\n    return create_state_model(model_name=\\\"GraphStateModel\\\", validate=False, **fields)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/graph/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0a9206fd99eee8b19570abef865b031e2b8398dd39a34366d764900c41ad8f67\",\"content\":\"import copy\\nfrom collections import defaultdict, deque\\nfrom collections.abc import Callable\\nfrom typing import Any\\n\\nimport networkx as nx\\n\\nfrom lfx.log.logger import logger\\n\\nPRIORITY_LIST_OF_INPUTS = [\\\"webhook\\\", \\\"chat\\\"]\\nMAX_CYCLE_APPEARANCES = 2\\n\\n\\ndef find_start_component_id(vertices, *, is_webhook: bool = False):\\n    \\\"\\\"\\\"Finds the component ID from a list of vertices based on a priority list of input types.\\n\\n    Args:\\n        vertices (list): A list of vertex IDs.\\n        is_webhook (bool, optional): Whether the flow is being run as a webhook. Defaults to False.\\n\\n    Returns:\\n        str or None: The component ID that matches the highest priority input type, or None if no match is found.\\n    \\\"\\\"\\\"\\n    # Set priority list based on whether this is a webhook flow\\n    priority_inputs = [\\\"webhook\\\"] if is_webhook else PRIORITY_LIST_OF_INPUTS\\n\\n    # Check input types in priority order\\n    for input_type_str in priority_inputs:\\n        component_id = next((vertex_id for vertex_id in vertices if input_type_str in vertex_id.lower()), None)\\n        if component_id:\\n            return component_id\\n    return None\\n\\n\\ndef find_last_node(nodes, edges):\\n    \\\"\\\"\\\"This function receives a flow and returns the last node.\\\"\\\"\\\"\\n    source_ids = {edge[\\\"source\\\"] for edge in edges}\\n    for node in nodes:\\n        if node[\\\"id\\\"] not in source_ids:\\n            return node\\n    return None\\n\\n\\ndef add_parent_node_id(nodes, parent_node_id) -> None:\\n    \\\"\\\"\\\"This function receives a list of nodes and adds a parent_node_id to each node.\\\"\\\"\\\"\\n    for node in nodes:\\n        node[\\\"parent_node_id\\\"] = parent_node_id\\n\\n\\ndef add_frozen(nodes, frozen) -> None:\\n    \\\"\\\"\\\"This function receives a list of nodes and adds a frozen to each node.\\\"\\\"\\\"\\n    for node in nodes:\\n        node[\\\"data\\\"][\\\"node\\\"][\\\"frozen\\\"] = frozen\\n\\n\\ndef ungroup_node(group_node_data, base_flow):\\n    template, flow, frozen = (\\n        group_node_data[\\\"node\\\"][\\\"template\\\"],\\n        group_node_data[\\\"node\\\"][\\\"flow\\\"],\\n        group_node_data[\\\"node\\\"].get(\\\"frozen\\\", False),\\n    )\\n    parent_node_id = group_node_data[\\\"id\\\"]\\n\\n    g_nodes = flow[\\\"data\\\"][\\\"nodes\\\"]\\n    add_parent_node_id(g_nodes, parent_node_id)\\n    add_frozen(g_nodes, frozen)\\n    g_edges = flow[\\\"data\\\"][\\\"edges\\\"]\\n\\n    # Redirect edges to the correct proxy node\\n    updated_edges = get_updated_edges(base_flow, g_nodes, g_edges, group_node_data)\\n\\n    # Update template values\\n    update_template(template, g_nodes)\\n\\n    nodes = [n for n in base_flow[\\\"nodes\\\"] if n[\\\"id\\\"] != group_node_data[\\\"id\\\"]] + g_nodes\\n    edges = (\\n        [e for e in base_flow[\\\"edges\\\"] if e[\\\"target\\\"] != group_node_data[\\\"id\\\"] and e[\\\"source\\\"] != group_node_data[\\\"id\\\"]]\\n        + g_edges\\n        + updated_edges\\n    )\\n\\n    base_flow[\\\"nodes\\\"] = nodes\\n    base_flow[\\\"edges\\\"] = edges\\n\\n    return nodes\\n\\n\\ndef process_flow(flow_object):\\n    cloned_flow = copy.deepcopy(flow_object)\\n    processed_nodes = set()  # To keep track of processed nodes\\n\\n    def process_node(node) -> None:\\n        node_id = node.get(\\\"id\\\")\\n\\n        # If node already processed, skip\\n        if node_id in processed_nodes:\\n            return\\n\\n        if node.get(\\\"data\\\") and node[\\\"data\\\"].get(\\\"node\\\") and node[\\\"data\\\"][\\\"node\\\"].get(\\\"flow\\\"):\\n            process_flow(node[\\\"data\\\"][\\\"node\\\"][\\\"flow\\\"][\\\"data\\\"])\\n            new_nodes = ungroup_node(node[\\\"data\\\"], cloned_flow)\\n            # Add new nodes to the queue for future processing\\n            nodes_to_process.extend(new_nodes)\\n\\n        # Mark node as processed\\n        processed_nodes.add(node_id)\\n\\n    nodes_to_process = deque(cloned_flow[\\\"nodes\\\"])\\n\\n    while nodes_to_process:\\n        node = nodes_to_process.popleft()\\n        process_node(node)\\n\\n    return cloned_flow\\n\\n\\ndef update_template(template, g_nodes) -> None:\\n    \\\"\\\"\\\"Updates the template of a node in a graph with the given template.\\n\\n    Args:\\n        template (dict): The new template to update the node with.\\n        g_nodes (list): The list of nodes in the graph.\\n    \\\"\\\"\\\"\\n    for value in template.values():\\n        if not value.get(\\\"proxy\\\"):\\n            continue\\n        proxy_dict = value[\\\"proxy\\\"]\\n        field, id_ = proxy_dict[\\\"field\\\"], proxy_dict[\\\"id\\\"]\\n        node_index = next((i for i, n in enumerate(g_nodes) if n[\\\"id\\\"] == id_), -1)\\n        if node_index != -1:\\n            display_name = None\\n            show = g_nodes[node_index][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][field][\\\"show\\\"]\\n            advanced = g_nodes[node_index][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][field][\\\"advanced\\\"]\\n            if \\\"display_name\\\" in g_nodes[node_index][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][field]:\\n                display_name = g_nodes[node_index][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][field][\\\"display_name\\\"]\\n            else:\\n                display_name = g_nodes[node_index][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][field][\\\"name\\\"]\\n\\n            g_nodes[node_index][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][field] = value\\n            g_nodes[node_index][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][field][\\\"show\\\"] = show\\n            g_nodes[node_index][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][field][\\\"advanced\\\"] = advanced\\n            g_nodes[node_index][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][field][\\\"display_name\\\"] = display_name\\n\\n\\ndef update_target_handle(new_edge, g_nodes):\\n    \\\"\\\"\\\"Updates the target handle of a given edge if it is a proxy node.\\n\\n    Args:\\n        new_edge (dict): The edge to update.\\n        g_nodes (list): The list of nodes in the graph.\\n\\n    Returns:\\n        dict: The updated edge.\\n    \\\"\\\"\\\"\\n    target_handle = new_edge[\\\"data\\\"][\\\"targetHandle\\\"]\\n    if proxy := target_handle.get(\\\"proxy\\\"):\\n        proxy_id = proxy[\\\"id\\\"]\\n        for node in g_nodes:\\n            if node[\\\"id\\\"] == proxy_id:\\n                set_new_target_handle(proxy_id, new_edge, target_handle, node)\\n                break\\n\\n    return new_edge\\n\\n\\ndef set_new_target_handle(proxy_id, new_edge, target_handle, node) -> None:\\n    \\\"\\\"\\\"Sets a new target handle for a given edge.\\n\\n    Args:\\n        proxy_id (str): The ID of the proxy.\\n        new_edge (dict): The new edge to be created.\\n        target_handle (dict): The target handle of the edge.\\n        node (dict): The node containing the edge.\\n    \\\"\\\"\\\"\\n    new_edge[\\\"target\\\"] = proxy_id\\n    type_ = target_handle.get(\\\"type\\\")\\n    if type_ is None:\\n        msg = \\\"The 'type' key must be present in target_handle.\\\"\\n        raise KeyError(msg)\\n\\n    field = target_handle[\\\"proxy\\\"][\\\"field\\\"]\\n    new_target_handle = {\\n        \\\"fieldName\\\": field,\\n        \\\"type\\\": type_,\\n        \\\"id\\\": proxy_id,\\n    }\\n\\n    node_data = node[\\\"data\\\"][\\\"node\\\"]\\n    if node_data.get(\\\"flow\\\"):\\n        field_template_proxy = node_data[\\\"template\\\"][field][\\\"proxy\\\"]\\n        new_target_handle[\\\"proxy\\\"] = {\\n            \\\"field\\\": field_template_proxy[\\\"field\\\"],\\n            \\\"id\\\": field_template_proxy[\\\"id\\\"],\\n        }\\n\\n    if input_types := target_handle.get(\\\"inputTypes\\\"):\\n        new_target_handle[\\\"inputTypes\\\"] = input_types\\n\\n    new_edge[\\\"data\\\"][\\\"targetHandle\\\"] = new_target_handle\\n\\n\\ndef _get_node_by_id(nodes, node_id):\\n    return next((node for node in nodes if node[\\\"id\\\"] == node_id), None)\\n\\n\\ndef _get_group_output_proxy(group_node_data, source_handle, g_nodes):\\n    if not group_node_data:\\n        return None\\n\\n    source_name = source_handle.get(\\\"name\\\")\\n    if not source_name:\\n        return None\\n\\n    for output in group_node_data.get(\\\"node\\\", {}).get(\\\"outputs\\\", []):\\n        if output.get(\\\"name\\\") == source_name:\\n            if proxy := output.get(\\\"proxy\\\"):\\n                return proxy\\n            break\\n\\n    for node in sorted(g_nodes, key=lambda item: len(item[\\\"id\\\"]), reverse=True):\\n        prefix = f\\\"{node['id']}_\\\"\\n        if source_name.startswith(prefix):\\n            return {\\\"id\\\": node[\\\"id\\\"], \\\"name\\\": source_name.removeprefix(prefix)}\\n\\n    return None\\n\\n\\ndef _get_output_types(node, output_name):\\n    outputs = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"outputs\\\", [])\\n    output = next((item for item in outputs if item.get(\\\"name\\\") == output_name), None)\\n    if output:\\n        return output.get(\\\"types\\\")\\n    return None\\n\\n\\ndef _update_source_handle_from_group_output(new_edge, group_node_data, g_nodes):\\n    source_handle = new_edge[\\\"data\\\"][\\\"sourceHandle\\\"]\\n    proxy = _get_group_output_proxy(group_node_data, source_handle, g_nodes)\\n    if not proxy:\\n        return False\\n\\n    proxy_id = proxy[\\\"id\\\"]\\n    output_name = proxy.get(\\\"name\\\") or proxy.get(\\\"field\\\")\\n    if not output_name:\\n        return False\\n\\n    node = _get_node_by_id(g_nodes, proxy_id)\\n    if node is None:\\n        msg = f\\\"Group output proxy references missing node {proxy_id}\\\"\\n        raise ValueError(msg)\\n\\n    new_edge[\\\"source\\\"] = proxy_id\\n    new_source_handle = copy.deepcopy(source_handle)\\n    new_source_handle[\\\"id\\\"] = proxy_id\\n    new_source_handle[\\\"name\\\"] = output_name\\n    if data_type := node.get(\\\"data\\\", {}).get(\\\"type\\\"):\\n        new_source_handle[\\\"dataType\\\"] = data_type\\n    if output_types := source_handle.get(\\\"output_types\\\") or _get_output_types(node, output_name):\\n        new_source_handle[\\\"output_types\\\"] = output_types\\n    new_edge[\\\"data\\\"][\\\"sourceHandle\\\"] = new_source_handle\\n    return True\\n\\n\\ndef update_source_handle(new_edge, g_nodes, g_edges, group_node_data=None):\\n    \\\"\\\"\\\"Updates the source handle of a group output edge.\\n\\n    Args:\\n        new_edge (dict): The edge to update.\\n        g_nodes: The graph nodes.\\n        g_edges: The graph edges.\\n        group_node_data: The group node data containing output proxy metadata.\\n\\n    Returns:\\n        dict: The updated edge with the new source handle.\\n    \\\"\\\"\\\"\\n    if _update_source_handle_from_group_output(new_edge, group_node_data, g_nodes):\\n        return new_edge\\n\\n    last_node = copy.deepcopy(find_last_node(g_nodes, g_edges))\\n    if last_node is None:\\n        msg = \\\"Unable to resolve group output source node\\\"\\n        raise ValueError(msg)\\n    new_edge[\\\"source\\\"] = last_node[\\\"id\\\"]\\n    new_source_handle = new_edge[\\\"data\\\"][\\\"sourceHandle\\\"]\\n    new_source_handle[\\\"id\\\"] = last_node[\\\"id\\\"]\\n    new_edge[\\\"data\\\"][\\\"sourceHandle\\\"] = new_source_handle\\n    return new_edge\\n\\n\\ndef get_updated_edges(base_flow, g_nodes, g_edges, group_node_data):\\n    \\\"\\\"\\\"Get updated edges.\\n\\n    Given a base flow, a list of graph nodes and a group node id, returns a list of updated edges.\\n    An updated edge is an edge that has its target or source handle updated based on the group node id.\\n\\n    Args:\\n        base_flow (dict): The base flow containing a list of edges.\\n        g_nodes (list): A list of graph nodes.\\n        g_edges (list): A list of graph edges.\\n        group_node_data (dict | str): The group node data or id.\\n\\n    Returns:\\n        list: A list of updated edges.\\n    \\\"\\\"\\\"\\n    if isinstance(group_node_data, str):\\n        group_node_id = group_node_data\\n        group_node_data = None\\n    else:\\n        group_node_id = group_node_data[\\\"id\\\"]\\n\\n    updated_edges = []\\n    for edge in base_flow[\\\"edges\\\"]:\\n        new_edge = copy.deepcopy(edge)\\n        if new_edge[\\\"target\\\"] == group_node_id:\\n            new_edge = update_target_handle(new_edge, g_nodes)\\n\\n        if new_edge[\\\"source\\\"] == group_node_id:\\n            new_edge = update_source_handle(new_edge, g_nodes, g_edges, group_node_data)\\n\\n        if group_node_id in {edge[\\\"target\\\"], edge[\\\"source\\\"]}:\\n            updated_edges.append(new_edge)\\n    return updated_edges\\n\\n\\ndef get_successors(graph: dict[str, dict[str, list[str]]], vertex_id: str) -> list[str]:\\n    successors_result = []\\n    stack = [vertex_id]\\n    visited = set()\\n    while stack:\\n        current_id = stack.pop()\\n        if current_id in visited:\\n            continue\\n        visited.add(current_id)\\n        if current_id != vertex_id:\\n            successors_result.append(current_id)\\n        stack.extend(graph[current_id][\\\"successors\\\"])\\n    return successors_result\\n\\n\\ndef get_root_of_group_node(\\n    graph: dict[str, dict[str, list[str]]], vertex_id: str, parent_node_map: dict[str, str | None]\\n) -> str:\\n    \\\"\\\"\\\"Returns the root of a group node.\\\"\\\"\\\"\\n    if vertex_id in parent_node_map.values():\\n        # Get all vertices with vertex_id as their parent node\\n        child_vertices = [v_id for v_id, parent_id in parent_node_map.items() if parent_id == vertex_id]\\n\\n        # Now go through successors of the child vertices\\n        # and get the one that none of its successors is in child_vertices\\n        for child_id in child_vertices:\\n            successors = get_successors(graph, child_id)\\n            if not any(successor in child_vertices for successor in successors):\\n                return child_id\\n\\n    msg = f\\\"Vertex {vertex_id} is not a top level vertex or no root vertex found\\\"\\n    raise ValueError(msg)\\n\\n\\ndef sort_up_to_vertex(\\n    graph: dict[str, dict[str, list[str]]],\\n    vertex_id: str,\\n    *,\\n    parent_node_map: dict[str, str | None] | None = None,\\n    is_start: bool = False,\\n) -> list[str]:\\n    \\\"\\\"\\\"Cuts the graph up to a given vertex and sorts the resulting subgraph.\\\"\\\"\\\"\\n    try:\\n        stop_or_start_vertex = graph[vertex_id]\\n    except KeyError as e:\\n        if parent_node_map is None:\\n            msg = \\\"Parent node map is required to find the root of a group node\\\"\\n            raise ValueError(msg) from e\\n        vertex_id = get_root_of_group_node(graph=graph, vertex_id=vertex_id, parent_node_map=parent_node_map)\\n        if vertex_id not in graph:\\n            msg = f\\\"Vertex {vertex_id} not found into graph\\\"\\n            raise ValueError(msg) from e\\n        stop_or_start_vertex = graph[vertex_id]\\n\\n    visited, excluded = set(), set()\\n    stack = [vertex_id]\\n    stop_predecessors = set(stop_or_start_vertex[\\\"predecessors\\\"])\\n\\n    while stack:\\n        current_id = stack.pop()\\n        if current_id in visited or current_id in excluded:\\n            continue\\n\\n        visited.add(current_id)\\n        current_vertex = graph[current_id]\\n\\n        stack.extend(current_vertex[\\\"predecessors\\\"])\\n\\n        if current_id == vertex_id or (current_id not in stop_predecessors and is_start):\\n            for successor_id in current_vertex[\\\"successors\\\"]:\\n                if is_start:\\n                    stack.append(successor_id)\\n                else:\\n                    excluded.add(successor_id)\\n                for succ_id in get_successors(graph, successor_id):\\n                    if is_start:\\n                        stack.append(succ_id)\\n                    else:\\n                        excluded.add(succ_id)\\n\\n    return list(visited)\\n\\n\\ndef has_cycle(vertex_ids: list[str], edges: list[tuple[str, str]]) -> bool:\\n    \\\"\\\"\\\"Determines whether a directed graph represented by a list of vertices and edges contains a cycle.\\n\\n    Args:\\n        vertex_ids (list[str]): A list of vertex IDs.\\n        edges (list[tuple[str, str]]): A list of tuples representing directed edges between vertices.\\n\\n    Returns:\\n        bool: True if the graph contains a cycle, False otherwise.\\n    \\\"\\\"\\\"\\n    # Build the graph as an adjacency list\\n    graph = defaultdict(list)\\n    for u, v in edges:\\n        graph[u].append(v)\\n\\n    # Utility function to perform DFS\\n    def dfs(v, visited, rec_stack) -> bool:\\n        visited.add(v)\\n        rec_stack.add(v)\\n\\n        for neighbor in graph[v]:\\n            if neighbor not in visited:\\n                if dfs(neighbor, visited, rec_stack):\\n                    return True\\n            elif neighbor in rec_stack:\\n                return True\\n\\n        rec_stack.remove(v)\\n        return False\\n\\n    visited: set[str] = set()\\n    rec_stack: set[str] = set()\\n\\n    return any(vertex not in visited and dfs(vertex, visited, rec_stack) for vertex in vertex_ids)\\n\\n\\ndef find_cycle_edge(entry_point: str, edges: list[tuple[str, str]]) -> tuple[str, str]:\\n    \\\"\\\"\\\"Find the edge that causes a cycle in a directed graph starting from a given entry point.\\n\\n    Args:\\n        entry_point (str): The vertex ID from which to start the search.\\n        edges (list[tuple[str, str]]): A list of tuples representing directed edges between vertices.\\n\\n    Returns:\\n        tuple[str, str]: A tuple representing the edge that causes a cycle, or None if no cycle is found.\\n    \\\"\\\"\\\"\\n    # Build the graph as an adjacency list\\n    graph = defaultdict(list)\\n    for u, v in edges:\\n        graph[u].append(v)\\n\\n    # Utility function to perform DFS\\n    def dfs(v, visited, rec_stack):\\n        visited.add(v)\\n        rec_stack.add(v)\\n\\n        for neighbor in graph[v]:\\n            if neighbor not in visited:\\n                result = dfs(neighbor, visited, rec_stack)\\n                if result:\\n                    return result\\n            elif neighbor in rec_stack:\\n                return (v, neighbor)  # This edge causes the cycle\\n\\n        rec_stack.remove(v)\\n        return None\\n\\n    visited: set[str] = set()\\n    rec_stack: set[str] = set()\\n\\n    return dfs(entry_point, visited, rec_stack)\\n\\n\\ndef find_all_cycle_edges(entry_point: str, edges: list[tuple[str, str]]) -> list[tuple[str, str]]:\\n    \\\"\\\"\\\"Find all edges that cause cycles in a directed graph starting from a given entry point.\\n\\n    Args:\\n        entry_point (str): The vertex ID from which to start the search.\\n        edges (list[tuple[str, str]]): A list of tuples representing directed edges between vertices.\\n\\n    Returns:\\n        list[tuple[str, str]]: A list of tuples representing edges that cause cycles.\\n    \\\"\\\"\\\"\\n    # Build the graph as an adjacency list\\n    graph = defaultdict(list)\\n    for u, v in edges:\\n        graph[u].append(v)\\n\\n    # Utility function to perform DFS\\n    def dfs(v, visited, rec_stack, cycle_edges):\\n        visited.add(v)\\n        rec_stack.add(v)\\n\\n        for neighbor in graph[v]:\\n            if neighbor not in visited:\\n                dfs(neighbor, visited, rec_stack, cycle_edges)\\n            elif neighbor in rec_stack:\\n                cycle_edges.append((v, neighbor))  # This edge causes a cycle\\n\\n        rec_stack.remove(v)\\n\\n    visited: set[str] = set()\\n    rec_stack: set[str] = set()\\n    cycle_edges: list[tuple[str, str]] = []\\n\\n    dfs(entry_point, visited, rec_stack, cycle_edges)\\n\\n    return cycle_edges\\n\\n\\ndef should_continue(yielded_counts: dict[str, int], max_iterations: int | None) -> bool:\\n    if max_iterations is None:\\n        return True\\n    return max(yielded_counts.values(), default=0) <= max_iterations\\n\\n\\ndef find_cycle_vertices(edges):\\n    graph = nx.DiGraph(edges)\\n\\n    # Initialize a set to collect vertices part of any cycle\\n    cycle_vertices = set()\\n\\n    # Utilize the strong component feature in NetworkX to find cycles\\n    for component in nx.strongly_connected_components(graph):\\n        if len(component) > 1 or graph.has_edge(tuple(component)[0], tuple(component)[0]):  # noqa: RUF015\\n            cycle_vertices.update(component)\\n\\n    return sorted(cycle_vertices)\\n\\n\\ndef layered_topological_sort(\\n    vertices_ids: set[str],\\n    in_degree_map: dict[str, int],\\n    successor_map: dict[str, list[str]],\\n    predecessor_map: dict[str, list[str]],\\n    start_id: str | None = None,\\n    cycle_vertices: set[str] | None = None,\\n    is_input_vertex: Callable[[str], bool] | None = None,  # noqa: ARG001\\n    *,\\n    is_cyclic: bool = False,\\n) -> list[list[str]]:\\n    \\\"\\\"\\\"Performs a layered topological sort of the vertices in the graph.\\n\\n    Args:\\n        vertices_ids: Set of vertex IDs to sort\\n        in_degree_map: Map of vertex IDs to their in-degree\\n        successor_map: Map of vertex IDs to their successors\\n        predecessor_map: Map of vertex IDs to their predecessors\\n        is_cyclic: Whether the graph is cyclic\\n        start_id: ID of the start vertex (if any)\\n        cycle_vertices: Set of vertices that form a cycle\\n        is_input_vertex: Function to check if a vertex is an input vertex\\n\\n    Returns:\\n        List of layers, where each layer is a list of vertex IDs\\n    \\\"\\\"\\\"\\n    # Queue for vertices with no incoming edges\\n    cycle_vertices = cycle_vertices or set()\\n    in_degree_map = in_degree_map.copy()\\n\\n    if is_cyclic and all(in_degree_map.values()):\\n        # This means we have a cycle because all vertex have in_degree_map > 0\\n        # because of this we set the queue to start on the start_id if it exists\\n        if start_id is not None:\\n            queue = deque([start_id])\\n            # Reset in_degree for start_id to allow cycle traversal\\n            in_degree_map[start_id] = 0\\n        else:\\n            # Find the chat input component\\n            chat_input = find_start_component_id(vertices_ids)\\n            if chat_input is None:\\n                # If no input component is found, start with any vertex\\n                queue = deque([next(iter(vertices_ids))])\\n                in_degree_map[next(iter(vertices_ids))] = 0\\n            else:\\n                queue = deque([chat_input])\\n                # Reset in_degree for chat_input to allow cycle traversal\\n                in_degree_map[chat_input] = 0\\n    else:\\n        # Start with vertices that have no incoming edges or are input vertices\\n        queue = deque(\\n            vertex_id\\n            for vertex_id in vertices_ids\\n            if in_degree_map[vertex_id] == 0\\n            # We checked if it is input but that caused the TextInput to be at the start\\n            # or (is_input_vertex and is_input_vertex(vertex_id))\\n        )\\n\\n    layers: list[list[str]] = []\\n    visited = set()\\n    cycle_counts = dict.fromkeys(vertices_ids, 0)\\n    current_layer = 0\\n\\n    # Process the first layer separately to avoid duplicates\\n    if queue:\\n        layers.append([])  # Start the first layer\\n        first_layer_vertices = set()\\n        layer_size = len(queue)\\n        for _ in range(layer_size):\\n            vertex_id = queue.popleft()\\n            if vertex_id not in first_layer_vertices:\\n                first_layer_vertices.add(vertex_id)\\n                visited.add(vertex_id)\\n                cycle_counts[vertex_id] += 1\\n                layers[current_layer].append(vertex_id)\\n\\n            for neighbor in successor_map[vertex_id]:\\n                # only vertices in `vertices_ids` should be considered\\n                # because vertices by have been filtered out\\n                # in a previous step. All dependencies of theirs\\n                # will be built automatically if required\\n                if neighbor not in vertices_ids:\\n                    continue\\n\\n                in_degree_map[neighbor] -= 1  # 'remove' edge\\n                if in_degree_map[neighbor] == 0:\\n                    queue.append(neighbor)\\n\\n                # if > 0 it might mean not all predecessors have added to the queue\\n                # so we should process the neighbors predecessors\\n                elif in_degree_map[neighbor] > 0:\\n                    for predecessor in predecessor_map[neighbor]:\\n                        if (\\n                            predecessor not in queue\\n                            and predecessor not in first_layer_vertices\\n                            and (in_degree_map[predecessor] == 0 or predecessor in cycle_vertices)\\n                        ):\\n                            queue.append(predecessor)\\n\\n        current_layer += 1  # Next layer\\n\\n    # Process remaining layers normally, allowing cycle vertices to appear multiple times\\n    while queue:\\n        layers.append([])  # Start a new layer\\n        layer_size = len(queue)\\n        for _ in range(layer_size):\\n            vertex_id = queue.popleft()\\n            if vertex_id not in visited or (is_cyclic and cycle_counts[vertex_id] < MAX_CYCLE_APPEARANCES):\\n                if vertex_id not in visited:\\n                    visited.add(vertex_id)\\n                cycle_counts[vertex_id] += 1\\n                layers[current_layer].append(vertex_id)\\n\\n            for neighbor in successor_map[vertex_id]:\\n                # only vertices in `vertices_ids` should be considered\\n                # because vertices by have been filtered out\\n                # in a previous step. All dependencies of theirs\\n                # will be built automatically if required\\n                if neighbor not in vertices_ids:\\n                    continue\\n\\n                in_degree_map[neighbor] -= 1  # 'remove' edge\\n                if in_degree_map[neighbor] == 0 and neighbor not in visited:\\n                    queue.append(neighbor)\\n                    # # If this is a cycle vertex, reset its in_degree to allow it to appear again\\n                    # if neighbor in cycle_vertices and neighbor in visited:\\n                    #     in_degree_map[neighbor] = len(predecessor_map[neighbor])\\n\\n                # if > 0 it might mean not all predecessors have added to the queue\\n                # so we should process the neighbors predecessors\\n                elif in_degree_map[neighbor] > 0:\\n                    for predecessor in predecessor_map[neighbor]:\\n                        if predecessor not in queue and (\\n                            predecessor not in visited\\n                            or (is_cyclic and cycle_counts[predecessor] < MAX_CYCLE_APPEARANCES)\\n                        ):\\n                            queue.append(predecessor)\\n\\n        current_layer += 1  # Next layer\\n\\n    # Remove empty layers\\n    return [layer for layer in layers if layer]\\n\\n\\ndef refine_layers(\\n    initial_layers: list[list[str]],\\n    successor_map: dict[str, list[str]],\\n) -> list[list[str]]:\\n    \\\"\\\"\\\"Refines the layers of vertices to ensure proper dependency ordering.\\n\\n    Args:\\n        initial_layers: Initial layers of vertices\\n        successor_map: Map of vertex IDs to their successors\\n\\n    Returns:\\n        Refined layers with proper dependency ordering\\n    \\\"\\\"\\\"\\n    # Map each vertex to its current layer\\n    vertex_to_layer: dict[str, int] = {}\\n    for layer_index, layer in enumerate(initial_layers):\\n        for vertex in layer:\\n            vertex_to_layer[vertex] = layer_index\\n\\n    refined_layers: list[list[str]] = [[] for _ in initial_layers]  # Start with empty layers\\n    new_layer_index_map = defaultdict(int)\\n\\n    # Map each vertex to its new layer index\\n    # by finding the lowest layer index of its dependencies\\n    # and subtracting 1\\n    # If a vertex has no dependencies, it will be placed in the first layer\\n    # If a vertex has dependencies, it will be placed in the lowest layer index of its dependencies\\n    # minus 1\\n    for vertex_id, deps in successor_map.items():\\n        indexes = [vertex_to_layer[dep] for dep in deps if dep in vertex_to_layer]\\n        new_layer_index = max(min(indexes, default=0) - 1, 0)\\n        new_layer_index_map[vertex_id] = new_layer_index\\n\\n    for layer_index, layer in enumerate(initial_layers):\\n        for vertex_id in layer:\\n            # Place the vertex in the highest possible layer where its dependencies are met\\n            new_layer_index = new_layer_index_map[vertex_id]\\n            if new_layer_index > layer_index:\\n                refined_layers[new_layer_index].append(vertex_id)\\n                vertex_to_layer[vertex_id] = new_layer_index\\n            else:\\n                refined_layers[layer_index].append(vertex_id)\\n\\n    # Remove empty layers if any\\n    return [layer for layer in refined_layers if layer]\\n\\n\\ndef _max_dependency_index(\\n    vertex_id: str,\\n    index_map: dict[str, int],\\n    get_vertex_successors: Callable[[str], list[str]],\\n) -> int:\\n    \\\"\\\"\\\"Finds the highest index a given vertex's dependencies occupy in the same layer.\\n\\n    Args:\\n        vertex_id: ID of the vertex to check\\n        index_map: Map of vertex IDs to their indices in the layer\\n        get_vertex_successors: Function to get the successor IDs of a vertex\\n\\n    Returns:\\n        The highest index of the vertex's dependencies\\n    \\\"\\\"\\\"\\n    max_index = -1\\n    for successor_id in get_vertex_successors(vertex_id):\\n        successor_index = index_map.get(successor_id, -1)\\n        max_index = max(successor_index, max_index)\\n    return max_index\\n\\n\\ndef _sort_single_layer_by_dependency(\\n    layer: list[str],\\n    get_vertex_successors: Callable[[str], list[str]],\\n) -> list[str]:\\n    \\\"\\\"\\\"Sorts a single layer by dependency using a stable sorting method.\\n\\n    Args:\\n        layer: List of vertex IDs in the layer\\n        get_vertex_successors: Function to get the successor IDs of a vertex\\n\\n    Returns:\\n        Sorted list of vertex IDs\\n    \\\"\\\"\\\"\\n    # Build a map of each vertex to its index in the layer for quick lookup.\\n    index_map = {vertex: index for index, vertex in enumerate(layer)}\\n    dependency_cache: dict[str, int] = {}\\n\\n    # Track vertices currently being processed to detect intra-layer cycles.\\n    # This can occur when cycle vertices (identified by find_cycle_vertices earlier)\\n    # end up in the same layer after layered_topological_sort. This is expected\\n    # behavior for cyclic graphs, not a failure of earlier cycle detection.\\n    processing: set[str] = set()\\n\\n    def max_dependency_index(vertex: str) -> int:\\n        if vertex in dependency_cache:\\n            return dependency_cache[vertex]\\n\\n        # Intra-layer cycle detection: if we're already processing this vertex,\\n        # we have a cycle within this layer (e.g., A -> B -> A where both are in the same layer).\\n        # This happens when cycle vertices from the graph end up grouped in the same layer.\\n        # We break the cycle by returning the vertex's current index.\\n        if vertex in processing:\\n            logger.debug(f\\\"Intra-layer cycle detected at vertex '{vertex}' during layer sorting, breaking cycle\\\")\\n            return index_map[vertex]\\n\\n        processing.add(vertex)\\n        max_index = index_map[vertex]\\n        for successor in get_vertex_successors(vertex):\\n            if successor in index_map:\\n                max_index = max(max_index, max_dependency_index(successor))\\n\\n        processing.remove(vertex)\\n        dependency_cache[vertex] = max_index\\n        return max_index\\n\\n    return sorted(layer, key=max_dependency_index, reverse=True)\\n\\n\\ndef sort_layer_by_dependency(\\n    vertices_layers: list[list[str]],\\n    get_vertex_successors: Callable[[str], list[str]],\\n) -> list[list[str]]:\\n    \\\"\\\"\\\"Sorts the vertices in each layer by dependency, ensuring no vertex depends on a subsequent vertex.\\n\\n    Args:\\n        vertices_layers: List of layers, where each layer is a list of vertex IDs\\n        get_vertex_successors: Function to get the successor IDs of a vertex\\n\\n    Returns:\\n        Sorted layers\\n    \\\"\\\"\\\"\\n    return [_sort_single_layer_by_dependency(layer, get_vertex_successors) for layer in vertices_layers]\\n\\n\\ndef sort_chat_inputs_first(\\n    vertices_layers: list[list[str]],\\n    get_vertex_predecessors: Callable[[str], list[str]],\\n) -> list[list[str]]:\\n    \\\"\\\"\\\"Sorts the vertices so that chat inputs come first in the layers.\\n\\n    Only one chat input is allowed in the entire graph.\\n\\n    Args:\\n        vertices_layers: List of layers, where each ";
